            // Función para guardar permisos
            function guardarPermisos() {
                const personaId = document.getElementById('edit_perfil_id').value || currentPersonaId;

                if (!personaId) {
                    Swal.fire({
                        icon: 'error',
                        title: 'Error',
                        text: 'No se encontró el ID de la persona'
                    });
                    return;
                }

                // Recopilar selección jerárquica
                const seleccionJerarquia = { pais: [], area: [], departamento: [], puesto: [] };
                const puestosSeleccionados = [];
                const modulosAsignar = [];
                const modulosEliminar = [];
                const puestosForm = document.getElementById('modal-edit-perfil-puestos-form') || document.getElementById('puestos-form');
                const modulosForm = document.getElementById('modal-edit-perfil-modulos-form') || document.getElementById('modulos-form');
                const checkboxesPuestos = puestosForm ? puestosForm.querySelectorAll('.modal-perfil-modulo-item-cb:checked') : [];
                const checkboxesModulos = modulosForm ? modulosForm.querySelectorAll('input[type="checkbox"]') : [];
                checkboxesPuestos.forEach(cb => {
                    const nivel = (cb.dataset.permNivel || 'puesto').toLowerCase();
                    const idNodo = parseInt(cb.dataset.permNodo || cb.value || '0', 10);
                    if (!idNodo) return;
                    if (seleccionJerarquia[nivel]) {
                        seleccionJerarquia[nivel].push(idNodo);
                    }
                    if (nivel === 'puesto') {
                        puestosSeleccionados.push(idNodo);
                    }
                });
                const switchPais = document.getElementById('perfilAccesoDirectoPaisSwitch');
                if (switchPais && switchPais.checked) {
                    const idNodoPais = parseInt(switchPais.dataset.permNodo || '0', 10);
                    if (idNodoPais > 0) {
                        seleccionJerarquia.pais.push(idNodoPais);
                    }
                }
                checkboxesModulos.forEach(cb => {
                    if (cb.value) {
                        if (cb.checked) {
                            modulosAsignar.push(parseInt(cb.value));
                        } else {
                            modulosEliminar.push(parseInt(cb.value));
                        }
                    }
                });

                Swal.fire({
                    title: 'Guardando cambios...',
                    text: 'Por favor espera',
                    allowOutsideClick: false,
                    didOpen: () => {
                        Swal.showLoading();
                    }
                });

                // Guardar puestos
                fetch('/caphum/guardarPermisosPuestos', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Accept': 'application/json'
                    },
                    body: JSON.stringify({
                        idPersona: parseInt(personaId, 10),
                        puestos: puestosSeleccionados,
                        jerarquia: seleccionJerarquia
                    })
                })
                .then(res => res.json())
                .then(respPuestos => {
                    if (!respPuestos.success) {
                        throw new Error(respPuestos.mensaje || 'Error al guardar puestos');
                    }

                    // Guardar módulos (asignar y eliminar)
                    const promesasModulos = [];

                    // Asignar módulos
                    modulosAsignar.forEach(moduloId => {
                        promesasModulos.push(
                            fetch('/caphum/PerfilCheckBoxEstado', {
                                method: 'POST',
                                headers: {
                                    'Content-Type': 'application/json',
                                    'Accept': 'application/json'
                                },
                                body: JSON.stringify({
                                    idPersona: parseInt(personaId, 10),
                                    modulo_id: moduloId,
                                    asignado: 1
                                })
                            }).then(res => res.json())
                        );
                    });

                    // Eliminar módulos
                    modulosEliminar.forEach(moduloId => {
                        promesasModulos.push(
                            fetch('/caphum/PerfilCheckBoxEstado', {
                                method: 'POST',
                                headers: {
                                    'Content-Type': 'application/json',
                                    'Accept': 'application/json'
                                },
                                body: JSON.stringify({
                                    idPersona: parseInt(personaId, 10),
                                    modulo_id: moduloId,
                                    asignado: 0
                                })
                            }).then(res => res.json())
                        );
                    });

                    return Promise.all(promesasModulos);
                })
                .then(() => {
                    Swal.fire({
                        icon: 'success',
                        title: 'Cambios guardados',
                        text: `Se guardaron ${puestosSeleccionados.length} puesto(s) y ${modulosAsignar.length} módulo(s) correctamente`,
                        timer: 2000,
                        showConfirmButton: false
                    }).then(() => {
                        const modalEl = document.getElementById('modalEditPerfil');
                        const modal = bootstrap.Modal.getInstance(modalEl);
                        if (modal) modal.hide();

                        // Recargar la tabla si es necesario
                        if (typeof getUsuarios === 'function') {
                            getUsuarios();
                        }
                    });
                })
                .catch(err => {
                    console.error('Error:', err);
                    Swal.fire({
                        icon: 'error',
                        title: 'Error al guardar',
                        text: err.message || 'Ocurrió un error al guardar los cambios'
                    });
                });
            }

            /* =========================
               RENDER MÃ“DULOS (agrupados como menú lateral; datos menu_* vienen del backend)
            ========================= */
            function normalizarTextoPermisoModal(s) {
                return String(s || '')
                    .normalize('NFD')
                    .replace(/[\u0300-\u036f]/g, '')
                    .toLowerCase()
                    .trim();
            }

            function esGrupoCierreDeCreditoModal(grupoNombre) {
                const n = normalizarTextoPermisoModal(grupoNombre);
                return n.includes('cierre') && n.includes('credito');
            }

            /** Celulas / Cartera bajo tarjeta Convenios: iconos contextuales. */
            function esModuloCierreCelulaCarteraEnGrupoConveniosModal(grupoNombre, mod) {
                if (normalizarTextoPermisoModal(grupoNombre) !== 'convenios') return false;
                const id = Number(mod?.modulo_id ?? mod?.id ?? 0);
                if (id === 56 || id === 57 || id === 59 || id === 92) return true;
                const lab = normalizarTextoPermisoModal(mod?.modulo_nombre || '');
                if (lab.includes('descargar') && lab.includes('excel')) return true;
                if (!lab.includes('cierre')) return false;
                return lab.includes('despachos') || lab.includes('call center') || lab.includes('cartera');
            }

            /** Las 4 pestañas de Cierre de crédito en permisos especiales (Convenios, Validación, En proceso, Historial). */
            function esFilaCuatroPestanasCierreCredito(displayLabel) {
                const lab = normalizarTextoPermisoModal(displayLabel);
                if (!lab) return false;
                if (lab === 'convenios' || lab === 'convenio') return true;
                if (lab.includes('validacion') && lab.includes('cierre')) return true;
                if (lab === 'en proceso') return true;
                if (lab === 'historial') return true;
                if (lab.includes('despachos') || lab.includes('celula despachos')) return true;
                if (lab.includes('call center') || lab.includes('celula call center')) return true;
                if (lab.includes('cartera')) return true;
                if (lab.includes('descargar') && lab.includes('excel')) return true;
                return false;
            }

            /** Icono dentro del cuadro (misma UI que otras tarjetas de permisos especiales). */
            function iconoCuadroCierreCreditoPermisoEsp(displayLabel) {
                const lab = normalizarTextoPermisoModal(displayLabel);
                if (lab === 'convenios' || lab === 'convenio') return 'fa-solid fa-handshake';
                if (lab.includes('validacion') && lab.includes('cierre')) return 'fa-solid fa-clipboard-check';
                if (lab === 'en proceso') return 'fa-solid fa-list-check';
                if (lab === 'historial') return 'fa-solid fa-clock-rotate-left';
                if (lab.includes('despachos') || lab.includes('celula despachos')) return 'fa-solid fa-building';
                if (lab.includes('call center') || lab.includes('celula call center')) return 'fa-solid fa-headset';
                if (lab.includes('cartera')) return 'fa-solid fa-briefcase';
                if (lab.includes('descargar') && lab.includes('excel')) return 'fa-solid fa-file-excel';
                return null;
            }

            function buildFilaModuloSistema(mod, displayLabel, iconosModulos, ctx) {
                ctx = ctx || {};
                const grupoNombre = ctx.grupoNombre != null ? String(ctx.grupoNombre) : '';
                const iconosCierrePorEtiqueta = !!ctx.iconosCierreCreditoPorEtiquetaPermisosEsp;

                const tr = document.createElement('tr');
                tr.className = 'modal-perfil-modulo-fila';
                tr.style.transition = 'all 0.3s ease';
                tr.style.cursor = 'pointer';
                tr.style.borderLeft = '3px solid transparent';
                tr.style.borderBottom = '1px solid #e9ecef';

                tr.onmouseenter = () => {
                    tr.style.backgroundColor = '#f8f9fa';
                    tr.style.borderLeftColor = '#495057';
                    tr.style.transform = 'translateX(4px)';
                };
                tr.onmouseleave = () => {
                    tr.style.backgroundColor = '';
                    tr.style.borderLeftColor = 'transparent';
                    tr.style.transform = 'translateX(0)';
                };

                const tdName = document.createElement('td');
                tdName.className = 'fw-medium';
                tdName.style.padding = '0.875rem 0.875rem 0.875rem 1.75rem';
                tdName.style.verticalAlign = 'middle';

                const nombreDiv = document.createElement('div');
                nombreDiv.style.display = 'flex';
                nombreDiv.style.alignItems = 'center';
                nombreDiv.style.gap = '0.75rem';

                const modId = mod.modulo_id != null ? mod.modulo_id : mod.id;
                let iconClass = iconosModulos[modId] || iconosModulos[Number(modId)] || 'fa fa-cube';
                if (iconosCierrePorEtiqueta
                    && (esGrupoCierreDeCreditoModal(grupoNombre) || esModuloCierreCelulaCarteraEnGrupoConveniosModal(grupoNombre, mod))
                    && esFilaCuatroPestanasCierreCredito(displayLabel || mod.modulo_nombre)) {
                    const icEsp = iconoCuadroCierreCreditoPermisoEsp(displayLabel || mod.modulo_nombre);
                    if (icEsp) iconClass = icEsp;
                }
                const iconoModulo = document.createElement('div');
                iconoModulo.className = 'modulo-icon-box';
                iconoModulo.style.width = '40px';
                iconoModulo.style.height = '40px';
                iconoModulo.style.borderRadius = '10px';
                iconoModulo.style.background = 'rgba(26, 82, 168, 0.12)';
                iconoModulo.style.border = '1px solid rgba(26, 82, 168, 0.25)';
                iconoModulo.style.display = 'flex';
                iconoModulo.style.alignItems = 'center';
                iconoModulo.style.justifyContent = 'center';
                iconoModulo.style.flexShrink = '0';

                const iconoInner = document.createElement('i');
                iconoInner.className = iconClass;
                iconoInner.style.color = '#1A52A8';
                iconoInner.style.fontSize = '1rem';
                iconoInner.title = displayLabel || mod.modulo_nombre || '';
                iconoModulo.appendChild(iconoInner);

                const nombre = document.createElement('span');
                nombre.innerText = displayLabel || mod.modulo_nombre || 'Módulo';
                nombre.style.fontWeight = '600';
                nombre.style.color = '#2c3e50';
                nombre.style.fontSize = '0.95rem';

                nombreDiv.appendChild(iconoModulo);
                nombreDiv.appendChild(nombre);

                const descRaw = String(mod.descripcion || '');
                const descParts = descRaw.split('>').map(s => s.trim()).filter(Boolean);
                if (descParts.length >= 3) {
                    const badgeGrupoInterno = document.createElement('span');
                    badgeGrupoInterno.className = 'badge bg-label-info rounded-pill px-2 py-1';
                    badgeGrupoInterno.style.fontSize = '0.65rem';
                    badgeGrupoInterno.style.fontWeight = '700';
                    badgeGrupoInterno.style.whiteSpace = 'nowrap';
                    badgeGrupoInterno.textContent = 'Dentro de: ' + descParts[1];
                    nombreDiv.appendChild(badgeGrupoInterno);
                }

                const desc = document.createElement('small');
                desc.className = 'text-muted d-block mt-1';
                desc.style.fontSize = '0.75rem';
                desc.innerText = descRaw;

                tdName.append(nombreDiv, desc);

                const tdCheck = document.createElement('td');
                tdCheck.className = 'text-end';
                tdCheck.style.padding = '0.875rem';
                tdCheck.style.verticalAlign = 'middle';
                tdCheck.style.width = '130px';

                const divCheck = document.createElement('div');
                divCheck.className = 'form-check mb-0';
                divCheck.style.display = 'flex';
                divCheck.style.alignItems = 'center';
                divCheck.style.justifyContent = 'flex-end';
                divCheck.style.gap = '0.5rem';

                const checkbox = document.createElement('input');
                checkbox.type = 'checkbox';
                checkbox.className = 'form-check-input modal-perfil-modulo-item-cb';
                checkbox.checked = Number(mod.asignado_flag) === 1;
                checkbox.value = mod.modulo_id;
                checkbox.style.cursor = 'pointer';
                checkbox.style.width = '1.1em';
                checkbox.style.height = '1.1em';

                const label = document.createElement('label');
                label.className = 'form-check-label';
                label.innerHTML = checkbox.checked
                    ? '<span class="badge bg-success rounded-pill px-3 py-1"><i class="fa fa-check me-1"></i>Asignado</span>'
                    : '<span class="badge bg-secondary rounded-pill px-3 py-1">Asignar</span>';
                label.style.cursor = 'pointer';
                label.style.userSelect = 'none';
                label.addEventListener('click', function(ev) {
                    ev.preventDefault();
                    checkbox.click();
                });

                checkbox.addEventListener('change', function() {
                    updateModuloCheckboxLabel(this);
                    onModuloChange(this);
                });

                divCheck.append(checkbox, label);
                tdCheck.appendChild(divCheck);

                tr.append(tdName, tdCheck);
                return tr;
            }

            /**
             * Tarjetas agrupadas por menu_grupo (misma UI en Â«Módulos del sistemaÂ» y Â«Permisos especialesÂ»).
             * @param {{ masterIdPrefix: string, iconosMap: Object, emptyHtml: string, collapseGrupos?: boolean, collapseIdPrefix?: string, iconosCierreCreditoPorEtiquetaPermisosEsp?: boolean, actualizarBotonExpandir?: () => void }} opts
             */
            function renderAgrupadoPorMenuGrupo(perfiles, container, opts) {
                const masterIdPrefix = opts.masterIdPrefix;
                const iconosMap = opts.iconosMap;
                const emptyHtml = opts.emptyHtml;
                const useCollapseGrupos = !!opts.collapseGrupos;
                const collapseIdPrefix = opts.collapseIdPrefix || 'modal-perfil-grupo';
                const iconosCierreCreditoPorEtiquetaPermisosEsp = !!opts.iconosCierreCreditoPorEtiquetaPermisosEsp;
                const actualizarBotonExpandirFn = (typeof opts.actualizarBotonExpandir === 'function')
                    ? opts.actualizarBotonExpandir
                    : function() {};
                if (!container) return;
                container.innerHTML = '';
                container.classList.add('modal-perfil-modulos-agrupados');

                if (!perfiles || perfiles.length === 0) {
                    container.innerHTML = emptyHtml;
                    return;
                }

                const grupos = new Map();
                const nombresGrupo = [];
                perfiles.forEach(m => {
                    const g = (m.menu_grupo != null && String(m.menu_grupo).trim() !== '') ? String(m.menu_grupo).trim() : 'Otros';
                    if (!grupos.has(g)) {
                        grupos.set(g, {
                            icono: m.menu_grupo_icono || 'fa-solid fa-folder',
                            orden: Number(m.menu_grupo_orden),
                            items: []
                        });
                        if (!Number.isFinite(grupos.get(g).orden)) grupos.get(g).orden = 999;
                        nombresGrupo.push(g);
                    }
                    grupos.get(g).items.push(m);
                });

                nombresGrupo.sort((a, b) => {
                    const oa = grupos.get(a).orden;
                    const ob = grupos.get(b).orden;
                    if (oa !== ob) return oa - ob;
                    return a.localeCompare(b, 'es');
                });

                nombresGrupo.forEach((gName, grupoIdx) => {
                    const g = grupos.get(gName);
                    g.items.sort((a, b) => {
                        const ia = Number(a.menu_item_orden);
                        const ib = Number(b.menu_item_orden);
                        if (Number.isFinite(ia) && Number.isFinite(ib) && ia !== ib) return ia - ib;
                        return (Number(a.modulo_id) || 0) - (Number(b.modulo_id) || 0);
                    });

                    const section = document.createElement('section');
                    section.className = 'modal-perfil-modulo-grupo card mb-0 shadow-sm';
                    section.style.border = '2px solid #000';
                    section.style.borderRadius = '0.5rem';
                    section.style.overflow = 'hidden';

                    const header = document.createElement('div');
                    header.className = 'modal-perfil-modulo-grupo-header px-3 py-2 d-flex align-items-center flex-wrap gap-2 fw-semibold';
                    header.style.background = 'rgba(26, 82, 168, 0.08)';
                    header.style.borderBottom = '2px solid #000';

                    const masterWrap = document.createElement('div');
                    masterWrap.className = 'd-flex align-items-center gap-2 ms-auto flex-shrink-0 modal-perfil-modulo-master-wrap';
                    const masterCb = document.createElement('input');
                    masterCb.type = 'checkbox';
                    masterCb.className = 'form-check-input modal-perfil-modulo-master-cb';
                    masterCb.id = masterIdPrefix + grupoIdx;
                    masterCb.setAttribute('data-grupo-nombre', gName);
                    masterCb.setAttribute('data-grupo-tipo', 'modulos');
                    masterCb.style.cursor = 'pointer';
                    const masterLbl = document.createElement('label');
                    masterLbl.className = 'form-check-label small text-secondary mb-0 modal-perfil-modulo-master-label';
                    masterLbl.setAttribute('for', masterCb.id);
                    masterLbl.style.cursor = 'pointer';
                    masterWrap.appendChild(masterLbl);
                    masterWrap.appendChild(masterCb);

                    const hi = document.createElement('i');
                    hi.className = (g.icono || 'fa-solid fa-folder') + ' me-2 text-primary';
                    hi.style.flexShrink = '0';
                    const ht = document.createElement('span');
                    ht.className = 'flex-grow-1 min-w-0';
                    ht.style.color = '#1e293b';
                    ht.textContent = gName + ' (' + g.items.length + ')';

                    let collapseId = '';
                    if (useCollapseGrupos) {
                        collapseId = collapseIdPrefix + '-collapse-' + grupoIdx;
                        header.classList.add('modal-perfil-modulo-grupo-toggle');
                        header.style.cursor = 'pointer';
                        header.setAttribute('role', 'button');
                        header.setAttribute('tabindex', '0');
                        header.setAttribute('aria-expanded', 'true');
                        header.setAttribute('aria-controls', collapseId);
                        header.setAttribute('data-bs-toggle', 'collapse');
                        header.setAttribute('data-bs-target', '#' + collapseId);

                        const stopToggle = (e) => { e.stopPropagation(); };
                        masterWrap.addEventListener('click', stopToggle);
                        masterWrap.addEventListener('mousedown', stopToggle);

                        const chevron = document.createElement('i');
                        chevron.className = 'fa fa-chevron-down modal-perfil-modulo-grupo-chevron text-primary';
                        chevron.style.flexShrink = '0';
                        chevron.style.fontSize = '0.75rem';
                        chevron.style.transition = 'transform 0.2s ease';
                        chevron.style.transform = 'rotate(0deg)';
                        chevron.setAttribute('aria-hidden', 'true');

                        header.appendChild(chevron);
                        header.appendChild(hi);
                        header.appendChild(ht);
                        header.appendChild(masterWrap);

                        header.addEventListener('keydown', function(ev) {
                            if (ev.key === 'Enter' || ev.key === ' ') {
                                ev.preventDefault();
                                const el = document.getElementById(collapseId);
                                if (!el) return;
                                if (typeof bootstrap !== 'undefined' && bootstrap.Collapse) {
                                    bootstrap.Collapse.getOrCreateInstance(el).toggle();
                                } else {
                                    el.classList.toggle('show');
                                    const open = el.classList.contains('show');
                                    header.setAttribute('aria-expanded', open ? 'true' : 'false');
                                    const ch = header.querySelector('.modal-perfil-modulo-grupo-chevron');
                                    if (ch) ch.style.transform = open ? 'rotate(0deg)' : 'rotate(-90deg)';
                                    actualizarBotonExpandirFn();
                                }
                            }
                        });
                    } else {
                        header.appendChild(hi);
                        header.appendChild(ht);
                        header.appendChild(masterWrap);
                    }

                    const table = document.createElement('table');
                    table.className = 'table table-hover mb-0';
                    table.style.fontSize = '0.9rem';

                    const tbody = document.createElement('tbody');
                    g.items.forEach(mod => {
                        const nombreModulo = mod.modulo_nombre != null ? String(mod.modulo_nombre).trim() : '';
                        const lbl = nombreModulo !== ''
                            ? nombreModulo
                            : ((mod.menu_item_label != null && String(mod.menu_item_label).trim() !== '')
                                ? String(mod.menu_item_label).trim()
                                : 'Módulo');
                        tbody.appendChild(buildFilaModuloSistema(mod, lbl, iconosMap, {
                            grupoNombre: gName,
                            iconosCierreCreditoPorEtiquetaPermisosEsp: iconosCierreCreditoPorEtiquetaPermisosEsp,
                        }));
                    });

                    table.appendChild(tbody);

                    masterCb.addEventListener('change', function() {
                        const want = this.checked;
                        this.indeterminate = false;
                        const cbs = [...tbody.querySelectorAll('.modal-perfil-modulo-item-cb')];
                        const toToggle = cbs.filter(cb => cb.checked !== want);
                        if (toToggle.length === 0) {
                            syncGrupoModuloMaster(masterCb, tbody);
                            return;
                        }
                        masterCb.disabled = true;
                        let chain = Promise.resolve(true);
                        toToggle.forEach(cb => {
                            chain = chain.then((ok) => {
                                if (!ok) return false;
                                cb.checked = want;
                                updateModuloCheckboxLabel(cb);
                                return onModuloChange(cb, { silent: true });
                            });
                        });
                        chain
                            .then((ok) => {
                                if (ok) {
                                    Swal.fire({
                                        icon: 'success',
                                        title: 'Grupo actualizado',
                                        text: 'Los permisos del grupo se guardaron correctamente.',
                                        timer: 1600,
                                        showConfirmButton: false,
                                        customClass: { container: 'swal-sobre-modal-perfil' }
                                    });
                                }
                                if (typeof getUsuarios === 'function') getUsuarios({ showLoader: false });
                            })
                            .finally(() => {
                                masterCb.disabled = false;
                                syncGrupoModuloMaster(masterCb, tbody);
                            });
                    });

                    syncGrupoModuloMaster(masterCb, tbody);

                    if (useCollapseGrupos) {
                        const collapse = document.createElement('div');
                        collapse.id = collapseId;
                        collapse.className = 'collapse show modal-perfil-modulo-grupo-collapse';

                        const syncChevron = (open) => {
                            header.setAttribute('aria-expanded', open ? 'true' : 'false');
                            const ch = header.querySelector('.modal-perfil-modulo-grupo-chevron');
                            if (ch) ch.style.transform = open ? 'rotate(0deg)' : 'rotate(-90deg)';
                        };
                        collapse.addEventListener('shown.bs.collapse', () => {
                            syncChevron(true);
                            actualizarBotonExpandirFn();
                        });
                        collapse.addEventListener('hidden.bs.collapse', () => {
                            syncChevron(false);
                            actualizarBotonExpandirFn();
                        });

                        syncChevron(true);

                        collapse.appendChild(table);
                        section.appendChild(header);
                        section.appendChild(collapse);
                    } else {
                        section.appendChild(header);
                        section.appendChild(table);
                    }

                    container.appendChild(section);
                });

                if (useCollapseGrupos) {
                    actualizarBotonExpandirFn();
                }
            }

            function renderPermisosEspeciales(perfiles) {
                const container = document.getElementById('modal-edit-perfil-permisos-especiales-form') || document.getElementById('permisos-especiales-form');
                const iconosMap = Object.assign({}, iconosModulosSistemaPerfil, iconosPermisosEspeciales);
                const idsPermisoEdicionCobranza = new Set(Array.from({ length: 21 }, (_, i) => 107 + i));
                const perfilesNormalizados = (Array.isArray(perfiles) ? perfiles : []).map(mod => {
                    const idMod = Number(mod.modulo_id ?? mod.id ?? 0);
                    if (!idsPermisoEdicionCobranza.has(idMod)) {
                        return mod;
                    }
                    return Object.assign({}, mod, {
                        menu_grupo: 'Permiso edici\u00f3n cobranza',
                        menu_grupo_icono: 'fa-solid fa-pen-to-square',
                        menu_grupo_orden: 12,
                        menu_item_orden: idMod
                    });
                });
                renderAgrupadoPorMenuGrupo(perfilesNormalizados, container, {
                    masterIdPrefix: 'modal-perfil-perm-esp-master-',
                    iconosMap: iconosMap,
                    emptyHtml: '<p class="text-muted small mb-0">No hay permisos especiales configurados.</p>',
                    collapseGrupos: true,
                    collapseIdPrefix: 'modal-perfil-perm-esp',
                    iconosCierreCreditoPorEtiquetaPermisosEsp: true,
                    actualizarBotonExpandir: actualizarBotonExpandirPermisosEspeciales,
                });
            }

            function renderModulos(perfiles) {
                const container = document.getElementById('modal-edit-perfil-modulos-form') || document.getElementById('modulos-form');
                renderAgrupadoPorMenuGrupo(perfiles, container, {
                    masterIdPrefix: 'modal-perfil-modulo-master-',
                    iconosMap: iconosModulosSistemaPerfil,
                    emptyHtml: '<div class="text-muted small text-center py-4">No hay módulos disponibles</div>',
                    collapseGrupos: true,
                    collapseIdPrefix: 'modal-perfil-modulos-tab',
                    actualizarBotonExpandir: actualizarBotonExpandirModulosSistema,
                });
            }

            let bajaSubordinadosActuales = [];
            let bajaPersonasSustitutoActuales = [];
            let bajaVacantesMismoPuestoActuales = [];
            let bajaAsignacionesJefe = {};

            function bajaEscapeHtml(value) {
                return String(value || '')
                    .replace(/&/g, '&amp;')
                    .replace(/</g, '&lt;')
                    .replace(/>/g, '&gt;')
                    .replace(/"/g, '&quot;')
                    .replace(/'/g, '&#039;');
            }

            function resetBajaReasignacion() {
                bajaSubordinadosActuales = [];
                bajaPersonasSustitutoActuales = [];
                bajaVacantesMismoPuestoActuales = [];
                bajaAsignacionesJefe = {};
                const count = document.getElementById('bajaSubordinadosCount');
                const lista = document.getElementById('bajaSubordinadosLista');
                const vacantesMismoPuesto = document.getElementById('bajaVacantesMismoPuesto');
                const buscarSubordinado = document.getElementById('bajaBuscarSubordinado');
                const resumenAsignaciones = document.getElementById('bajaResumenAsignacionesJefe');
                const wrap = document.getElementById('bajaReasignacionWrap');
                const sustitutoWrap = document.getElementById('bajaSustitutoWrap');
                const sustituto = document.getElementById('bajaSustitutoId');
                const modoVacante = document.getElementById('bajaModoVacante');
                if (sustituto && typeof window.jQuery !== 'undefined' && window.jQuery.fn.select2) {
                    const $sustituto = window.jQuery(sustituto);
                    if ($sustituto.hasClass('select2-hidden-accessible')) $sustituto.select2('destroy');
                }
                if (count) count.textContent = '0';
                if (lista) lista.innerHTML = '<div class="list-group-item text-muted">Cargando subordinados...</div>';
                if (vacantesMismoPuesto) vacantesMismoPuesto.innerHTML = '';
                if (buscarSubordinado) buscarSubordinado.value = '';
                if (resumenAsignaciones) resumenAsignaciones.innerHTML = '';
                if (wrap) wrap.style.display = 'none';
                if (sustitutoWrap) sustitutoWrap.style.display = 'none';
                if (sustituto) sustituto.innerHTML = '<option value="">Cargando personas...</option>';
                if (modoVacante) modoVacante.checked = true;
                actualizarVistaReasignacionBaja();
            }

            function actualizarVistaReasignacionBaja() {
                const modoSeleccionado = document.querySelector('input[name="bajaModoReasignacion"]:checked');
                const modo = modoSeleccionado ? modoSeleccionado.value : 'vacante';
                const detalleSubordinados = document.getElementById('bajaSubordinadosDetalleWrap');
                const vacanteResumen = document.getElementById('bajaVacanteResumen');
                const sustitutoWrap = document.getElementById('bajaSustitutoWrap');
                const count = document.getElementById('bajaSubordinadosCount');

                if (detalleSubordinados) detalleSubordinados.classList.toggle('d-none', modo !== 'sustituto');
                if (vacanteResumen) vacanteResumen.classList.toggle('d-none', modo !== 'vacante');
                if (sustitutoWrap) sustitutoWrap.style.display = modo === 'sustituto' ? 'block' : 'none';
                if (count) {
                    count.textContent = modo === 'vacante'
                        ? String(bajaVacantesMismoPuestoActuales.length)
                        : String(Math.max(0, bajaSubordinadosActuales.length - Object.keys(bajaAsignacionesJefe).length));
                }
            }

            function renderBajaSubordinados(subordinados) {
                bajaSubordinadosActuales = Array.isArray(subordinados) ? subordinados : [];
                const count = document.getElementById('bajaSubordinadosCount');
                const lista = document.getElementById('bajaSubordinadosLista');
                const wrap = document.getElementById('bajaReasignacionWrap');
                if (!lista || !wrap) return;

                if (!bajaSubordinadosActuales.length) {
                    lista.innerHTML = '<div class="list-group-item text-muted">Esta persona no tiene subordinados directos activos.</div>';
                    wrap.style.display = 'none';
                    return;
                }

                lista.innerHTML = bajaSubordinadosActuales.map(function (s) {
                    const nombre = bajaEscapeHtml(s.nombre_completo || ('ID ' + s.id));
                    const puesto = bajaEscapeHtml(s.nombre_puesto || 'Sin puesto');
                    const departamento = bajaEscapeHtml(s.nombre_departamento || 'Sin departamento');
                    const externalId = bajaEscapeHtml(s.numero_empleado || s.id);
                    const textoBusqueda = bajaEscapeHtml((externalId + ' ' + nombre + ' ' + puesto + ' ' + departamento).toLowerCase());
                    return '<label class="list-group-item d-flex align-items-start gap-2 bg-transparent baja-subordinado-row mb-0" data-search="' + textoBusqueda + '">'
                        + '<input class="form-check-input mt-1 baja-subordinado-check" type="checkbox" value="' + bajaEscapeHtml(s.id) + '" checked>'
                        + '<span class="min-w-0 d-block">'
                        + '<span class="badge bg-label-secondary text-secondary rounded-pill mb-1">#' + externalId + '</span>'
                        + '<span class="fw-semibold text-body text-truncate d-block">' + nombre + '</span>'
                        + '<span class="text-muted text-truncate d-block">' + puesto + ' - ' + departamento + '</span>'
                        + '<span class="badge bg-label-secondary text-secondary rounded-pill mt-1 baja-jefe-asignado" data-subordinado-id="' + bajaEscapeHtml(s.id) + '">Sin jefe destino</span>'
                        + '</span>'
                        + '</label>';
                }).join('');
                wrap.style.display = 'block';
                actualizarVistaReasignacionBaja();
                filtrarBajaSubordinados();
            }

            function renderBajaSustitutos(personas, idPersonaBaja) {
                const personasUnicas = [];
                const vistos = new Set();
                (Array.isArray(personas) ? personas : []).forEach(function (p) {
                    if (!p || p.id == null) return;
                    const id = String(p.id);
                    if (vistos.has(id)) return;
                    vistos.add(id);
                    personasUnicas.push(p);
                });
                bajaPersonasSustitutoActuales = personasUnicas;
                const select = document.getElementById('bajaSustitutoId');
                if (!select) return;
                if (typeof window.jQuery !== 'undefined' && window.jQuery.fn.select2) {
                    const $select = window.jQuery(select);
                    if ($select.hasClass('select2-hidden-accessible')) $select.select2('destroy');
                }
                select.innerHTML = '<option value="">Selecciona sustituto</option>';
                bajaPersonasSustitutoActuales.forEach(function (p) {
                    if (String(p.id) === String(idPersonaBaja)) return;
                    const opt = document.createElement('option');
                    opt.value = p.id;
                    opt.textContent = (p.nombre_completo || ('ID ' + p.id)) + (p.nombre_puesto ? ' - ' + p.nombre_puesto : '');
                    select.appendChild(opt);
                });
                if (typeof window.refreshSelectBuscador === 'function') window.refreshSelectBuscador('bajaSustitutoId');
            }

            function getNombreBajaSustituto(idPersona) {
                const persona = bajaPersonasSustitutoActuales.find(function (p) {
                    return String(p.id) === String(idPersona);
                });
                return persona ? (persona.nombre_completo || ('ID ' + persona.id)) : ('ID ' + idPersona);
            }

            function actualizarBadgesAsignacionJefe() {
                document.querySelectorAll('.baja-jefe-asignado').forEach(function (badge) {
                    const idSubordinado = badge.dataset.subordinadoId;
                    const jefeId = bajaAsignacionesJefe[idSubordinado];
                    const row = badge.closest('.baja-subordinado-row');
                    const check = row ? row.querySelector('.baja-subordinado-check') : null;
                    if (!jefeId) {
                        badge.className = 'badge bg-label-secondary text-secondary rounded-pill mt-1 baja-jefe-asignado';
                        badge.textContent = 'Sin jefe destino';
                        if (row) row.classList.remove('bg-light');
                        if (check) check.disabled = false;
                        return;
                    }
                    badge.className = 'badge bg-label-primary text-primary rounded-pill mt-1 baja-jefe-asignado';
                    badge.textContent = 'Jefe: ' + getNombreBajaSustituto(jefeId);
                    if (row) row.classList.add('bg-light');
                    if (check) {
                        check.checked = false;
                        check.disabled = true;
                    }
                });
                renderResumenAsignacionesJefe();
                actualizarVistaReasignacionBaja();
            }

            function renderResumenAsignacionesJefe() {
                const cont = document.getElementById('bajaResumenAsignacionesJefe');
                if (!cont) return;
                const grupos = {};
                Object.keys(bajaAsignacionesJefe).forEach(function (idSubordinado) {
                    const jefeId = bajaAsignacionesJefe[idSubordinado];
                    if (!jefeId) return;
                    if (!grupos[jefeId]) grupos[jefeId] = [];
                    grupos[jefeId].push(idSubordinado);
                });

                const idsJefe = Object.keys(grupos);
                if (!idsJefe.length) {
                    cont.innerHTML = '<div class="badge bg-label-secondary text-secondary rounded-pill">Sin grupos asignados</div>';
                    return;
                }

                cont.innerHTML = '<div class="d-flex flex-column gap-1">'
                    + idsJefe.map(function (jefeId) {
                        return '<div class="d-flex justify-content-between align-items-center gap-2 rounded border bg-body px-2 py-1 small">'
                            + '<span class="text-truncate">' + bajaEscapeHtml(getNombreBajaSustituto(jefeId)) + '</span>'
                            + '<span class="d-flex align-items-center gap-1 flex-shrink-0">'
                            + '<span class="badge bg-primary rounded-pill">' + grupos[jefeId].length + '</span>'
                            + '<button type="button" class="btn btn-sm btn-outline-danger px-2 py-0 baja-quitar-asignacion" data-jefe-id="' + bajaEscapeHtml(jefeId) + '" title="Quitar asignacion">'
                            + '<i class="fa-solid fa-xmark"></i>'
                            + '</button>'
                            + '</span>'
                            + '</div>';
                    }).join('')
                    + '</div>';
            }

            function quitarAsignacionJefeBaja(jefeId) {
                Object.keys(bajaAsignacionesJefe).forEach(function (idSubordinado) {
                    if (String(bajaAsignacionesJefe[idSubordinado]) === String(jefeId)) {
                        delete bajaAsignacionesJefe[idSubordinado];
                    }
                });
                actualizarBadgesAsignacionJefe();
            }

            function aplicarJefeASeleccionadosBaja() {
                const select = document.getElementById('bajaSustitutoId');
                const jefeId = select ? select.value : '';
                if (!jefeId) {
                    Swal.fire('Atencion', 'Selecciona un jefe destino.', 'warning');
                    return;
                }

                const seleccionados = Array.from(document.querySelectorAll('.baja-subordinado-check:checked'));
                if (!seleccionados.length) {
                    Swal.fire('Atencion', 'Selecciona al menos una persona para asignar jefe.', 'warning');
                    return;
                }

                seleccionados.forEach(function (chk) {
                    bajaAsignacionesJefe[chk.value] = jefeId;
                });
                actualizarBadgesAsignacionJefe();
                const input = document.getElementById('bajaBuscarSubordinado');
                if (input) input.value = '';
                filtrarBajaSubordinados();
            }

            function renderBajaVacantesMismoPuesto(vacantes, puestoBaja) {
                bajaVacantesMismoPuestoActuales = Array.isArray(vacantes) ? vacantes : [];
                const cont = document.getElementById('bajaVacantesMismoPuesto');
                if (!cont) return;

                const puesto = puestoBaja && puestoBaja.nombre_puesto ? bajaEscapeHtml(puestoBaja.nombre_puesto) : 'este puesto';
                if (!bajaVacantesMismoPuestoActuales.length) {
                    cont.innerHTML = '<div class="badge bg-label-secondary text-secondary rounded-pill">No hay vacantes activas para ' + puesto + '</div>';
                    actualizarVistaReasignacionBaja();
                    return;
                }

                cont.innerHTML = '<div class="fw-semibold mb-2">Vacantes activas para ' + puesto + '</div>'
                    + '<div class="list-group list-group-flush rounded border bg-body">'
                    + bajaVacantesMismoPuestoActuales.map(function (v, idx) {
                        const departamento = bajaEscapeHtml(v.nombre_departamento || 'Sin departamento');
                        const jefe = bajaEscapeHtml(v.nombre_jefe || 'Sin jefe asignado');
                        return '<label class="list-group-item small bg-transparent d-flex align-items-start gap-2 mb-0">'
                            + '<input class="form-check-input mt-1 baja-vacante-check" type="checkbox" value="' + bajaEscapeHtml(v.id) + '"' + (idx === 0 ? ' checked' : '') + '>'
                            + '<span class="min-w-0 d-block">'
                            + '<span class="fw-semibold text-body d-block">Vacante #' + bajaEscapeHtml(v.id) + '</span>'
                            + '<span class="text-muted text-truncate d-block">' + departamento + '</span>'
                            + '<span class="text-muted text-truncate d-block">Jefe: ' + jefe + '</span>'
                            + '</span>'
                            + '</label>';
                    }).join('')
                    + '</div>';
                actualizarVistaReasignacionBaja();
            }

            function filtrarBajaSubordinados() {
                const input = document.getElementById('bajaBuscarSubordinado');
                const filtro = input ? input.value.trim().toLowerCase() : '';
                document.querySelectorAll('#bajaSubordinadosLista .baja-subordinado-row').forEach(function (row) {
                    row.classList.toggle('d-none', filtro !== '' && !(row.dataset.search || '').includes(filtro));
                });
            }

            function cargarDatosReasignacionBaja(idPersona) {
                resetBajaReasignacion();
                fetch('/CapHum/getDatosReasignacionBaja', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Accept': 'application/json'
                    },
                    body: JSON.stringify({ idPersona: idPersona })
                })
                .then(res => res.json())
                .then(data => {
                    if (!data.success) {
                        renderBajaSubordinados([]);
                        return;
                    }
                    renderBajaSubordinados(data.datos && data.datos.subordinados ? data.datos.subordinados : []);
                    renderBajaSustitutos(data.datos && data.datos.personas ? data.datos.personas : [], idPersona);
                    renderBajaVacantesMismoPuesto(
                        data.datos && data.datos.vacantes_mismo_puesto ? data.datos.vacantes_mismo_puesto : [],
                        data.datos && data.datos.puesto_baja ? data.datos.puesto_baja : null
                    );
                })
                .catch(err => {
                    console.error('Error al cargar reasignacion de baja:', err);
                    renderBajaSubordinados([]);
                });
            }

            document.addEventListener('change', function (ev) {
                if (!ev.target) return;
                if (ev.target.name === 'bajaModoReasignacion') {
                    actualizarVistaReasignacionBaja();
                    return;
                }
                if (ev.target.classList && ev.target.classList.contains('baja-vacante-check') && ev.target.checked) {
                    document.querySelectorAll('.baja-vacante-check').forEach(function (chk) {
                        if (chk !== ev.target) chk.checked = false;
                    });
                }
                if (ev.target.classList && ev.target.classList.contains('baja-subordinado-check') && !ev.target.checked) {
                    delete bajaAsignacionesJefe[ev.target.value];
                    actualizarBadgesAsignacionJefe();
                }
            });

            document.addEventListener('input', function (ev) {
                if (ev.target && ev.target.id === 'bajaBuscarSubordinado') filtrarBajaSubordinados();
            });

            document.addEventListener('click', function (ev) {
                if (ev.target && ev.target.id === 'bajaAplicarJefeSeleccionados') aplicarJefeASeleccionadosBaja();
                const quitar = ev.target && ev.target.closest ? ev.target.closest('.baja-quitar-asignacion') : null;
                if (quitar) {
                    quitarAsignacionJefeBaja(quitar.dataset.jefeId);
                }
            });

            function baja_gestor(id) {
                    if (!id) {
                        Swal.fire("Error", "ID inválido", "error");
                        return;
                    }

                    // Limpiar campos del modal antes de cargar nueva información
                    document.getElementById("motivoBaja").value = "";
                    document.getElementById("motivoBajaDescripcion").value = "";
                    document.getElementById("archivoPDF").value = "";
                    document.getElementById("listaArchivos").innerHTML = "";
                    document.getElementById("listaArchivos").style.display = "none";
                    const spanBaja = document.getElementById("bajaModal_nombreArchivo");
                    if (spanBaja) spanBaja.textContent = "No se ha seleccionado ningún archivo";
                    archivosSeleccionados = [];
                    document.getElementById("gestor").innerHTML = "<strong>Gestor:</strong> ";
                    resetBajaReasignacion();

                    fetch('/CapHum/getDetalles', {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'Accept': 'application/json'
                        },
                        body: JSON.stringify({
                            idPersona: id
                        })
                    })
                    .then(res => res.json())
                    .then(data => {
                        if (!data.success) {
                            Swal.fire("Error", data.mensaje, "error");
                            return;
                        }

                       const persona = data.datos && data.datos.persona ? data.datos.persona : data.datos;
                        if (!persona || !persona.id) {
                            Swal.fire("Error", "No se encontraron datos de la persona.", "error");
                            return;
                        }
                        document.getElementById("edit_id").value = persona.id;
                        // Concatenar el nombre completo en el <p id="gestor">
                        document.getElementById("gestor").innerHTML = "<strong>Gestor:</strong> " + persona.nombres + " " + persona.apellidop + " " + persona.apellidom;

                        cargarDatosReasignacionBaja(persona.id);

                        $("#modalBajas").modal("show");
                    })
                    .catch(err => {
                        console.error('FETCH ERROR:', err);
                        Swal.fire("Error", "No se pudo cargar la información", "error");
                    });
        }

            function registra_ausencia(id) {
                if (!id) {
                    Swal.fire("Error", "ID inválido", "error");
                    return;
                }

                fetch('/CapHum/getDetalles', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Accept': 'application/json'
                    },
                    body: JSON.stringify({
                        idPersona: id
                    })
                })
                .then(res => res.json())
                .then(resp => {

                    if (!resp.success) {
                        Swal.fire("Error", resp.mensaje, "error");
                        return;
                    }

                    const persona = resp.datos && resp.datos.persona ? resp.datos.persona : resp.datos;
                    if (!persona || !persona.id) {
                        Swal.fire("Error", "No se encontraron datos de la persona.", "error");
                        return;
                    }

                    // ID oculto
                    document.getElementById("edit_id_ausencia").value = persona.id;

                    // Nombre del gestor
                    document.getElementById("gestor_ausencia").innerHTML =
                        `<strong>Gestor:</strong> ${persona.nombres} ${persona.apellidop} ${persona.apellidom}`;

                    // Limpiar formulario
                    document.getElementById("razonAusencia").value = "";
                    document.getElementById("fechaInicio").value = "";
                    document.getElementById("fechaFin").value = "";
                    document.getElementById("descripcionAusencia").value = "";

                    // Cargar catálogo y tabla
                    cargarRazones();
                    cargarAusencias(persona.id);

                    // Mostrar modal correcto
                    $("#modalAuscencia").modal("show");
                })
                .catch(err => {
                    console.error('FETCH ERROR:', err);
                    Swal.fire("Error", "No se pudo cargar la información", "error");
                });
