            function initFlatpickrAusencia() {
                var inpInicio = document.getElementById("fechaInicio");
                var inpFin = document.getElementById("fechaFin");
                if (!inpInicio || !inpFin || typeof flatpickr === "undefined") return;
                if (inpInicio._flatpickr) return;
                var opts = {
                    enableTime: true,
                    dateFormat: "Y-m-d H:i",
                    time_24hr: true,
                    allowInput: false,
                    clickOpens: true,
                    appendTo: document.body,
                    disableMobile: true,
                    locale: "es",
                    static: false,
                    onReady: function(selectedDates, dateStr, instance) {
                        if (instance && instance.calendarContainer) {
                            instance.calendarContainer.classList.add("ausencia-flatpickr-calendar");
                        }
                    },
                    onOpen: function(selectedDates, dateStr, instance) {
                        if (instance && instance.calendarContainer) {
                            instance.calendarContainer.classList.add("ausencia-flatpickr-calendar");
                        }
                    }
                };
                flatpickr(inpInicio, opts);
                flatpickr(inpFin, opts);
            }

            function cargarAusencias(idPersona) {
            fetch('/CapHum/getAusenciasPersona', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Accept': 'application/json'
                },
                body: JSON.stringify({
                    idPersona: idPersona
                })
            })
            .then(res => res.json())
            .then(resp => {

                if (!resp.success) {
                    Swal.fire("Error", resp.mensaje, "error");
                    return;
                }

                const tbody = document.getElementById("tablaAusencias");
                tbody.innerHTML = "";

                const data = resp.datos;

                if (!Array.isArray(data) || data.length === 0) {
                    tbody.innerHTML = `
                        <tr>
                            <td colspan="5" class="text-center text-muted">
                                Sin registros
                            </td>
                        </tr>`;
                    return;
                }

                data.forEach(a => {
                    tbody.innerHTML += `
                        <tr>
                            <td>${a.razon}</td>
                            <td>${a.fecha_inicio}</td>
                            <td>${a.fecha_fin}</td>
                            <td>${a.descripcion ?? ''}</td>
                            <td>${a.activo == 1 ? 'Sí' : 'No'}</td>
                             <td class="text-center">
                                <button class="btn btn-sm btn-warning"
                                    onclick="editarAusencia(${a.id})"
                                    title="Editar / Documentos">
                                    <i class="fa fa-edit"></i>
                                </button>
                            </td>
                        </tr>
                    `;
                });
            })
            .catch(err => {
                console.error("ERROR cargarAusencias:", err);
            });
        }

           function cargarRazones() {

                fetch('/CapHum/getRazonesAusencia')
                    .then(res => res.json())
                    .then(resp => {

                        if (!resp.success) {
                            Swal.fire("Error", resp.mensaje, "error");
                            return;
                        }

                        if (!Array.isArray(resp.datos)) {
                            console.error("resp.datos no es array", resp);
                            return;
                        }

                        const select = document.getElementById('razonAusencia');
                        select.innerHTML = '<option value="">-- Selecciona --</option>';

                        resp.datos.forEach(r => {
                            select.innerHTML += `
                                <option value="${r.id}">${r.nombre}</option>
                            `;
                        });
                    })
                    .catch(err => {
                        console.error("ERROR cargarRazones:", err);
                    });
            }

           function editarAusencia(idAusencia) {
                if (!idAusencia) {
                    Swal.fire("Error", "Id de ausencia inválido", "error");
                    return;
                }

                fetch('/CapHum/getAusenciaById', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Accept': 'application/json'
                    },
                    body: JSON.stringify({ idAusencia: idAusencia })
                })
                .then(res => res.json())
                .then(resp => {

                    if (!resp.success) {
                        Swal.fire("Error", resp.mensaje, "error");
                        return;
                    }

                    const a = resp.datos;

                    // ðŸ¹ Modo edición
                    document.getElementById("id_ausencia").value = a.id;
                    document.getElementById("razonAusencia").value = a.id_razon;

                    // ðŸ¹ Fechas formato Flatpickr (Y-m-d H:i)
                    var fi = (a.fecha_inicio || '').toString().substring(0, 16);
                    var ff = (a.fecha_fin || '').toString().substring(0, 16);
                    document.getElementById("fechaInicio").value = fi;
                    document.getElementById("fechaFin").value = ff;
                    if (document.getElementById("fechaInicio")._flatpickr) document.getElementById("fechaInicio")._flatpickr.setDate(fi, false);
                    if (document.getElementById("fechaFin")._flatpickr) document.getElementById("fechaFin")._flatpickr.setDate(ff, false);

                    document.getElementById("descripcionAusencia").value = a.descripcion || '';

                    // ðŸ¹ Cambiar texto del botón
                    document.getElementById("btnGuardarAusencia").innerText = "Actualizar ausencia";

                    // ðŸ¹ Cargar documentos asociados
                    //cargarDocumentosAusencia(a.id);

                    // ðŸ¹ Mostrar modal
                    $("#modalAusencia").modal("show");
                })
                .catch(err => {
                    console.error("ERROR editarAusencia:", err);
                    Swal.fire("Error", "No se pudo cargar la ausencia", "error");
                });
            }

            function limpiarFormularioAusencia() {
                document.getElementById("id_ausencia").value = '';
                document.getElementById("razonAusencia").value = '';
                var elInicio = document.getElementById("fechaInicio");
                var elFin = document.getElementById("fechaFin");
                if (elInicio) { elInicio.value = ''; if (elInicio._flatpickr) elInicio._flatpickr.clear(); }
                if (elFin) { elFin.value = ''; if (elFin._flatpickr) elFin._flatpickr.clear(); }
                document.getElementById("descripcionAusencia").value = '';

                // Texto del botón
                document.getElementById("btnGuardarAusencia").innerText = "Guardar ausencia";

                // Texto del gestor (opcional)
                const gestor = document.getElementById("gestor");
                if (gestor) {
                    gestor.innerHTML = "<strong>Gestor:</strong>";
                }
            }


           function guardarAusencia() {

                const idAusencia = document.getElementById("id_ausencia").value;
                const idPersona   = document.getElementById("edit_id_ausencia").value;
                const idRazon     = document.getElementById("razonAusencia").value;
                const fechaInicio = document.getElementById("fechaInicio").value;
                const fechaFin    = document.getElementById("fechaFin").value;
                const descripcion = document.getElementById("descripcionAusencia").value;

                const payload = {
                    idPersona,
                    idRazon,
                    fechaInicio,
                    fechaFin,
                    descripcion,
                    idAusencia
                };


                fetch('/CapHum/guardarAusencia', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Accept': 'application/json'
                    },
                    body: JSON.stringify(payload)
                })
                .then(res => res.json())
                .then(resp => {

                    if (!resp.success) {
                        Swal.fire("Error", resp.mensaje, "error");
                        return;
                    }

                    Swal.fire("Ã‰xito", resp.mensaje, "success");

                    $("#modalAusencia").modal("hide");

                    // Limpieza
                    document.getElementById("id_ausencia").value = '';
                    document.getElementById("btnGuardarAusencia").innerText = "Guardar ausencia";

                    //  LIMPIEZA CENTRALIZADA
                    limpiarFormularioAusencia();
                    // Refrescar tabla
                    cargarAusencias(idPersona);
                })
                .catch(err => {
                    console.error("ERROR guardarAusencia:", err);
                    Swal.fire("Error", "No se pudo guardar la ausencia", "error");
                });
            }




           function confirmarBaja() {
                const idGestor = document.getElementById("edit_id").value;
                const motivoSelect = document.getElementById("motivoBaja").value;
                const descripcion = document.getElementById("motivoBajaDescripcion").value;
                const tieneSubordinados = bajaSubordinadosActuales.length > 0;
                const modoReasignacionEl = document.querySelector('input[name="bajaModoReasignacion"]:checked');
                const modoReasignacion = modoReasignacionEl
                    ? modoReasignacionEl.value
                    : (tieneSubordinados ? 'vacante' : 'sin_subordinados');
                const sustitutoSelect = document.getElementById("bajaSustitutoId");
                const sustitutoId = sustitutoSelect ? sustitutoSelect.value : "";
                const subordinadosSeleccionados = modoReasignacion === 'sustituto'
                    ? Object.keys(bajaAsignacionesJefe)
                    : Array.from(document.querySelectorAll('.baja-subordinado-check:checked')).map(chk => chk.value);
                const vacanteSeleccionada = document.querySelector('.baja-vacante-check:checked');
                const vacanteExistenteId = vacanteSeleccionada ? vacanteSeleccionada.value : "";
                const asignacionesJefe = {};
                Object.keys(bajaAsignacionesJefe).forEach(function (idSubordinado) {
                    if (bajaAsignacionesJefe[idSubordinado]) {
                        asignacionesJefe[idSubordinado] = bajaAsignacionesJefe[idSubordinado];
                    }
                });
                const pendientesAsignacion = modoReasignacion === 'sustituto'
                    ? bajaSubordinadosActuales.length - Object.keys(bajaAsignacionesJefe).length
                    : 0;
                const tieneVacantesActivasParaPuesto = Array.isArray(bajaVacantesMismoPuestoActuales)
                    && bajaVacantesMismoPuestoActuales.length > 0;

                // Validaciones
                if (!motivoSelect) {
                    Swal.fire({
                        icon: 'warning',
                        title: 'Atención',
                        text: 'Debes seleccionar un motivo de baja.'
                    });
                    return;
                }

                if (descripcion.trim() === "") {
                    Swal.fire({
                        icon: 'warning',
                        title: 'Atención',
                        text: 'Debes escribir la descripción de la baja.'
                    });
                    return;
                }

                if (modoReasignacion === 'sustituto' && pendientesAsignacion > 0) {
                    Swal.fire({
                        icon: 'warning',
                        title: 'Atencion',
                        text: 'Aun quedan ' + pendientesAsignacion + ' persona(s) sin jefe destino.'
                    });
                    return;
                }

                if (modoReasignacion === 'vacante' && tieneVacantesActivasParaPuesto && !vacanteExistenteId) {
                    Swal.fire({
                        icon: 'warning',
                        title: 'Selecciona una vacante',
                        text: 'Ya existe una vacante activa para este puesto. Selecciona la vacante disponible antes de confirmar la baja.'
                    });
                    return;
                }

                const sinVacantesActivasParaPuesto = !Array.isArray(bajaVacantesMismoPuestoActuales)
                    || bajaVacantesMismoPuestoActuales.length === 0;
                const crearVacanteAutomatica = modoReasignacion === 'vacante' && sinVacantesActivasParaPuesto;
                const tituloConfirmacion = crearVacanteAutomatica
                    ? 'Confirmar baja y crear vacante'
                    : '¿Confirmar baja?';
                const mensajeConfirmacion = crearVacanteAutomatica
                    ? '<div class="text-start">'
                        + '<p>Se dará de baja a esta persona.</p>'
                        + '<p class="mb-0">No hay una vacante activa para este puesto. Al confirmar, el sistema creará una vacante nueva automáticamente para conservar esa posición disponible.</p>'
                        + '</div>'
                    : 'Esta acción no se puede deshacer.';

                // Confirmación antes de enviar
                Swal.fire({
                    title: tituloConfirmacion,
                    html: mensajeConfirmacion,
                    icon: 'question',
                    showCancelButton: true,
                    confirmButtonText: 'Sí, confirmar baja',
                    cancelButtonText: 'Cancelar',
                    reverseButtons: true
                }).then((result) => {
                    if (result.isConfirmed) {

                        //  Crear FormData
                        const formData = new FormData();
                        formData.append("idGestor", idGestor);
                        formData.append("motivo", motivoSelect);
                        formData.append("descripcion", descripcion);
                        formData.append("modo_reasignacion", modoReasignacion);
                        formData.append("sustituto_id", sustitutoId);
                        formData.append("subordinados_seleccionados", JSON.stringify(subordinadosSeleccionados));
                        formData.append("asignaciones_jefe", JSON.stringify(asignacionesJefe));
                        formData.append("vacante_existente_id", vacanteExistenteId);

                        // ðŸ“Ž Archivos múltiples (AQU EST EL CAMBIO)
                        archivosSeleccionados.forEach(file => {
                            formData.append('archivosPDF[]', file);
                        });

                        //  Deshabilitar botón para evitar doble envío
                        const btnBajaConfirmar = document.querySelector('#modalBajas .btn-danger');
                        if (btnBajaConfirmar) { btnBajaConfirmar.disabled = true; btnBajaConfirmar.textContent = 'Procesando...'; }

                        //  Enviar al controlador
                        fetch('/CapHum/registrarBaja', {
                            method: 'POST',
                            body: formData
                        })
                        .then(response => response.json())
                        .then(data => {
                            if (data.success) {
                                const legacyBaja = data.datos && data.datos.legacy_sync ? data.datos.legacy_sync : null;
                                const legacyResultado = legacyBaja ? String(legacyBaja.resultado || '').toLowerCase() : '';
                                const legacyMensaje = legacyBaja && legacyBaja.mensaje ? String(legacyBaja.mensaje) : '';
                                let legacyHtml = '';
                                if (legacyBaja) {
                                    const legacyOk = legacyResultado !== 'error';
                                    const legacyBadge = legacyResultado === 'sin_cambios'
                                        ? 'bg-info'
                                        : (legacyResultado === 'omitido' ? 'bg-secondary' : (legacyOk ? 'bg-success' : 'bg-warning text-dark'));
                                    const legacyEstado = legacyResultado === 'sin_cambios'
                                        ? 'Legacy ya estaba dado de baja'
                                        : (legacyResultado === 'omitido' ? 'Legacy sin registro activo' : (legacyOk ? 'Legacy dado de baja' : 'Legacy pendiente'));
                                    legacyHtml =
                                        '<div class="text-start">' +
                                            '<div class="mb-2">' + (data.message || 'La baja se registrÃƒÂ³ correctamente.') + '</div>' +
                                            '<span class="badge ' + legacyBadge + '">' + legacyEstado + '</span>' +
                                            (legacyMensaje ? '<div class="small text-muted mt-2">' + legacyMensaje + '</div>' : '') +
                                        '</div>';
                                }
                                Swal.fire({
                                    icon: legacyResultado === 'error' ? 'warning' : 'success',
                                    html: legacyHtml || undefined,
                                    title: '¡Listo!',
                                    text: data.message || 'La baja se registró correctamente.'
                                }).then(() => {
                                    $("#modalBajas").modal("hide");

                                    //  Limpieza
                                    archivosSeleccionados = [];
                                    const listEl = document.getElementById("listaArchivos");
                                    if (listEl) { listEl.innerHTML = ""; listEl.style.display = "none"; }
                                    const spanBajaOk = document.getElementById("bajaModal_nombreArchivo");
                                    if (spanBajaOk) spanBajaOk.textContent = "No se ha seleccionado ningún archivo";

                                    if (typeof getUsuarios === 'function') getUsuarios();
                                    if (typeof getBajas === 'function') getBajas();
                                });
                            } else {
                                if (btnBajaConfirmar) { btnBajaConfirmar.disabled = false; btnBajaConfirmar.textContent = 'Confirmar Baja'; }
                                Swal.fire({
                                    icon: 'error',
                                    title: 'Error',
                                    text: data.message || 'Ocurrió un error al registrar la baja.'
                                });
                            }
                        })
                        .catch(error => {
                            if (btnBajaConfirmar) { btnBajaConfirmar.disabled = false; btnBajaConfirmar.textContent = 'Confirmar Baja'; }
                            console.error("Error:", error);
                            Swal.fire({
                                icon: 'error',
                                title: 'Error',
                                text: 'Ocurrió un error al procesar la baja.'
                            });
                        });
                    }
                });
            }




            function onModuloChange(checkbox, opts) {
                opts = opts || {};
                const silent = !!opts.silent;
                if (!checkbox || currentPersonaId == null) {
                    return Promise.resolve(false);
                }

                const payload = {
                    idPersona: currentPersonaId,
                    modulo_id: checkbox.value,
                    asignado: checkbox.checked ? 1 : 0
                };

                return fetch('/CapHum/PerfilCheckBoxEstado', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Accept': 'application/json'
                    },
                    body: JSON.stringify(payload)
                })
                .then(res => res.json())
                .then(data => {

                    if (!data.success) {
                        checkbox.checked = !checkbox.checked;
                        updateModuloCheckboxLabel(checkbox);
                        syncGrupoModuloMasterFromChild(checkbox);
                        Swal.fire({ icon: 'error', title: 'Error', text: data.mensaje || 'No se pudo actualizar', customClass: { container: 'swal-sobre-modal-perfil' } });
                        return false;
                    }

                    if (!silent) {
                        Swal.fire({
                            icon: 'success',
                            title: checkbox.checked
                                ? 'Asignación correcta'
                                : 'Asignación eliminada',
                            text: checkbox.checked
                                ? 'El módulo fue asignado correctamente'
                                : 'El módulo fue desasignado correctamente',
                            timer: 1600,
                            showConfirmButton: false,
                            customClass: { container: 'swal-sobre-modal-perfil' }
                        });
                        if (typeof getUsuarios === 'function') getUsuarios({ showLoader: false });
                    }
                    syncGrupoModuloMasterFromChild(checkbox);
                    return true;
                })
                .catch(err => {
                    console.error(err);
                    checkbox.checked = !checkbox.checked;
                    updateModuloCheckboxLabel(checkbox);
                    syncGrupoModuloMasterFromChild(checkbox);
                    Swal.fire({ icon: 'error', title: 'Error', text: 'Error de comunicación con el servidor', customClass: { container: 'swal-sobre-modal-perfil' } });
                    return false;
                });
            }

            /** IDs de división (Select2): leer con jQuery.val() para no enviar null si el nativo quedó desincronizado. */
            function leerValorSelectDivision(selectId) {
                var el = document.getElementById(selectId);
                if (!el) return null;
                if (typeof window.jQuery !== 'undefined') {
                    var $e = window.jQuery('#' + selectId);
                    if ($e.length) {
                        var jv = $e.val();
                        if (jv !== null && jv !== undefined && String(jv).trim() !== '') {
                            return String(jv).trim();
                        }
                    }
                }
                var v = el.value;
                return (v !== null && v !== undefined && String(v).trim() !== '') ? String(v).trim() : null;
            }

            function enviarUpdateGestor(payload) {
                Swal.fire({
                    title: 'Actualizando usuario...',
                    html: '<div class="spinner-border text-primary" role="status"><span class="visually-hidden">Cargando...</span></div><p style="margin-top: 1rem;">Guardando cambios y sincronizando con Legacy...</p>',
                    allowOutsideClick: false,
                    allowEscapeKey: false,
                    showConfirmButton: false,
                    didOpen: () => Swal.showLoading()
                });

                fetch('/CapHum/updateGestorF', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                })
                .then(res => res.json())
                .then(data => {
                    if (!data.success) {
                        if (data.datos && data.datos.requiere_resolucion_puesto_anterior) {
                            pedirResolucionPuestoAnterior(data.datos, payload);
                            return;
                        }
                        const detalleErrorUpdate = data.error ? `<div class="text-start mt-2 small text-muted">${String(data.error).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}</div>` : '';
                        Swal.fire({
                            icon: "error",
                            title: "Error",
                            html: `${data.mensaje || 'Error al actualizar persona.'}${detalleErrorUpdate}`
                        });
                        return;
                    }

                    swalGestionUsuarioLegacy(data, {
                        tituloOk: 'Usuario actualizado',
                        tituloPendiente: 'Usuario actualizado, Legacy pendiente',
                        mensajeDefault: 'Gestor actualizado correctamente'
                    }).then(() => {
                        bootstrap.Offcanvas.getInstance(
                            document.getElementById('offcanvasEditUser')
                        ).hide();

                        if (typeof getUsuarios === 'function') getUsuarios();
                    });
                })
                .catch(() => {
                    Swal.fire("Error", "No se pudo actualizar el gestor.", "error");
                });
            }

            function pedirResolucionPuestoAnterior(info, payload) {
                const puestoAnterior = info.puesto_anterior || {};
                const puestoNuevo = info.puesto_nuevo || {};
                const subordinados = Number(info.subordinados_count || 0);
                const sustitutos = Array.isArray(info.sustitutos) ? info.sustitutos : [];
                const escaparHtml = function(valor) {
                    return String(valor || '').replace(/[&<>"']/g, function(c) {
                        return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' })[c];
                    });
                };
                const opcionesSustituto = sustitutos.map(item => {
                    const id = escaparHtml(item.id);
                    const nombre = escaparHtml(item.nombre_completo);
                    const puesto = escaparHtml(item.nombre_puesto);
                    return `<option value="${id}">${nombre}${puesto ? ' - ' + puesto : ''}</option>`;
                }).join('');

                Swal.fire({
                    icon: 'question',
                    title: 'Resolver puesto anterior',
                    html: `
                        <div class="text-start">
                            <p class="mb-2">
                                Al cambiar de <b>${escaparHtml(puestoAnterior.nombre_puesto || 'puesto anterior')}</b>
                                a <b>${escaparHtml(puestoNuevo.nombre_puesto || 'nuevo puesto')}</b>, quedan
                                <b>${subordinados}</b> subordinado(s) ligados al puesto anterior.
                            </p>
                            <p class="mb-3">Elige como se debe cubrir ese puesto antes de guardar el cambio.</p>
                            <label class="form-check border rounded p-3 mb-2">
                                <input class="form-check-input me-2" type="radio" name="resolver_puesto_anterior" value="vacante" checked>
                                <span class="fw-semibold">Crear una vacante</span>
                                <small class="d-block text-muted ms-4">Los subordinados quedaran unidos a la vacante del puesto anterior.</small>
                            </label>
                            <label class="form-check border rounded p-3 mb-2">
                                <input class="form-check-input me-2" type="radio" name="resolver_puesto_anterior" value="sustituto">
                                <span class="fw-semibold">Asignar un sustituto</span>
                                <small class="d-block text-muted ms-4">Los subordinados pasaran a la persona seleccionada.</small>
                            </label>
                            <select id="swal_sustituto_puesto_anterior" class="form-select mt-2" disabled>
                                <option value="">Selecciona un sustituto</option>
                                ${opcionesSustituto}
                            </select>
                        </div>
                    `,
                    showCancelButton: true,
                    confirmButtonText: 'Continuar',
                    cancelButtonText: 'Cancelar',
                    reverseButtons: true,
                    didOpen: () => {
                        const radios = document.querySelectorAll('input[name="resolver_puesto_anterior"]');
                        const select = document.getElementById('swal_sustituto_puesto_anterior');
                        radios.forEach(radio => {
                            radio.addEventListener('change', () => {
                                select.disabled = radio.value !== 'sustituto' || !radio.checked;
                            });
                        });
                    },
                    preConfirm: () => {
                        const modo = document.querySelector('input[name="resolver_puesto_anterior"]:checked')?.value || 'vacante';
                        const sustituto = document.getElementById('swal_sustituto_puesto_anterior')?.value || '';
                        if (modo === 'sustituto' && !sustituto) {
                            Swal.showValidationMessage('Selecciona un sustituto para continuar.');
                            return false;
                        }
                        return { modo, sustituto };
                    }
                }).then(result => {
                    if (!result.isConfirmed || !result.value) return;
                    const nuevoPayload = Object.assign({}, payload, {
                        resolver_puesto_anterior: result.value.modo,
                        id_sustituto_puesto_anterior: result.value.sustituto || null
                    });
                    enviarUpdateGestor(nuevoPayload);
                });
            }

            function UpdateGestor() {
                const esEdicionParcialCobranza = !!window.modoVisualizarConEdicionCobranza;

                let departamento = document.getElementById("edit_departamento_id").value;  // <---- esta es la linea 2009
                let puesto       = document.getElementById("edit_id_puesto").value;
                const jefe         = document.getElementById("edit_id_jefe").value;
                const asignarLegion = document.getElementById("edit_asignar_legion") && document.getElementById("edit_asignar_legion").checked;
                const idLegion     = document.getElementById("edit_id_legion") ? document.getElementById("edit_id_legion").value : '';
                const id_div_nivel1 = leerValorSelectDivision('edit_id_div_nivel1');
                const id_div_nivel2 = leerValorSelectDivision('edit_id_div_nivel2');
                const id_div_nivel3 = leerValorSelectDivision('edit_id_div_nivel3');
                const id_div_nivel4 = leerValorSelectDivision('edit_id_div_nivel4');
                const domicilio_calle_texto = document.getElementById('edit_domicilio_calle_texto')?.value?.trim() || null;
                const domicilio_num_exterior = document.getElementById('edit_domicilio_num_exterior')?.value?.trim() || null;
                const domicilio_num_interior = document.getElementById('edit_domicilio_num_interior')?.value?.trim() || null;
                const codigo_postal = document.getElementById('edit_codigo_postal')?.value?.trim() || null;

                let puestosAdicionales = [];
                if (typeof obtenerPuestosParaGuardar === 'function') {
                    puestosAdicionales = obtenerPuestosParaGuardar();
                }
                const puestosModificados = window.puestosUsuarioModificados === true;
                const puestosEliminados = Array.isArray(window.puestosEliminadosUsuario) ? window.puestosEliminadosUsuario : [];
                const puestoPrincipalOriginal = window.puestoPrincipalOriginalUsuario || null;

                if (Array.isArray(puestosAdicionales) && puestosAdicionales.length > 0) {
                    const puestoPrincipalFinal = puestosAdicionales[0] || {};
                    puesto = puestoPrincipalFinal.id_puesto || puesto;
                    departamento = puestoPrincipalFinal.id_departamento || departamento;
                } else if (puestosModificados) {
                    puesto = '';
                    departamento = '';
                }

                //  VALIDACIONES OBLIGATORIAS
                if (!esEdicionParcialCobranza && !puestosModificados && !departamento) {
                    Swal.fire("Falta información", "Debes seleccionar un departamento", "warning");
                    return;
                }

                if (!esEdicionParcialCobranza && !puestosModificados && !puesto) {
                    Swal.fire("Falta información", "Debes seleccionar un puesto", "warning");
                    return;
                }

                if (!esEdicionParcialCobranza && !jefe) {
                    Swal.fire("Falta información", "Debes seleccionar un jefe", "warning");
                    return;
                }

                if (!esEdicionParcialCobranza && asignarLegion && !idLegion) {
                    Swal.fire("Falta información", "Debes seleccionar una legión", "warning");
                    return;
                }

                const idColoniaEdit = id_div_nivel3 || '';
                const cpEdit = document.getElementById('edit_codigo_postal')?.value?.trim() || '';
                const calleTxtEdit = document.getElementById('edit_domicilio_calle_texto')?.value?.trim() || '';
                const idCalleEdit = id_div_nivel4 || '';
                const capturaDomicilioEdit = !!(idColoniaEdit || cpEdit || calleTxtEdit || idCalleEdit);
                if (!esEdicionParcialCobranza && capturaDomicilioEdit && !domicilio_num_exterior) {
                    Swal.fire("Falta información", "El número exterior es obligatorio cuando captura domicilio (colonia, calle o código postal).", "warning");
                    return;
                }
                var selCalleEdit = document.getElementById('edit_id_div_nivel4');
                if (!esEdicionParcialCobranza && id_div_nivel3 && selCalleEdit && !selCalleEdit.disabled && selCalleEdit.options && selCalleEdit.options.length > 1 && !id_div_nivel4 && !calleTxtEdit) {
                    Swal.fire("Falta información", "Indique la calle: elija una del catálogo o escríbala en el campo de texto (nombre o número, p. ej. Calle 10A).", "warning");
                    return;
                }

                // ðŸ¹ Payload
                const payload = {
                    id: document.getElementById("edit_id").value,
                    numero_empleado: document.getElementById("edit_num_empleado").value,
                    nombres: document.getElementById("edit_nombres").value,
                    segundo_nombre: document.getElementById("edit_segundo_nombre").value,
                    apellidop: document.getElementById("edit_apellidop").value,
                    apellidom: document.getElementById("edit_apellidom").value,
                    curp: document.getElementById("edit_curp")?.value?.trim() || null,
                    telefono: document.getElementById("edit_telefono").value,
                    departamento_id: departamento,
                    puesto_id: puesto,
                    jefe_id: jefe,
                    asignar_legion: asignarLegion,
                    id_legion: asignarLegion ? idLegion : null,
                    usuario: document.getElementById("edit_usuario").value,
                    contrasena: document.getElementById("edit_contrasena").value,
                    puestos_adicionales: puestosAdicionales,
                    puestos_eliminados: puestosEliminados,
                    puesto_principal_original: puestoPrincipalOriginal,
                    id_div_nivel1: id_div_nivel1 || null,
                    id_div_nivel2: id_div_nivel2 || null,
                    id_div_nivel3: id_div_nivel3 || null,
                    id_div_nivel4: id_div_nivel4 || null,
                    domicilio_calle_texto: domicilio_calle_texto,
                    domicilio_num_exterior: domicilio_num_exterior,
                    domicilio_num_interior: domicilio_num_interior,
                    codigo_postal: codigo_postal,
                    modo_edicion_cobranza: esEdicionParcialCobranza ? 'parcial' : 'completa'
                };

                enviarUpdateGestor(payload);
                return;

                fetch('/CapHum/updateGestorF', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                })
                .then(res => res.json())
                .then(data => {
                    if (!data.success) {
                        Swal.fire("Error", data.mensaje, "error");
                        return;
                    }

                    Swal.fire("Ã‰xito", "Gestor actualizado correctamente", "success");

                    bootstrap.Offcanvas.getInstance(
                        document.getElementById('offcanvasEditUser')
                    ).hide();

                    if (typeof getUsuarios === 'function') getUsuarios();
                });
            }


            function handleAddDepartamentoChange() {
                const depEl = document.getElementById('add_departamento_id');
                const idDepartamento = depEl ? depEl.value : '';
                const selectPuesto = document.getElementById('add_id_puesto');
                const selectJefe   = document.getElementById('add_id_jefe');
                if (!selectPuesto || !selectJefe) return;
                // Reset
                selectPuesto.innerHTML = '<option value="">Seleccione un puesto</option>';
                selectPuesto.disabled = true;
                selectJefe.innerHTML = '<option value="">Seleccione un jefe</option>';
                selectJefe.disabled = true;
                resetVacantesAsignablesAdd();
                if (typeof window.refreshSelectBuscador === 'function') {
                    window.refreshSelectBuscador('add_id_puesto');
                    window.refreshSelectBuscador('add_id_jefe');
                }

                if (!idDepartamento) return;

                fetch('/CapHum/getPuestosParaGestor', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id_departamento: idDepartamento })
                })
                .then(res => res.json())
                .then(data => {
                    if (!data.success) {
                        Swal.fire("Error", data.mensaje, "error");
                        return;
                    }
                    const lista = Array.isArray(data.datos) ? data.datos : [];
                    lista.forEach(puesto => {
                        const option = document.createElement('option');
                        option.value = puesto.id;
                        option.textContent = puesto.nombre;
                        selectPuesto.appendChild(option);
                    });
                    selectPuesto.disabled = false;
                    if (typeof window.refreshSelectBuscador === 'function') {
                        window.refreshSelectBuscador('add_id_puesto');
                    }
                    // Cargar jefes del departamento (sin puesto aún: por es_jefe o todas las personas del depto)
                    cargarJefeComboAdd(idDepartamento, null, selectJefe);
                })
                .catch(() => {
                    Swal.fire("Error", "No se pudieron cargar los puestos", "error");
                });
            }

            function resetVacantesAsignablesAdd() {
                const wrap = document.getElementById('add_vacante_wrap');
                const select = document.getElementById('add_vacante_existente_id');
                if (select) {
                    select.innerHTML = '<option value="">Sin vacante seleccionada</option>';
                    select.value = '';
                    select.disabled = true;
                }
                if (wrap) wrap.classList.add('d-none');
                if (typeof window.refreshSelectBuscador === 'function') {
                    window.refreshSelectBuscador('add_vacante_existente_id');
                }
            }

            function aplicarJefeDeVacanteAdd() {
                const selectVacante = document.getElementById('add_vacante_existente_id');
                const selectJefe = document.getElementById('add_id_jefe');
                if (!selectVacante || !selectJefe || !selectVacante.value) return;
                const opt = selectVacante.options[selectVacante.selectedIndex];
                const jefeId = opt ? (opt.dataset.jefeId || '') : '';
                const jefeNombre = opt ? (opt.dataset.jefeNombre || '') : '';
                if (!jefeId) return;

                let existe = false;
                Array.from(selectJefe.options || []).forEach(function (op) {
                    if (String(op.value) === String(jefeId)) existe = true;
                });
                if (!existe) {
                    selectJefe.appendChild(new Option(jefeNombre || ('Jefe ID ' + jefeId), jefeId, false, false));
                }
                selectJefe.value = jefeId;
                if (typeof window.refreshSelectBuscador === 'function') {
                    window.refreshSelectBuscador('add_id_jefe');
                }
            }

            function cargarVacantesAsignablesAdd(idDepartamento, idPuesto) {
                resetVacantesAsignablesAdd();
                if (getTipoRegistroAdd && getTipoRegistroAdd() === 'vacante') return;
                if (!idDepartamento || !idPuesto) return;

                fetch('/CapHum/getVacantesDisponiblesParaAsignar', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
                    body: JSON.stringify({ id_departamento: idDepartamento, id_puesto: idPuesto })
                })
                .then(res => res.json())
                .then(data => {
                    if (!data.success || !Array.isArray(data.datos) || data.datos.length === 0) {
                        resetVacantesAsignablesAdd();
                        return;
                    }
                    const wrap = document.getElementById('add_vacante_wrap');
                    const select = document.getElementById('add_vacante_existente_id');
                    if (!wrap || !select) return;
                    select.innerHTML = '<option value="">Sin vacante seleccionada</option>';
                    data.datos.forEach(v => {
                        const subs = Number(v.subordinados || 0);
                        const jefe = v.nombre_jefe ? (' - Jefe: ' + v.nombre_jefe) : '';
                        const option = document.createElement('option');
                        option.value = v.id;
                        option.textContent = 'Vacante #' + v.id + (subs ? ' - ' + subs + ' subordinado(s)' : '') + jefe;
                        option.dataset.jefeId = v.id_jefe || '';
                        option.dataset.jefeNombre = v.nombre_jefe || '';
                        select.appendChild(option);
                    });
                    select.disabled = false;
                    wrap.classList.remove('d-none');
                    if (typeof window.refreshSelectBuscador === 'function') {
                        window.refreshSelectBuscador('add_vacante_existente_id');
                    }
                })
                .catch(() => resetVacantesAsignablesAdd());
            }

            document.addEventListener('change', function (ev) {
                if (ev.target && ev.target.id === 'add_vacante_existente_id') aplicarJefeDeVacanteAdd();
            });

            if (typeof window.jQuery !== 'undefined' && window.jQuery.fn.select2) {
                window.jQuery('#add_departamento_id').off('change.gestionAddDepto').on('change.gestionAddDepto', handleAddDepartamentoChange);
            } else {
                const depAdd = document.getElementById('add_departamento_id');
                if (depAdd) depAdd.addEventListener('change', handleAddDepartamentoChange);
            }

            function cargarJefeComboAdd(idDepartamento, idPuesto, selectJefe) {
                if (!selectJefe) selectJefe = document.getElementById('add_id_jefe');
                selectJefe.innerHTML = '<option value="">Seleccione un jefe</option>';
                selectJefe.disabled = true;
                fetch('/CapHum/getJefeDirecto', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id_departamento: idDepartamento, id_puesto: idPuesto || undefined })
                })
                .then(res => res.json())
                .then(data => {
                    if (!data.success) {
                        selectJefe.disabled = false;
                        if (typeof window.refreshSelectBuscador === 'function') {
                            window.refreshSelectBuscador('add_id_jefe');
                        }
                        return;
                    }
                    (data.datos || []).forEach(jefe => {
                        const option = document.createElement('option');
                        option.value = jefe.id;
                        option.textContent = jefe.nombre_completo || (jefe.nombre_puesto ? jefe.nombre_completo + ' - ' + jefe.nombre_puesto : jefe.nombre_completo);
                        if (jefe.tipo_jefe === 'vacante') {
                            option.dataset.tipoJefe = 'vacante';
                            option.className = 'text-warning';
                        }
                        selectJefe.appendChild(option);
                    });
                    selectJefe.disabled = false;
                    if (typeof window.refreshSelectBuscador === 'function') {
                        window.refreshSelectBuscador('add_id_jefe');
                    }
                })
                .catch(() => {
                    selectJefe.disabled = false;
                    Swal.fire("Error", "No se pudieron cargar los jefes", "error");
                });
            }

            document.getElementById('add_id_puesto').addEventListener('change', function () {
                const idPuesto = this.value;
                const idDepartamento = document.getElementById('add_departamento_id').value;
                const selectJefe = document.getElementById('add_id_jefe');
                if (!idDepartamento) return;
                cargarJefeComboAdd(idDepartamento, idPuesto || null, selectJefe);
                cargarVacantesAsignablesAdd(idDepartamento, idPuesto || null);
            });

            // Función para mostrar/ocultar el select de legión
            function toggleSelectLegion() {
                const checkbox = document.getElementById('add_asignar_legion');
                const divSelect = document.getElementById('div_select_legion');
                const selectLegion = document.getElementById('add_id_legion');

                if (checkbox.checked) {
                    divSelect.style.display = 'block';
                } else {
                    divSelect.style.display = 'none';
                    selectLegion.value = ''; // Limpiar selección si se desmarca
                }
                if (typeof window.refreshSelectBuscador === 'function') {
                    window.refreshSelectBuscador('add_id_legion');
                }
            }

            // Variable para almacenar los event listeners y poder removerlos
            let fechaInputClickHandler = null;
            let fechaWrapperClickHandler = null;

            function configurarMaxFechaIngreso() {
                // Esperar un poco para asegurar que el input esté disponible
                setTimeout(() => {
                    const wrapper = document.getElementById('fecha_acta_wrapper');
                    if (!wrapper) {
                        console.warn('Wrapper de fecha no encontrado');
                        return;
                    }

                    let oldInput = document.getElementById('add_fecha_ingreso');
                    if (!oldInput) {
                        console.warn('Input de fecha no encontrado');
                        return;
                    }

                    // Remover event listeners anteriores si existen
                    if (fechaInputClickHandler && oldInput) {
                        oldInput.removeEventListener('click', fechaInputClickHandler);
                        fechaInputClickHandler = null;
                    }

                    if (wrapper && fechaWrapperClickHandler) {
                        wrapper.removeEventListener('click', fechaWrapperClickHandler);
                        fechaWrapperClickHandler = null;
                    }

                    // Intentar destruir instancia anterior de forma segura
                    try {
                        if (oldInput._flatpickr) {
                            const instance = oldInput._flatpickr;
                            if (instance && typeof instance.destroy === 'function') {
                                instance.destroy();
                            }
                        }
                        // También intentar con getInstance
                        if (typeof flatpickr !== 'undefined' && typeof flatpickr.getInstance === 'function') {
                            const existingInstance = flatpickr.getInstance(oldInput);
                            if (existingInstance && typeof existingInstance.destroy === 'function') {
                                existingInstance.destroy();
                            }
                        }
                    } catch (e) {
                        // Ignorar errores al destruir
                    }

                    // Guardar el valor actual si existe
                    const currentValue = oldInput.value || '';

                    // Crear un nuevo input completamente limpio
                    const newInput = document.createElement('input');
                    newInput.type = 'text';
                    newInput.id = 'add_fecha_ingreso';
                    newInput.className = 'form-control';
                    newInput.placeholder = 'YYYY-MM-DD';
                    newInput.value = currentValue;

                    // Reemplazar el input viejo con el nuevo
                    oldInput.parentNode.replaceChild(newInput, oldInput);

                    // Pequeño delay para asegurar que el DOM se actualice
                    setTimeout(() => {
                        const input = document.getElementById('add_fecha_ingreso');
                        if (!input) {
                            console.warn('Nuevo input no encontrado después del reemplazo');
                            return;
                        }

                        // Calcular fecha máxima (hoy + 1 día)
                        const hoy = new Date();
                        hoy.setDate(hoy.getDate() + 1);
                        const fechaMax = hoy.toISOString().split('T')[0];

                        // Inicializar Flatpickr si está disponible
                        if (typeof flatpickr !== 'undefined') {
                            try {
                                // Renderizar el calendario directamente en el body para evitar problemas de overflow
                                const fp = flatpickr(input, {
                                    dateFormat: 'Y-m-d',
                                    maxDate: fechaMax,
                                    allowInput: false,
                                    clickOpens: true,
                                    defaultDate: null,
                                    appendTo: document.body,
                                    static: false
                                });

                                // Asegurar que el calendario tenga z-index alto después de renderizarse
                                setTimeout(() => {
                                    if (fp && fp.calendarContainer) {
                                        fp.calendarContainer.style.zIndex = '99999';
                                        fp.calendarContainer.style.display = '';
                                        fp.calendarContainer.style.visibility = 'visible';
                                        fp.calendarContainer.style.opacity = '1';
                                    }
                                }, 100);

                                // Crear handler para el click en el input
                                fechaInputClickHandler = function(e) {
                                    e.preventDefault();
                                    e.stopPropagation();
                                    setTimeout(() => {
                                        if (fp && typeof fp.open === 'function') {
                                            fp.open();
                                            // Asegurar visibilidad después de abrir
                                            if (fp.calendarContainer) {
                                                fp.calendarContainer.style.zIndex = '99999';
                                                fp.calendarContainer.style.display = '';
                                                fp.calendarContainer.style.visibility = 'visible';
                                                fp.calendarContainer.style.opacity = '1';
                                            }
                                        }
                                    }, 10);
                                };

                                input.addEventListener('click', fechaInputClickHandler);

                                // También en el wrapper
                                if (wrapper) {
                                    fechaWrapperClickHandler = function(e) {
                                        if (e.target === wrapper || e.target === input) {
                                            e.preventDefault();
                                            e.stopPropagation();
                                            setTimeout(() => {
                                                if (fp && typeof fp.open === 'function') {
                                                    fp.open();
                                                    // Asegurar visibilidad después de abrir
                                                    if (fp.calendarContainer) {
                                                        fp.calendarContainer.style.zIndex = '99999';
                                                        fp.calendarContainer.style.display = '';
                                                        fp.calendarContainer.style.visibility = 'visible';
                                                        fp.calendarContainer.style.opacity = '1';
                                                    }
                                                }
                                            }, 10);
                                        }
                                    };
                                    wrapper.addEventListener('click', fechaWrapperClickHandler);
                                }


                            } catch (error) {
                                console.error('Error al inicializar Flatpickr:', error);
                                // Fallback si hay error
                                input.type = 'date';
                                input.max = fechaMax;
                            }
                        } else {
                            // Fallback si Flatpickr no está disponible
                            console.warn('Flatpickr no está disponible, usando input nativo');
                            input.type = 'date';
                            input.max = fechaMax;
                        }
                    }, 50); // Delay corto para asegurar que el DOM se actualice
                }, 200);
            }

            function getTipoRegistroAdd() {
                const seleccionado = document.querySelector('input[name="add_tipo_registro"]:checked');
                return seleccionado ? seleccionado.value : 'persona';
            }

            function aplicarTipoRegistroAdd() {
                const esVacante = getTipoRegistroAdd() === 'vacante';
                document.querySelectorAll('#offcanvasAddUser .add-persona-only').forEach(function (el) {
                    el.style.display = esVacante ? 'none' : '';
                });
                if (esVacante && typeof resetVacantesAsignablesAdd === 'function') {
                    resetVacantesAsignablesAdd();
                }
                const titulo = document.querySelector('#offcanvasAddUser .offcanvas-title');
                if (titulo) titulo.textContent = esVacante ? 'Registrar Nueva Vacante' : 'Registrar Nuevo Usuario';
                const btn = document.querySelector('#offcanvasAddUser button.btn-primary');
                if (btn) btn.textContent = esVacante ? 'Guardar vacante' : 'Guardar';
            }

            document.addEventListener('change', function (ev) {
                if (ev.target && ev.target.name === 'add_tipo_registro') aplicarTipoRegistroAdd();
            });
            document.addEventListener('DOMContentLoaded', aplicarTipoRegistroAdd);
            if (document.readyState !== 'loading') aplicarTipoRegistroAdd();

            function escapeHtmlLegacyAlta(value) {
                return String(value == null ? '' : value)
                    .replace(/&/g, '&amp;')
                    .replace(/</g, '&lt;')
                    .replace(/>/g, '&gt;')
                    .replace(/"/g, '&quot;')
                    .replace(/'/g, '&#039;');
            }

            function swalGestionUsuarioLegacy(data, opciones) {
                opciones = opciones || {};
                const legacy = (data && data.legacy_sync) || (data && data.datos && data.datos.legacy_sync) || null;
                const tituloOk = opciones.tituloOk || 'Usuario registrado';
                const tituloPendiente = opciones.tituloPendiente || (tituloOk + ', Legacy pendiente');
                const mensajeDefault = opciones.mensajeDefault || 'Usuario registrado correctamente';
                if (!legacy) {
                    return Swal.fire({
                        icon: 'warning',
                        title: tituloOk,
                        html: '<div class="text-start">' +
                            '<div class="mb-2">' + escapeHtmlLegacyAlta((data && data.mensaje) || mensajeDefault) + '</div>' +
                            '<div class="border rounded-3 p-3 bg-label-warning text-dark">' +
                                '<div class="fw-bold mb-1"><i class="fa fa-triangle-exclamation me-1"></i>Sincronizaci&oacute;n Legacy sin confirmar</div>' +
                                '<div class="small">La respuesta no incluy&oacute; el resultado de Legacy. Revisa bit&aacute;cora o ejecuta reproceso de pendientes.</div>' +
                            '</div>' +
                        '</div>',
                        confirmButtonText: 'Aceptar'
                    });
                }

                const resultado = String(legacy.resultado || '').toLowerCase();
                const creadoLegacy = !!(legacy.detalle && legacy.detalle.usuario_legacy_creado);
                const reactivadoLegacy = !!(legacy.detalle && legacy.detalle.usuario_legacy_reactivado);
                const numeroEmpleado = legacy.external_id || (data && data.datos && data.datos.numero_empleado) || '';
                let icon = 'success';
                let title = tituloOk;
                let estado = 'Sincronizado en Legacy';
                let estadoDetalle = 'Los datos ya quedaron aplicados en Legacy.';
                let badgeClass = 'bg-success';
                let panelClass = 'border-success bg-label-success';
                let iconClass = 'fa-circle-check text-success';

                if (resultado === 'actualizado') {
                    if (creadoLegacy) {
                        estado = 'Creado y sincronizado en Legacy';
                        estadoDetalle = 'El usuario ya existe en Legacy con usuario, contrase&ntilde;a, rol y jerarqu&iacute;a actualizados.';
                    } else if (reactivadoLegacy) {
                        estado = 'Reactivado y sincronizado en Legacy';
                        estadoDetalle = 'El usuario estaba dado de baja en Legacy y fue reactivado.';
                    } else {
                        estado = 'Actualizado en Legacy';
                        estadoDetalle = 'Usuario, contrase&ntilde;a, rol y jerarqu&iacute;a fueron sincronizados con Legacy.';
                    }
                } else if (resultado === 'sin_cambios') {
                    estado = 'Legacy ya estaba sincronizado';
                    estadoDetalle = 'No hubo diferencias que actualizar en Legacy.';
                    badgeClass = 'bg-info';
                    panelClass = 'border-info bg-label-info';
                    iconClass = 'fa-circle-info text-info';
                } else if (resultado === 'omitido') {
                    estado = 'No aplica sincronizaci&oacute;n Legacy';
                    estadoDetalle = 'El usuario no entra en alcance o no tiene un n&uacute;mero de empleado v&aacute;lido.';
                    badgeClass = 'bg-secondary';
                    panelClass = 'border-secondary bg-label-secondary';
                    iconClass = 'fa-circle-minus text-secondary';
                } else if (resultado === 'error') {
                    icon = 'warning';
                    title = tituloPendiente;
                    estado = 'Legacy no se pudo actualizar';
                    estadoDetalle = 'El usuario se guard&oacute; en Spartan, pero Legacy requiere revisi&oacute;n o reproceso.';
                    badgeClass = 'bg-warning text-dark';
                    panelClass = 'border-warning bg-label-warning';
                    iconClass = 'fa-triangle-exclamation text-warning';
                }

                return Swal.fire({
                    icon: icon,
                    title: title,
                    html: '<div class="text-start">' +
                        '<div class="mb-2">' + escapeHtmlLegacyAlta((data && data.mensaje) || mensajeDefault) + '</div>' +
                        '<div class="border rounded-3 p-3 ' + panelClass + '">' +
                            '<div class="d-flex align-items-center justify-content-between gap-2 flex-wrap mb-1">' +
                                '<div class="fw-bold"><i class="fa ' + iconClass + ' me-1"></i>Sincronizaci&oacute;n Legacy</div>' +
                                '<span class="badge ' + badgeClass + '">' + escapeHtmlLegacyAlta(estado) + '</span>' +
                            '</div>' +
                            '<div class="small mb-2">' + estadoDetalle + '</div>' +
                            '<div class="small text-muted">' +
                                (resultado ? '<span class="me-2">Resultado: <strong>' + escapeHtmlLegacyAlta(resultado) + '</strong></span>' : '') +
                                (numeroEmpleado ? '<span>No. empleado: <strong>' + escapeHtmlLegacyAlta(numeroEmpleado) + '</strong></span>' : '') +
                            '</div>' +
                        '</div>' +
                        (legacy.mensaje ? '<div class="small text-muted mt-2">' + escapeHtmlLegacyAlta(legacy.mensaje) + '</div>' : '') +
                    '</div>',
                    confirmButtonText: 'Aceptar'
                });
            }

            function swalAltaUsuarioLegacy(data) {
                return swalGestionUsuarioLegacy(data, {
                    tituloOk: 'Usuario registrado',
                    tituloPendiente: 'Usuario registrado, Legacy pendiente',
                    mensajeDefault: 'Usuario registrado correctamente'
                });
            }

            function guardarGestor() {
                const tipoRegistro = getTipoRegistroAdd();
                const esVacante = tipoRegistro === 'vacante';
                const nombres = document.getElementById('add_nombres').value.trim();
                const segundo_nombre = document.getElementById('add_segundo_nombre').value.trim();
                const apellidop = document.getElementById('add_apellidop').value.trim();
                const apellidom = document.getElementById('add_apellidom').value.trim();
                const telefono = document.getElementById('add_telefono').value.trim();
                const id_pais = document.getElementById('add_id_pais').value;
                const id_puesto = document.getElementById('add_id_puesto').value;
                const departamento_id = document.getElementById('add_departamento_id').value;
                const id_jefe = document.getElementById('add_id_jefe').value;
                const vacante_existente_id = document.getElementById('add_vacante_existente_id')?.value || null;
                const asignarLegion = document.getElementById('add_asignar_legion').checked;
                const id_legion = document.getElementById('add_id_legion').value;

                const usuario = document.getElementById('add_usuario').value.trim();
                const contrasena = document.getElementById('add_contrasena').value.trim();
                const fecha_ingreso = document.getElementById('add_fecha_ingreso').value.trim() || null;
                const curp = (document.getElementById('add_curp')?.value || '').trim().toUpperCase();

                const id_div_nivel1 = leerValorSelectDivision('add_id_div_nivel1');
                const id_div_nivel2 = leerValorSelectDivision('add_id_div_nivel2');
                const id_div_nivel3 = leerValorSelectDivision('add_id_div_nivel3');
                const id_div_nivel4 = leerValorSelectDivision('add_id_div_nivel4');
                const domicilio_calle_texto = document.getElementById('add_domicilio_calle_texto')?.value?.trim() || null;
                const domicilio_num_exterior = document.getElementById('add_domicilio_num_exterior')?.value?.trim() || null;
                const domicilio_num_interior = document.getElementById('add_domicilio_num_interior')?.value?.trim() || null;
                const codigo_postal = document.getElementById('add_codigo_postal')?.value?.trim() || null;

                if (esVacante) {
                    if (!departamento_id) return Swal.fire('Error', 'Debe seleccionar un departamento', 'error');
                    if (!id_puesto) return Swal.fire('Error', 'Debe seleccionar un puesto', 'error');
                    if (id_jefe && isNaN(id_jefe) && !String(id_jefe).startsWith('vacante:')) return Swal.fire('Error', 'Jefe invalido', 'error');

                    fetch('/CapHum/getInsertarGestor', {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'Accept': 'application/json'
                        },
                        body: JSON.stringify({
                            tipo_registro: 'vacante',
                            departamento_id,
                            id_puesto,
                            id_jefe: id_jefe || null
                        })
                    })
                    .then(res => {
                        if (!res.ok) throw new Error('Error HTTP');
                        return res.json();
                    })
                    .then(data => {
                        if (!data.success) {
                            return Swal.fire({ icon: 'error', title: 'Error', text: data.mensaje || 'No se pudo registrar la vacante' });
                        }
                        Swal.fire('Exito', data.mensaje || 'Vacante registrada correctamente', 'success')
                            .then(() => location.reload());
                    })
                    .catch(err => {
                        console.error('Error al registrar vacante:', err);
                        Swal.fire('Error', 'No se pudo registrar la vacante', 'error');
                    });
                    return;
                }

                //  Validaciones obligatorias (todos los campos)
                if (!nombres) return Swal.fire('Error', 'Los nombres son obligatorios', 'error');
                if (!apellidop) return Swal.fire('Error', 'El apellido paterno es obligatorio', 'error');
                if (!apellidom) return Swal.fire('Error', 'El apellido materno es obligatorio', 'error');
                if (!curp) return Swal.fire('Error', 'El CURP es obligatorio', 'error');
                if (!/^[A-Z]{4}\d{6}[HM][A-Z]{5}[0-9A-Z]\d$/.test(curp)) {
                    return Swal.fire('Error', 'El CURP debe tener 18 caracteres con formato válido.', 'error');
                }
                if (!telefono) return Swal.fire('Error', 'El teléfono es obligatorio', 'error');
                if (!fecha_ingreso) return Swal.fire('Error', 'La fecha de ingreso es obligatoria', 'error');

                if (!id_pais) return Swal.fire('Error', 'Debe seleccionar un país (sede)', 'error');
                if (!id_puesto) return Swal.fire('Error', 'Debe seleccionar un puesto', 'error');
                if (!departamento_id) return Swal.fire('Error', 'Debe seleccionar un departamento', 'error');

                // âš ï¸ jefe puede ser null, solo valida si viene
                if (id_jefe && isNaN(id_jefe) && !String(id_jefe).startsWith('vacante:')) {
                    return Swal.fire('Error', 'Jefe inválido', 'error');
                }

                //  Validar legión: si el checkbox está marcado, debe seleccionar una legión
                if (asignarLegion && !id_legion) {
                    return Swal.fire('Error', 'Debe seleccionar una legión', 'error');
                }

                if (!usuario) return Swal.fire('Error', 'Usuario obligatorio', 'error');
                if (!contrasena) return Swal.fire('Error', 'Ingresa una contraseña', 'error');

                const idColoniaAdd = id_div_nivel3 || '';
                const cpAdd = document.getElementById('add_codigo_postal')?.value?.trim() || '';
                const calleTxtAdd = document.getElementById('add_domicilio_calle_texto')?.value?.trim() || '';
                const idCalleAdd = id_div_nivel4 || '';
                const capturaDomicilioAdd = !!(idColoniaAdd || cpAdd || calleTxtAdd || idCalleAdd);
                if (capturaDomicilioAdd && !domicilio_num_exterior) {
                    return Swal.fire('Error', 'El número exterior es obligatorio cuando captura domicilio (colonia, calle o código postal).', 'error');
                }
                var selCalleAdd = document.getElementById('add_id_div_nivel4');
                if (id_div_nivel3 && selCalleAdd && !selCalleAdd.disabled && selCalleAdd.options && selCalleAdd.options.length > 1 && !id_div_nivel4 && !calleTxtAdd) {
                    return Swal.fire('Error', 'Indique la calle: elija una del catálogo o escríbala en el campo de texto (nombre o número, p. ej. Calle 10A).', 'error');
                }
                Swal.fire({
                    title: 'Guardando usuario...',
                    html: '<div class="spinner-border text-primary" role="status"><span class="visually-hidden">Cargando...</span></div><p style="margin-top: 1rem;">Guardando en Spartan y sincronizando con Legacy...</p>',
                    allowOutsideClick: false,
                    allowEscapeKey: false,
                    showConfirmButton: false,
                    didOpen: () => Swal.showLoading()
                });

                fetch('/CapHum/getInsertarGestor', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Accept': 'application/json'
                    },
                    body: JSON.stringify({
                        nombres,
                        segundo_nombre,
                        apellidop,
                        apellidom,
                        curp,
                        telefono,
                        fecha_ingreso,
                        id_pais: id_pais || 1,
                        id_div_nivel1: id_div_nivel1 || null,
                        id_div_nivel2: id_div_nivel2 || null,
                        id_div_nivel3: id_div_nivel3 || null,
                        id_div_nivel4: id_div_nivel4 || null,
                        domicilio_calle_texto: domicilio_calle_texto,
                        domicilio_num_exterior: domicilio_num_exterior,
                        domicilio_num_interior: domicilio_num_interior,
                        codigo_postal: codigo_postal,
                        id_puesto,
                        departamento_id,
                        id_jefe: id_jefe || null,
                        vacante_existente_id: vacante_existente_id || null,
                        asignar_legion: asignarLegion,
                        id_legion: asignarLegion ? id_legion : null,
                        usuario,
                        contrasena
                    })
                })
                .then(res => {
                    if (!res.ok) throw new Error('Error HTTP');
                    return res.json();
                })
                .then(data => {
                    if (!data.success) {
                        return Swal.fire({
                            icon: 'error',
                            title: 'Error',
                            text: data.mensaje || 'No se pudo registrar'
                        });
                    }

                    swalAltaUsuarioLegacy(data)
                        .then(() => location.reload());
                })
                .catch(err => {
                    console.error(err);
                    Swal.fire('Error', 'No se pudo registrar el usuario', 'error');
                });
            }

            // Limpiar formulario Agregar Usuario al cerrar el offcanvas (Cancelar o X)
            function limpiarFormularioAgregarUsuario() {
                const ids = ['add_nombres', 'add_apellidop', 'add_apellidom', 'add_curp', 'add_telefono', 'add_usuario', 'add_contrasena', 'add_num_telefono', 'add_id_pais'];
                ids.forEach(id => {
                    const el = document.getElementById(id);
                    if (el) el.value = '';
                });
                // Limpiar campo de fecha (Flatpickr)
                const fechaInput = document.getElementById('add_fecha_ingreso');
                if (fechaInput) {
                    if (fechaInput._flatpickr) {
                        fechaInput._flatpickr.clear();
                    } else {
                        fechaInput.value = '';
                    }
                }
                const addDepartamento = document.getElementById('add_departamento_id');
                if (addDepartamento) addDepartamento.value = '';
                const addPuesto = document.getElementById('add_id_puesto');
                if (addPuesto) { addPuesto.value = ''; addPuesto.disabled = true; addPuesto.innerHTML = '<option value="">Seleccione un puesto</option>'; }
                if (typeof resetVacantesAsignablesAdd === 'function') resetVacantesAsignablesAdd();
                const addJefe = document.getElementById('add_id_jefe');
                if (addJefe) { addJefe.value = ''; addJefe.disabled = true; addJefe.innerHTML = '<option value="">Seleccione un jefe</option>'; }
                const addLegion = document.getElementById('add_id_legion');
                if (addLegion) addLegion.value = '';
                const addAsignarLegion = document.getElementById('add_asignar_legion');
                if (addAsignarLegion) addAsignarLegion.checked = false;
                const divLegion = document.getElementById('div_select_legion');
                if (divLegion) divLegion.style.display = 'none';
                if (typeof resetCascadaAdd === 'function') {
                    resetCascadaAdd();
                }
            }

            $(document).ready(() => {
                // Inicializar DataTable con columnas explícitas
                configuraTabla("#historialUsuarios", { registrosPorPagina: 10 });
                getUsuarios();

                // Flatpickr fecha+hora en modal de ausencias (calendario moderno)
                $("#modalAuscencia").on("shown.bs.modal", function() { initFlatpickrAusencia(); });

                // Configurar Flatpickr para fecha de ingreso (máximo: hoy + 1 día) cuando se abre el offcanvas
                const offcanvasAdd = document.getElementById('offcanvasAddUser');
                if (offcanvasAdd) {
                    offcanvasAdd.addEventListener('shown.bs.offcanvas', function() {
                        // Inicializar Flatpickr cuando se abre el offcanvas
                        configurarMaxFechaIngreso();
                    });
                    offcanvasAdd.addEventListener('hidden.bs.offcanvas', limpiarFormularioAgregarUsuario);
                }
            });

        // Función para inicializar vista de bajas (se llama desde bajas())
        function inicializarBajas() {
            // Ocultar filtros y botón agregar
            $('.card-header.border-bottom').hide();
            $('.row.justify-content-between.m-4').hide();

            // Inicializar DataTable con las nuevas columnas
            const tabla = configuraTabla("#historialUsuarios", {
                registrosPorPagina: 10,
                columns: [
                    { data: null, defaultContent: '', className: 'control', orderable: false },
                    { data: 'nombres', title: 'Nombres' },
                    { data: 'puesto', title: 'Puesto' },
                    { data: 'estatus', title: 'Estatus', render: function(d) { return d != null ? d : ''; } },
                    { data: 'motivos', title: 'Motivos de baja' },
                    { data: 'usuario', title: 'Usuario' },
                    { data: 'acciones', title: 'Acciones', orderable: false }
                ]
            });

            // Asegurar que el select muestre el valor correcto después de la inicialización
            // Usamos drawCallback para asegurar que se ejecute después del renderizado
            tabla.on('draw.dt', function() {
                const select = $('select[name="historialUsuarios_length"]');
                if (select.length && select.val() !== '10') {
                    select.val('10');
                }
            });

            // También lo establecemos inmediatamente después de la inicialización
            setTimeout(function() {
                const select = $('select[name="historialUsuarios_length"]');
                if (select.length) {
                    select.val('10');
                }
            }, 50);

            getBajas();
        }

        // Función placeholder para editar baja (por ahora no hace nada)
        function editarBaja(registroBaja) {
            Swal.fire({
                icon: 'warning',
                title: '¡Espera!',
                html: `
                    <p style="font-size: 18px;">No me toques por favor ï¿½Ëœâ€¦</p>
                    <p style="font-size: 16px; margin-top: 10px;">Soy mucho botón para tu click, jejej</p>
                    <p style="font-size: 14px; margin-top: 10px; color: #666;">Por ahora solo soy decorativo</p>
                `,
                confirmButtonText: 'Ok, entendido',
                confirmButtonColor: '#3085d6'
            });
        }

        var archivosSeleccionadosReingreso = [];
        function abrirModalReingreso(idPersona, nombreCompleto) {
            document.getElementById('reingreso_id_persona').value = idPersona || '';
            document.getElementById('reingreso_gestor').innerHTML = '<strong>Gestor:</strong> ' + (nombreCompleto || 'N/A');
            document.getElementById('motivoReingreso').value = '';
            document.getElementById('reingreso_descripcion').value = '';
            document.getElementById('archivoPDFReingreso').value = '';
            archivosSeleccionadosReingreso = [];
            document.getElementById('reingreso_nombreArchivo').textContent = 'No se ha seleccionado ningún archivo';
            document.getElementById('listaArchivosReingreso').style.display = 'none';
            document.getElementById('listaArchivosReingreso').innerHTML = '';
            var modal = new bootstrap.Modal(document.getElementById('modalReingreso'));
            modal.show();
        }
        function agregarArchivosReingreso(input) {
            archivosSeleccionadosReingreso = Array.from(input.files || []);
            renderListaArchivosReingreso();
        }
        function renderListaArchivosReingreso() {
            var span = document.getElementById('reingreso_nombreArchivo');
            var list = document.getElementById('listaArchivosReingreso');
            if (!list) return;
            if (archivosSeleccionadosReingreso.length === 0) {
                span.textContent = 'No se ha seleccionado ningún archivo';
                list.style.display = 'none';
                list.innerHTML = '';
            } else {
                span.textContent = archivosSeleccionadosReingreso.length + ' archivo(s) seleccionado(s)';
                list.innerHTML = archivosSeleccionadosReingreso.map(function(f, i) {
                    return '<div class="d-flex align-items-center justify-content-between py-1 px-2 border rounded mb-1 small" style="background-color: rgba(0,0,0,0.03);">' +
                        '<span><i class="fa fa-file-pdf text-danger me-1"></i>' + (i + 1) + '. ' + (f.name || 'archivo') + '</span>' +
                        '<div class="d-flex gap-1">' +
                        '<button type="button" class="btn btn-sm btn-outline-info py-0 px-1" onclick="verArchivoReingreso(' + i + ')" title="Ver PDF"><i class="fa fa-eye"></i></button>' +
                        '<button type="button" class="btn btn-sm btn-outline-danger py-0 px-1" onclick="quitarArchivoReingreso(' + i + ')" title="Quitar de la lista"><i class="fa fa-times"></i></button>' +
                        '</div></div>';
                }).join('');
                list.style.display = 'block';
            }
        }
        function verArchivoReingreso(index) {
            if (archivosSeleccionadosReingreso[index]) {
                var url = URL.createObjectURL(archivosSeleccionadosReingreso[index]);
                window.open(url, '_blank');
            }
        }
        function quitarArchivoReingreso(index) {
            archivosSeleccionadosReingreso.splice(index, 1);
            renderListaArchivosReingreso();
            document.getElementById('archivoPDFReingreso').value = '';
        }
        function confirmarReingreso() {
            var motivo = (document.getElementById('motivoReingreso') && document.getElementById('motivoReingreso').value) || '';
            var descripcion = (document.getElementById('reingreso_descripcion') && document.getElementById('reingreso_descripcion').value.trim()) || '';
            var idPersona = (document.getElementById('reingreso_id_persona') && document.getElementById('reingreso_id_persona').value) || '';
            if (!motivo) { Swal.fire({ icon: 'warning', title: 'Atención', text: 'Falta el motivo de reingreso. Selecciona un motivo.' }); return; }
            if (!descripcion) { Swal.fire({ icon: 'warning', title: 'Atención', text: 'Falta la descripción del reingreso. Escribe la descripción.' }); return; }
            if (!idPersona) { Swal.fire({ icon: 'warning', title: 'Atención', text: 'No se identificó al gestor. Cierra y vuelve a abrir desde el botón Reactivar.' }); return; }
            Swal.fire({ title: '¿Confirmar reingreso?', text: 'La persona pasará de Baja a Activo en la plantilla.', icon: 'question', showCancelButton: true, confirmButtonText: 'Sí, confirmar reingreso', cancelButtonText: 'Cancelar', reverseButtons: true }).then(function(result) {
                if (!result.isConfirmed) return;
                var formData = new FormData();
                formData.append('id_gestor', idPersona);
                formData.append('motivo_reingreso', motivo);
                formData.append('descripcion_reingreso', descripcion);
                archivosSeleccionadosReingreso.forEach(function(file) { formData.append('archivosPDF[]', file); });
                fetch('/CapHum/registrarReingreso', { method: 'POST', body: formData })
                    .then(function(r) { return r.json(); })
                    .then(function(data) {
                        if (data.success) {
                            Swal.fire({ icon: 'success', title: '¡Listo!', text: data.message || 'Reingreso registrado. La persona ha sido reactivada.' });
                            bootstrap.Modal.getInstance(document.getElementById('modalReingreso')).hide();
                            if (typeof getBajas === 'function') getBajas();
                        } else {
                            var errText = data.message || 'No se pudo registrar el reingreso.';
                            if (data.error) errText += ' ' + data.error;
                            Swal.fire({ icon: 'error', title: 'Error', text: errText });
                        }
                    })
                    .catch(function(err) { Swal.fire({ icon: 'error', title: 'Error', text: 'Error de conexión. ' + (err.message || '') }); });
            });
        }

            let archivosSeleccionados = [];

            function seleccionarArchivoBajaModal() {
                document.getElementById("archivoPDF").click();
            }

            function verArchivoCargadoBajaModal(index) {
                const file = archivosSeleccionados[index];
                if (file) {
                    const url = URL.createObjectURL(file);
                    window.open(url, "_blank");
                }
            }

            document.getElementById("archivoPDF").addEventListener("change", function (e) {
                const nuevosArchivos = Array.from(e.target.files || []);
                nuevosArchivos.forEach(file => {
                    if (file.type !== "application/pdf") return;
                    archivosSeleccionados.push(file);
                });
                const spanBaja = document.getElementById("bajaModal_nombreArchivo");
                if (spanBaja) spanBaja.textContent = archivosSeleccionados.length > 0 ? archivosSeleccionados.length + " archivo(s) seleccionado(s)" : "No se ha seleccionado ningún archivo";
                renderArchivos();
                this.value = "";
            });

            function renderArchivos() {
                const lista = document.getElementById("listaArchivos");
                const spanBaja = document.getElementById("bajaModal_nombreArchivo");
                if (!lista) return;
                lista.innerHTML = "";
                if (archivosSeleccionados.length === 0) {
                    lista.style.display = "none";
                    if (spanBaja) spanBaja.textContent = "No se ha seleccionado ningún archivo";
                    return;
                }
                lista.style.display = "block";
                if (spanBaja) spanBaja.textContent = archivosSeleccionados.length + " archivo(s) seleccionado(s)";
                archivosSeleccionados.forEach((file, index) => {
                    lista.innerHTML += `
                        <div class="d-flex align-items-center justify-content-between p-2 mb-2 border rounded" style="background-color: #f8f9fa;">
                            <div class="d-flex align-items-center gap-2">
                                <i class="fa fa-file-pdf text-danger"></i>
                                <span>${file.name}</span>
                                <span class="badge bg-success rounded-pill"><i class="fa fa-check"></i></span>
                            </div>
                            <div class="d-flex gap-1">
                                <button type="button" class="btn btn-sm btn-info p-1" onclick="verArchivoCargadoBajaModal(${index})" title="Ver archivo" style="width: 28px; height: 28px; display: flex; align-items: center; justify-content: center;">
                                    <i class="fa fa-eye" style="font-size: 12px;"></i>
                                </button>
                                <button type="button" class="btn btn-sm btn-danger p-1" onclick="eliminarArchivo(${index})" title="Eliminar archivo" style="width: 28px; height: 28px; display: flex; align-items: center; justify-content: center;">
                                    <i class="fa fa-times" style="font-size: 12px;"></i>
                                </button>
                            </div>
                        </div>
                    `;
                });
            }

            function eliminarArchivo(index) {
                archivosSeleccionados.splice(index, 1);
                renderArchivos();
            }

            // ==========================================
            // FUNCIONES PARA CARGAR DOCUMENTOS DE PERSONA (GESTIÃ“N)
            // ==========================================

            // Array para almacenar archivos seleccionados (Gestión)
            let archivosSeleccionadosPersona = [];
            let archivosSubidosPersona = [];

            // Alias para el botón "Ver archivo" de la tabla (recibe id de persona)
            function verArchivo(idPersona) {
                cargarDocumentoPersona(idPersona);
            }

            // Función para abrir modal de cargar documento de persona
            function cargarDocumentoPersona(button) {
                let idPersona, nombreCompleto;
                const esIdDirecto = typeof button === 'number' || (typeof button === 'string' && button !== '' && !isNaN(Number(button)));

                if (esIdDirecto) {
                    idPersona = String(button);
                    nombreCompleto = 'N/A';
                } else {
                    let btnElement = button;
                    if (!button || typeof button.getAttribute !== 'function') {
                        if (typeof event !== 'undefined' && event && event.target) {
                            btnElement = event.target.closest('button');
                        } else if (typeof button === 'string' || typeof button === 'number') {
                            btnElement = document.querySelector(`[data-id-persona="${button}"]`);
                        }
                        if (!btnElement || typeof btnElement.getAttribute !== 'function') {
                            console.error('No se pudo obtener el elemento del botón:', button);
                            return;
                        }
                    }
                    idPersona = btnElement.getAttribute('data-id-persona');
                    nombreCompleto = btnElement.getAttribute('data-nombre') || '';
                    if (!idPersona) {
                        console.error('No se encontró el ID de persona en el botón');
                        return;
                    }
                }

                // Guardar el ID de persona en un campo oculto del modal
                document.getElementById('cargarDocPersona_idPersona').value = idPersona || '';
                document.getElementById('cargarDocPersona_nombrePersona').textContent = 'Persona: ' + (nombreCompleto || 'N/A');

                // Limpiar el select y el input de archivo
                const selectTipo = document.getElementById('cargarDocPersona_tipoDocumento');
                selectTipo.value = '';
                document.getElementById('cargarDocPersona_archivo').value = '';
                document.getElementById('cargarDocPersona_nombreArchivo').textContent = 'No se ha seleccionado ningún archivo';

                // Limpiar la lista de archivos nuevos
                archivosSeleccionadosPersona = [];
                document.getElementById('cargarDocPersona_listaArchivos').style.display = 'none';

                // Primero resetear todas las opciones del select para que sean visibles
                Array.from(selectTipo.options).forEach(option => {
                    option.style.display = 'block';
                    option.disabled = false;
                });

                // Cargar archivos existentes (esto actualizará el select automáticamente ocultando los únicos ya subidos)
                if (idPersona) {
                    cargarArchivosExistentesPersona(idPersona);
                } else {
                    // Si no hay ID, al menos actualizar el select para mostrar todas las opciones
                    actualizarSelectDocumentos();
                }

                // Actualizar el atributo multiple del input file según el tipo de documento
                const inputFile = document.getElementById('cargarDocPersona_archivo');

                // Remover listeners anteriores si existen para evitar duplicados
                const nuevoSelectTipo = selectTipo.cloneNode(true);
                selectTipo.parentNode.replaceChild(nuevoSelectTipo, selectTipo);

                // Actualizar la referencia al nuevo elemento
                const selectTipoActualizado = document.getElementById('cargarDocPersona_tipoDocumento');

                selectTipoActualizado.addEventListener('change', function() {
                    const tipoDoc = this.value;
                    if (tipoDoc && !permiteMultiplesArchivos(tipoDoc)) {
                        inputFile.setAttribute('multiple', 'false');
                        inputFile.removeAttribute('multiple');
                    } else {
                        inputFile.setAttribute('multiple', 'multiple');
                    }

                    // Limpiar archivos seleccionados cuando cambia el tipo
                    archivosSeleccionadosPersona = [];
                    inputFile.value = '';
                    document.getElementById('cargarDocPersona_nombreArchivo').textContent = 'No se ha seleccionado ningún archivo';
                    document.getElementById('cargarDocPersona_listaArchivos').style.display = 'none';
                });

                // Mostrar modal
                const modal = new bootstrap.Modal(document.getElementById('modalCargarDocumentoPersona'));
                modal.show();
            }

            // Función para seleccionar archivo
            function seleccionarArchivoDocumentoPersona() {
                document.getElementById('cargarDocPersona_archivo').click();
            }

            // Tipos de documentos que solo permiten un archivo
            const documentosUnicos = [
                'Acta de Nacimiento',
                'Certificado de Estudios',
                'Comprobante de Domicilio',
                'CURP',
                'Identificación Oficial (INE)',
                'RFC'
            ];

            // Función para verificar si un tipo de documento permite múltiples archivos
            function permiteMultiplesArchivos(tipoDocumento) {
                return !documentosUnicos.includes(tipoDocumento);
            }

            // Función para agregar archivo a la lista
            function agregarArchivoListaPersona(input) {
                const tipoDocumento = document.getElementById('cargarDocPersona_tipoDocumento').value;

                if (!tipoDocumento) {
                    Swal.fire({
                        icon: 'warning',
                        title: 'Atención',
                        text: 'Por favor selecciona primero un tipo de documento'
                    });
                    input.value = '';
                    return;
                }

                // Verificar si ya existe un documento de este tipo subido
                const esUnico = !permiteMultiplesArchivos(tipoDocumento);
                if (esUnico) {
                    // Verificar si ya hay un archivo de este tipo en los archivos subidos
                    const idDocumento = obtenerIdDocumentoPorNombre(tipoDocumento);
                    const existeDocumento = archivosSubidosPersona.some(doc => doc.id_documento === idDocumento);

                    if (existeDocumento) {
                        Swal.fire({
                            icon: 'warning',
                            title: 'Documento ya existe',
                            text: 'Este tipo de documento solo permite un archivo. Por favor elimina el existente antes de subir uno nuevo.'
                        });
                        input.value = '';
                        return;
                    }

                    // Verificar si ya hay un archivo seleccionado de este tipo
                    if (archivosSeleccionadosPersona.length > 0) {
                        Swal.fire({
                            icon: 'warning',
                            title: 'Solo un archivo permitido',
                            text: 'Este tipo de documento solo permite un archivo. Por favor elimina el archivo seleccionado antes de agregar otro.'
                        });
                        input.value = '';
                        return;
                    }
                }

                if (input.files && input.files.length > 0) {
                    const archivosValidos = [];

                    Array.from(input.files).forEach(file => {
                        if (file.type === 'application/pdf') {
                            // Si es documento único, solo permitir un archivo
                            if (esUnico && archivosSeleccionadosPersona.length >= 1) {
                                Swal.fire({
                                    icon: 'warning',
                                    title: 'Solo un archivo permitido',
                                    text: 'Este tipo de documento solo permite un archivo.'
                                });
                                return;
                            }
                            archivosValidos.push(file);
                        }
                    });

                    // Agregar archivos válidos
                    archivosValidos.forEach(file => {
                        archivosSeleccionadosPersona.push(file);
                    });

                    // Actualizar contador
                    const count = archivosSeleccionadosPersona.length;
                    document.getElementById('cargarDocPersona_nombreArchivo').textContent =
                        count > 0 ? `${count} archivo(s) seleccionado(s)` : 'No se ha seleccionado ningún archivo';

                    // Renderizar lista
                    renderArchivosSubidosPersona();
                }
            }

            // Función auxiliar para obtener ID de documento (usando IDs reales de la BD)
            function obtenerIdDocumentoPorNombre(nombre) {
                const mapaDocumentos = {
                    'CURP': 8,
                    'Identificación Oficial (INE)': 9,
                    'RFC': 10,
                    'Comprobante de Domicilio': 11,
                    'Acta de Nacimiento': 12,
                    'Certificado de Estudios': 13,
                    'Referencias Laborales': 14,
                    'Documento baja': 15,
                    'Documento Baja': 15,
                    'Documento reingreso': 16,
                    'Documento Reingreso': 16
                };
                return mapaDocumentos[nombre] || null;
            }

            // Función para renderizar archivos
            function idsDocumentosPersonaSeleccionados() {
                return documentosPersonaSeleccionados().map(doc => doc.id);
            }

            function documentosPersonaSeleccionados() {
                return Array.from(document.querySelectorAll('.doc-persona-check:checked'))
                    .map(input => {
                        const id = input.value;
                        const formato = document.querySelector(`.doc-persona-formato[data-doc-id="${id}"]`)?.value || 'pdf';
                        return { id, formato };
                    })
                    .filter(doc => doc.id);
            }

            function actualizarAccionesDescargaPersona() {
                const ids = idsDocumentosPersonaSeleccionados();
                const btnDescargar = document.getElementById('btnDescargarDocsPersona');
                if (btnDescargar) btnDescargar.disabled = ids.length === 0;
                const checkTodos = document.getElementById('checkTodosDocsPersona');
                if (checkTodos) {
                    const checks = Array.from(document.querySelectorAll('.doc-persona-check'));
                    checkTodos.checked = checks.length > 0 && checks.every(input => input.checked);
                    checkTodos.indeterminate = checks.some(input => input.checked) && !checkTodos.checked;
                }
            }

            function toggleSeleccionDocumentosPersona(seleccionado) {
                document.querySelectorAll('.doc-persona-check').forEach(input => {
                    input.checked = seleccionado;
                });
                actualizarAccionesDescargaPersona();
            }

            function nombreArchivoDescargaPersona(disposition, fallback) {
                const header = String(disposition || '');
                const utf = header.match(/filename\*=UTF-8''([^;]+)/i);
                if (utf && utf[1]) {
                    try { return decodeURIComponent(utf[1].replace(/"/g, '')); } catch (e) {}
                }
                const normal = header.match(/filename="([^";]+)"/i);
                return normal && normal[1] ? normal[1] : fallback;
            }

            async function abrirDescargaDocumentoPersona(ids, zip, formato = 'pdf', merge = false, formatos = '') {
                const listaIds = Array.isArray(ids) ? ids : [ids];
                if (!listaIds.length) return;
                const url = '/caphum/descargarDocumentosPersona?ids=' + encodeURIComponent(listaIds.join(',')) + '&formato=' + encodeURIComponent(formato || 'pdf') + (zip ? '&zip=1&folder=1' : '') + (merge ? '&merge=1' : '') + (formatos ? '&formatos=' + encodeURIComponent(formatos) : '');
                if (window.Swal) {
                    Swal.fire({
                        title: 'Descargando archivos',
                        text: 'Estamos preparando los documentos seleccionados.',
                        allowOutsideClick: false,
                        allowEscapeKey: false,
                        showConfirmButton: false,
                        didOpen: () => Swal.showLoading()
                    });
                }
                try {
                    const resp = await fetch(url, { credentials: 'same-origin' });
                    if (!resp.ok) {
                        const texto = await resp.text();
                        throw new Error(texto || 'No se pudo descargar los documentos.');
                    }
                    const blob = await resp.blob();
                    const extension = zip ? 'zip' : (formato === 'word' ? 'docx' : formato);
                    const nombre = nombreArchivoDescargaPersona(resp.headers.get('Content-Disposition'), 'documentos.' + extension);
                    const enlace = document.createElement('a');
                    const blobUrl = URL.createObjectURL(blob);
                    enlace.href = blobUrl;
                    enlace.download = nombre;
                    document.body.appendChild(enlace);
                    enlace.click();
                    enlace.remove();
                    setTimeout(() => URL.revokeObjectURL(blobUrl), 30000);
                    if (window.Swal) Swal.close();
                } catch (error) {
                    if (window.Swal) {
                        Swal.fire('No se pudo descargar', error.message || 'Revisa los documentos seleccionados.', 'error');
                    } else {
                        alert(error.message || 'No se pudo descargar.');
                    }
                }
            }

            function descargarDocumentoPersonaId(idDocumento, formato, zip) {
                abrirDescargaDocumentoPersona([idDocumento], !!zip, formato || 'pdf');
            }

            function abrirMenuDescargaDocumentosPersona() {
                const documentos = documentosPersonaSeleccionados();
                if (documentos.length === 0) {
                    Swal.fire('Selecciona documentos', 'Marca al menos un documento para descargar.', 'warning');
                    return;
                }

                Swal.fire({
                    title: 'Descargar documentos',
                    html: `
                        <div class="d-grid gap-2 text-start">
                            <button type="button" class="btn btn-outline-primary text-start" id="descDocsTodos">
                                <i class="fa fa-file-archive me-2"></i>Todo en ZIP
                            </button>
                            <button type="button" class="btn btn-outline-primary text-start" id="descDocsUno">
                                <i class="fa fa-list me-2"></i>Uno por uno
                            </button>
                        </div>
                    `,
                    showConfirmButton: false,
                    showCloseButton: true,
                    didOpen: () => {
                        document.getElementById('descDocsTodos')?.addEventListener('click', () => {
                            Swal.close();
                            descargarDocumentosPersonaSeleccionados('todos');
                        });
                        document.getElementById('descDocsUno')?.addEventListener('click', () => {
                            Swal.close();
                            descargarDocumentosPersonaSeleccionados('uno');
                        });
                    }
                });
            }

            function descargarDocumentosPersonaSeleccionados(modo) {
                const documentos = documentosPersonaSeleccionados();
                if (documentos.length === 0) {
                    Swal.fire('Selecciona documentos', 'Marca al menos un documento para descargar.', 'warning');
                    return;
                }

                const ids = documentos.map(doc => doc.id);
                const formatos = documentos.map(doc => doc.id + ':' + (doc.formato || 'pdf')).join(',');
                const formatoBase = documentos[0].formato || 'pdf';
                if (modo === 'todos') {
                    abrirDescargaDocumentoPersona(ids, true, formatoBase, false, formatos);
                    return;
                }
                documentos.forEach((doc, index) => setTimeout(() => abrirDescargaDocumentoPersona([doc.id], false, doc.formato || 'pdf'), index * 450));
            }

            function renderArchivosSubidosPersona() {
                const listaArchivos = document.getElementById('cargarDocPersona_listaArchivos');
                const tablaArchivos = document.getElementById('cargarDocPersona_tablaArchivos');

                // Renderizar tabla de archivos subidos
                if (archivosSubidosPersona.length > 0) {
                    let htmlTabla = '';
                    archivosSubidosPersona.forEach(doc => {
                        const fechaFormateada = doc.fecha_carga || 'N/A';
                        const archivoEscapado = (doc.archivo || '').replace(/'/g, "\\'");

                        var contexto = obtenerContextoDocumento(doc.id_documento);
                        htmlTabla += `
                            <tr>
                                <td class="text-center">
                                    <input type="checkbox" class="form-check-input doc-persona-check" value="${doc.id}" onchange="actualizarAccionesDescargaPersona()">
                                </td>
                                <td>
                                    <select class="form-select form-select-sm doc-persona-formato" data-doc-id="${doc.id}" onchange="actualizarAccionesDescargaPersona()">
                                        <option value="pdf" selected>PDF</option>
                                        <option value="jpg">JPG</option>
                                        <option value="word">Word</option>
                                    </select>
                                </td>
                                <td>${obtenerNombreDocumento(doc.id_documento)}</td>
                                <td>${contexto}</td>
                                <td>${doc.archivo || 'N/A'}</td>
                                <td>${fechaFormateada}</td>
                                <td>
                                    <span class="badge bg-success">Sí</span>
                                </td>
                                <td class="text-center">
                                    <div class="d-inline-flex flex-column gap-2 align-items-center">
                                    <button
                                        type="button"
                                        class="btn btn-sm btn-info text-white d-inline-flex align-items-center justify-content-center"
                                        onclick="verArchivoSubidoPersona('${archivoEscapado}')"
                                        title="Ver archivo"
                                        style="width: 44px; height: 32px;"
                                    >
                                        <i class="fa fa-eye"></i>
                                    </button>
                                    <button
                                        type="button"
                                        class="btn btn-sm btn-danger d-inline-flex align-items-center justify-content-center"
                                        onclick="eliminarArchivoSubidoPersona(${doc.id}, '${archivoEscapado}')"
                                        title="Eliminar archivo"
                                        style="width: 44px; height: 32px;"
                                    >
                                        <i class="fa fa-trash"></i>
                                    </button>
                                    </div>
                                </td>
                            </tr>
                        `;
                    });
                    tablaArchivos.innerHTML = htmlTabla;
                } else {
                    tablaArchivos.innerHTML = '<tr><td colspan="8" class="text-center text-muted">No hay archivos subidos</td></tr>';
                }
                actualizarAccionesDescargaPersona();

                // Renderizar lista de archivos nuevos seleccionados (antes de subir)
                if (archivosSeleccionadosPersona.length > 0) {
                    listaArchivos.style.display = 'block';
                    let htmlLista = '';
                    archivosSeleccionadosPersona.forEach((file, index) => {
                        htmlLista += `
                            <div class="d-flex align-items-center justify-content-between p-2 mb-2 border rounded" style="background-color: #f8f9fa;">
                                <div class="d-flex align-items-center gap-2">
                                    <i class="fa fa-file-pdf text-danger"></i>
                                    <span>${file.name}</span>
                                    <span class="badge bg-success rounded-pill">
                                        <i class="fa fa-check"></i>
                                    </span>
                                </div>
                                <div class="d-flex gap-1">
                                    <button
                                        type="button"
                                        class="btn btn-sm btn-info p-1"
                                        onclick="verArchivoCargadoPersona(${index})"
                                        title="Ver archivo"
                                        style="width: 28px; height: 28px; display: flex; align-items: center; justify-content: center;"
                                    >
                                        <i class="fa fa-eye" style="font-size: 12px;"></i>
                                    </button>
                                    <button
                                        type="button"
                                        class="btn btn-sm btn-danger p-1"
                                        onclick="eliminarArchivoCargadoPersona(${index})"
                                        title="Eliminar archivo"
                                        style="width: 28px; height: 28px; display: flex; align-items: center; justify-content: center;"
                                    >
                                        <i class="fa fa-times" style="font-size: 12px;"></i>
                                    </button>
                                </div>
                            </div>
                        `;
                    });
                    listaArchivos.innerHTML = htmlLista;
                } else {
                    listaArchivos.style.display = 'none';
                }
            }

            function obtenerContextoDocumento(idDocumento) {
                if (idDocumento == 15) return '<span class="badge bg-danger">Baja</span>';
                if (idDocumento == 16) return '<span class="badge bg-success">Reingreso</span>';
                return '<span class="badge bg-secondary">Gestión</span>';
            }
            function obtenerNombreDocumento(idDocumento) {
                const mapeo = {
                    8: 'CURP',
                    9: 'Identificación Oficial (INE)',
                    10: 'RFC',
                    11: 'Comprobante de Domicilio',
                    12: 'Acta de Nacimiento',
                    13: 'Certificado de Estudios',
                    14: 'Referencias Laborales',
                    15: 'Documento baja',
                    16: 'Documento reingreso'
                };
                return mapeo[idDocumento] || 'Documento';
            }

            // Función para actualizar el select de documentos, ocultando los únicos que ya están subidos
            function actualizarSelectDocumentos() {
                const selectTipo = document.getElementById('cargarDocPersona_tipoDocumento');
                if (!selectTipo) return;

                // Obtener todos los IDs de documentos únicos que ya están subidos
                const documentosUnicosSubidos = new Set();
                archivosSubidosPersona.forEach(doc => {
                    const idDoc = doc.id_documento;
                    // Verificar si este ID corresponde a un documento único
                    const nombreDoc = obtenerNombreDocumento(idDoc);
                    if (nombreDoc && !permiteMultiplesArchivos(nombreDoc)) {
                        documentosUnicosSubidos.add(nombreDoc);
                    }
                });

                // Verificar si el valor actual del select es un documento único ya subido
                const valorActual = selectTipo.value;
                if (valorActual && !permiteMultiplesArchivos(valorActual) && documentosUnicosSubidos.has(valorActual)) {
                    // Si el documento seleccionado es único y ya está subido, limpiar el select
                    selectTipo.value = '';
                }

                // Recorrer todas las opciones del select
                Array.from(selectTipo.options).forEach(option => {
                    const valor = option.value;
                    // Si es un documento único y ya está subido, ocultarlo
                    if (valor && !permiteMultiplesArchivos(valor) && documentosUnicosSubidos.has(valor)) {
                        option.style.display = 'none';
                        option.disabled = true;
                    } else {
                        option.style.display = 'block';
                        option.disabled = false;
                    }
                });
            }

            // Función para cargar archivos existentes
            function cargarArchivosExistentesPersona(idPersona) {
                fetch('/caphum/getDocumentosPersona?id_persona=' + idPersona)
                    .then(res => res.json())
                    .then(resp => {
                        if (resp.success && resp.datos) {
                            archivosSubidosPersona = resp.datos;
                            renderArchivosSubidosPersona();
                            // Actualizar el select después de cargar los archivos
                            actualizarSelectDocumentos();
                        } else {
                            archivosSubidosPersona = [];
                            renderArchivosSubidosPersona();
                            actualizarSelectDocumentos();
                        }
                    })
                    .catch(err => {
                        console.error('Error al cargar archivos:', err);
                        archivosSubidosPersona = [];
                        renderArchivosSubidosPersona();
                        actualizarSelectDocumentos();
                    });
            }

            // Función para eliminar archivo cargado (nuevo, antes de subir)
            function eliminarArchivoCargadoPersona(index) {
                archivosSeleccionadosPersona.splice(index, 1);
                const count = archivosSeleccionadosPersona.length;
                document.getElementById('cargarDocPersona_nombreArchivo').textContent =
                    count > 0 ? `${count} archivo(s) seleccionado(s)` : 'No se ha seleccionado ningún archivo';
                renderArchivosSubidosPersona();
            }

            // Función para eliminar archivo subido (ya en BD)
            function eliminarArchivoSubidoPersona(idDocumento, nombreArchivo) {
                Swal.fire({
                    title: '¿Eliminar archivo?',
                    text: '¿Estás seguro de que deseas eliminar "' + nombreArchivo + '"?',
                    icon: 'warning',
                    showCancelButton: true,
                    confirmButtonColor: '#d33',
                    cancelButtonColor: '#3085d6',
                    confirmButtonText: 'Sí, eliminar',
                    cancelButtonText: 'Cancelar'
                }).then((result) => {
                    if (result.isConfirmed) {
                        const formData = new FormData();
                        formData.append('id_documento', idDocumento);

                        fetch('/caphum/eliminarDocumentoPersona', {
                            method: 'POST',
                            body: formData
                        })
                        .then(res => res.json())
                        .then(resp => {
                            if (resp.success) {
                                Swal.fire({
                                    icon: 'success',
                                    title: 'Archivo eliminado',
                                    text: 'El archivo fue eliminado correctamente',
                                    timer: 2000,
                                    showConfirmButton: false
                                });

                                // Recargar lista (esto también actualizará el select)
                                const idPersona = document.getElementById('cargarDocPersona_idPersona').value;
                                if (idPersona) {
                                    cargarArchivosExistentesPersona(idPersona);
                                }
                            } else {
                                Swal.fire({
                                    icon: 'error',
                                    title: 'Error',
                                    text: resp.mensaje || 'No se pudo eliminar el archivo'
                                });
                            }
                        })
                        .catch(err => {
                            console.error('Error:', err);
                            Swal.fire({
                                icon: 'error',
                                title: 'Error',
                                text: 'Ocurrió un error al eliminar el archivo'
                            });
                        });
                    }
                });
            }

            // Función para ver un archivo nuevo (no subido)
            function verArchivoCargadoPersona(index) {
                const file = archivosSeleccionadosPersona[index];
                if (file) {
                    const url = URL.createObjectURL(file);
                    window.open(url, '_blank');
                }
            }

            // Función para ver un archivo ya subido
            function verArchivoSubidoPersona(nombreArchivo) {
                const url = '/caphum/verDocumentoPersona?archivo=' + encodeURIComponent(nombreArchivo);
                window.open(url, '_blank');
            }

            const mapaDocumentosIds = {
                'CURP': 8,
                'Identificación Oficial (INE)': 9,
                'RFC': 10,
                'Comprobante de Domicilio': 11,
                'Acta de Nacimiento': 12,
                'Certificado de Estudios': 13,
                'Referencias Laborales': 14,
                'Documento baja': 15,
                'Documento reingreso': 16
            };

            // Función para subir documento de persona
            function subirDocumentoPersona() {
                const tipoDocumento = document.getElementById('cargarDocPersona_tipoDocumento').value;
                const idPersona = document.getElementById('cargarDocPersona_idPersona').value;

                if (!tipoDocumento) {
                    Swal.fire({
                        icon: 'warning',
                        title: 'Atención',
                        text: 'Por favor selecciona un tipo de documento'
                    });
                    return;
                }

                // Obtener ID del documento usando el mapeo directo
                const idDocumento = mapaDocumentosIds[tipoDocumento];
                if (!idDocumento) {
                    Swal.fire({
                        icon: 'error',
                        title: 'Error',
                        text: 'Tipo de documento no válido: ' + tipoDocumento
                    });
                    return;
                }

                if (archivosSeleccionadosPersona.length === 0) {
                    Swal.fire({
                        icon: 'warning',
                        title: 'Atención',
                        text: 'Por favor selecciona al menos un archivo'
                    });
                    return;
                }

                if (!idPersona) {
                    Swal.fire({
                        icon: 'error',
                        title: 'Error',
                        text: 'No se encontró el ID de la persona'
                    });
                    return;
                }

                // Mostrar loading
                Swal.fire({
                    title: 'Subiendo archivos...',
                    text: 'Por favor espera',
                    allowOutsideClick: false,
                    didOpen: () => {
                        Swal.showLoading();
                    }
                });

                // Crear FormData
                const formData = new FormData();
                formData.append('id_persona', idPersona);
                formData.append('id_documento', idDocumento);  // Enviar ID directamente

                // Agregar archivos
                archivosSeleccionadosPersona.forEach((file) => {
                    formData.append('archivosPDF[]', file);
                });

                // Enviar al servidor
                fetch('/caphum/subirDocumentosPersona', {
                    method: 'POST',
                    body: formData
                })
                .then(res => {
                    // Verificar si la respuesta es JSON válido
                    const contentType = res.headers.get('content-type');
                    if (contentType && contentType.includes('application/json')) {
                        return res.json();
                    } else {
                        // Si no es JSON, leer como texto para ver el error
                        return res.text().then(text => {
                            console.error('Respuesta no JSON:', text);
                            throw new Error('El servidor devolvió una respuesta no válida.');
                        });
                    }
                })
                .then(resp => {
                    Swal.close();

                    if (resp.success) {
                        Swal.fire({
                            icon: 'success',
                            title: 'Archivos subidos',
                            text: 'Se subieron ' + archivosSeleccionadosPersona.length + ' archivo(s) correctamente',
                            timer: 2000,
                            showConfirmButton: false
                        });

                        // Limpiar archivos seleccionados
                        archivosSeleccionadosPersona = [];
                        document.getElementById('cargarDocPersona_archivo').value = '';
                        document.getElementById('cargarDocPersona_nombreArchivo').textContent = 'No se ha seleccionado ningún archivo';
                        document.getElementById('cargarDocPersona_listaArchivos').style.display = 'none';

                        // Si es un documento único, limpiar el select de tipo de documento
                        // (Referencias Laborales y Documento baja permiten múltiples, así que no se limpian)
                        if (!permiteMultiplesArchivos(tipoDocumento)) {
                            const selectTipoDoc = document.getElementById('cargarDocPersona_tipoDocumento');
                            if (selectTipoDoc) {
                                selectTipoDoc.value = '';
                            }
                        }

                        // Recargar lista de archivos (esto también actualizará el select ocultando los únicos ya subidos)
                        cargarArchivosExistentesPersona(idPersona);
                    } else {
                        Swal.fire({
                            icon: 'error',
                            title: 'Error',
                            text: resp.mensaje || 'No se pudieron subir los archivos'
                        });
                    }
                })
                .catch(err => {
                    Swal.close();
                    console.error('Error al subir archivos:', err);
                    Swal.fire({
                        icon: 'error',
                        title: 'Error',
                        text: 'Ocurrió un error al subir los archivos: ' + (err.message || 'Error desconocido')
                    });
                });
            }

        </script>
        HTML;
        // Easter egg "300" solo en Capital Humano â†’ Gestión (Ctrl+Shift+3)
