    /** Vista Candidatos (Capital Humano). Misma arquitectura que Gestión: heredoc con el script, self::set("script"), self::render. */
    public function candidatos()
    {
        $script = <<<'HTML'
        <script>

            // Estado del módulo candidatos
            var candidatoEditId = null;
            var candidatoNuevoId = null;
            var candidatoNuevoEmail = null;
            var candidatoReenviarId = null;
            var candidatoReenviarEmail = null;
            var candidatoDatosEnvio = null;
            var candidatosFiltrosLlenos = false;
            window.miUsuarioId = Number(window.miUsuarioId || 0);

            // Eager Loading: Map global con todos los candidatos y sus documentos precargados
            if (!window.candidatosDataMap) {
                window.candidatosDataMap = new Map();
            }

            var docModalPollTimer = null;
            var docModalFetchInFlight = false;
            window.SPARTA_DOC_DEBUG = window.SPARTA_DOC_DEBUG === true;

            function clearDocModalPoll() {
                if (docModalPollTimer) {
                    clearInterval(docModalPollTimer);
                    docModalPollTimer = null;
                }
            }

            function disposeDocModalTooltips() {
                if (typeof bootstrap === "undefined" || !bootstrap.Tooltip) return;
                document.querySelectorAll("#modalDocumentacionCandidato [data-bs-toggle=\"tooltip\"], .tooltip").forEach(function(el) {
                    try {
                        var inst = bootstrap.Tooltip.getInstance(el);
                        if (inst) inst.dispose();
                    } catch (e) {}
                    if (el.classList && el.classList.contains("tooltip") && el.parentNode) {
                        try { el.parentNode.removeChild(el); } catch (e2) {}
                    }
                });
            }

            function maybeScheduleDocModalPoll(idCandidato, metricas, verif, opts) {
                opts = opts || {};
                if (opts.fromPoll) {
                    return;
                }
                clearDocModalPoll();
                if (!metricas || metricas.expediente_completo !== true || (verif && verif.verificacion_en_proceso !== true)) {
                    return;
                }
                var intentos = 0;
                var maxIntentos = 60;
                docModalPollTimer = setInterval(function() {
                    intentos++;
                    if (intentos > maxIntentos) {
                        clearDocModalPoll();
                        var bv = document.getElementById("modalDocumentacionCandidatoVerificacion");
                        var modalAbierto = document.getElementById("modalDocumentacionCandidato");
                        if (bv && modalAbierto && modalAbierto.classList.contains("show")) {
                            bv.classList.remove("d-none");
                            bv.innerHTML = "<div class=\"alert alert-info small mb-0\"><i class=\"fa fa-hourglass-half me-1\"></i>Validación documental en segundo plano. Puedes cerrar este modal y volver a abrirlo; el resultado aparecerá cuando termine.</div>";
                        }
                        return;
                    }
                    cargarDocumentosModal(idCandidato, { fromPoll: true });
                }, 2000);
            }

            /* â€â€ KPI Candidatos: contador animado (misma lógica que Gestión kpiAnimateCounter) â€â€ */
            function kpiAnimateCounterCand(el, target, dur, delay) {
                if (!el) return;
                dur   = dur   || 600;
                delay = delay || 0;
                setTimeout(function() {
                    var start = performance.now();
                    var ease  = function(t) { return t < 0.5 ? 2*t*t : -1+(4-2*t)*t; };
                    (function tick(now) {
                        var p = Math.min((now - start) / dur, 1);
                        el.textContent = Math.round(target * ease(p));
                        if (p < 1) requestAnimationFrame(tick);
                        else el.textContent = target;
                    })(performance.now());
                }, delay);
            }

            /* â€â€ KPI Candidatos: barra animada (misma lógica que Gestión kpiAnimateBar) â€â€ */
            function kpiAnimateBarCand(id, pct, delay) {
                var el = document.getElementById(id);
                if (!el) return;
                el.style.width = '0%';
                setTimeout(function() { el.style.width = (pct != null ? pct : 0) + '%'; }, (delay || 0) + 80);
            }

            function actualizarIndicadoresCandidatos(datos) {
                var total = (datos && datos.length) || 0;
                var porEvaluar = (datos && datos.filter(function(c){ return (c.estatus || "") === "Por evaluar"; }).length) || 0;
                var enviadas = (datos && datos.filter(function(c){ return c.postulacion_enviada == 1; }).length) || 0;
                var elTotal = document.getElementById("kpi-total-candidatos");
                var elPorEval = document.getElementById("kpi-por-evaluar");
                var elEnviadas = document.getElementById("kpi-postulaciones-enviadas");
                if (elTotal) kpiAnimateCounterCand(elTotal, total, 600, 0);
                if (elPorEval) kpiAnimateCounterCand(elPorEval, porEvaluar, 600, 60);
                if (elEnviadas) kpiAnimateCounterCand(elEnviadas, enviadas, 600, 120);
                var pctTotal = total > 0 ? 100 : 0;
                var pctEvaluar = total > 0 ? Math.min(100, Math.round((porEvaluar / total) * 100)) : 0;
                var pctEnviadas = total > 0 ? Math.min(100, Math.round((enviadas / total) * 100)) : 0;
                kpiAnimateBarCand("kpi-bar-cand-total",    pctTotal,   80);
                kpiAnimateBarCand("kpi-bar-cand-evaluar",  pctEvaluar, 160);
                kpiAnimateBarCand("kpi-bar-cand-enviadas", pctEnviadas, 240);
                var msTotal = document.getElementById("kpi-ms-cand-total");
                var msEval = document.getElementById("kpi-ms-cand-evaluar");
                var msEnv = document.getElementById("kpi-ms-cand-enviadas");
                var dvTotal = document.getElementById("kpi-dv-cand-total");
                var dvEval = document.getElementById("kpi-dv-cand-evaluar");
                var dvEnv = document.getElementById("kpi-dv-cand-enviadas");
                if (msTotal) msTotal.textContent = total;
                if (msEval) msEval.textContent = porEvaluar;
                if (msEnv) msEnv.textContent = enviadas;
                if (dvTotal) dvTotal.textContent = total;
                if (dvEval) dvEval.textContent = porEvaluar;
                if (dvEnv) dvEnv.textContent = enviadas;
                if (kpiCandCurrentMode === "vision") {
                    kpiAnimateDonutCand("kpi-arc-cand-total", pctTotal, 80);
                    kpiAnimateDonutCand("kpi-arc-cand-evaluar", pctEvaluar, 160);
                    kpiAnimateDonutCand("kpi-arc-cand-enviadas", pctEnviadas, 240);
                }
            }

            function getCandidatos() {
                var selDepto = document.getElementById("UserRole");
                var selPuesto = document.getElementById("UserPlan");
                var selEstatus = document.getElementById("FilterTransaction");
                var data = {};
                if (selEstatus && selEstatus.value) data.estatus = selEstatus.value;
                if (selDepto && selDepto.value) data.id_departamento = selDepto.value;
                if (selPuesto && selPuesto.value) data.id_puesto = selPuesto.value;

                http.request({
                    endpoint: "/caphum/getCandidatos",
                    metodo: "GET",
                    data: data,
                    onSuccess: function(resp) {
                        try {
                            if (!resp || !resp.success || !resp.datos) {
                                console.warn('getCandidatos: respuesta vacía o sin éxito', resp);
                                return;
                            }

                            if (!Array.isArray(resp.datos)) {
                                console.error('getCandidatos: resp.datos no es un array', resp);
                                return;
                            }

                            actualizarIndicadoresCandidatos(resp.datos);

                            // ==========================================
                            // CONSOLIDAR CANDIDATOS (ESTRUCTURA IDÃ‰NTICA A GESTIÃ“N)
                            // ==========================================
                            var candidatosMap = new Map();

                            resp.datos.forEach(function(candidato) {
                                var id = candidato.id;

                                if (!id) {
                                    console.warn('getCandidatos: candidato sin ID', candidato);
                                    return;
                                }

                                if (!candidatosMap.has(id)) {
                                    // Primera vez que vemos este candidato - copiar todas las propiedades manualmente
                                    var candidatoConsolidado = {
                                        id: candidato.id,
                                        nombres: candidato.nombres,
                                        segundo_nombre: candidato.segundo_nombre,
                                        apellidop: candidato.apellidop,
                                        apellidom: candidato.apellidom,
                                        email: candidato.email,
                                        telefono: candidato.telefono,
                                        id_pais: candidato.id_pais,
                                        nombre_pais: candidato.nombre_pais,
                                        id_div_nivel1: candidato.id_div_nivel1,
                                        nombre_div_nivel1: candidato.nombre_div_nivel1,
                                        id_div_nivel2: candidato.id_div_nivel2,
                                        nombre_div_nivel2: candidato.nombre_div_nivel2,
                                        id_div_nivel3: candidato.id_div_nivel3,
                                        nombre_div_nivel3: candidato.nombre_div_nivel3,
                                        domicilio_calle_texto: candidato.domicilio_calle_texto,
                                        domicilio_num_exterior: candidato.domicilio_num_exterior,
                                        domicilio_num_interior: candidato.domicilio_num_interior,
                                        id_puesto: candidato.id_puesto,
                                        nombre_puesto: candidato.nombre_puesto,
                                        nombre_departamento: candidato.nombre_departamento,
                                        id_departamento: candidato.id_departamento,
                                        estatus: candidato.estatus,
                                        postulacion_enviada: candidato.postulacion_enviada,
                                        fecha_ingreso_programada: candidato.fecha_ingreso_programada,
                                        fecha_ingreso_notificada_en: candidato.fecha_ingreso_notificada_en,
                                        contrato_firmado_en: candidato.contrato_firmado_en,
                                        fecha_registro: candidato.fecha_registro,
                                        fecha_actualizacion: candidato.fecha_actualizacion,
                                        documentos: candidato.documentos || [],
                                        verificacion_expediente: candidato.verificacion_expediente || null,
                                        metricas: candidato.metricas || null,
                                        puestos: [{
                                            id_puesto: candidato.id_puesto,
                                            nombre_puesto: candidato.nombre_puesto,
                                            nombre_departamento: candidato.nombre_departamento,
                                            id_departamento: candidato.id_departamento
                                        }]
                                    };
                                    candidatosMap.set(id, candidatoConsolidado);
                                } else {
                                    // Ya existe, agregar nuevo puesto (por si acaso hay duplicados)
                                    var candidatoExistente = candidatosMap.get(id);
                                    if (candidatoExistente && candidatoExistente.puestos) {
                                        var puestoExiste = candidatoExistente.puestos.some(function(p) {
                                            return p.id_puesto === candidato.id_puesto &&
                                                   p.nombre_departamento === candidato.nombre_departamento;
                                        });

                                        if (!puestoExiste) {
                                            candidatoExistente.puestos.push({
                                                id_puesto: candidato.id_puesto,
                                                nombre_puesto: candidato.nombre_puesto,
                                                nombre_departamento: candidato.nombre_departamento,
                                                id_departamento: candidato.id_departamento
                                            });
                                        }
                                    }
                                }
                            });

                            var candidatosConsolidados = Array.from(candidatosMap.values());

                            // Guardar en variable global para otros usos
                            window.candidatosData = candidatosConsolidados;

                            // Eager Loading: Guardar todos los candidatos con sus documentos en el Map global
                            if (window.candidatosDataMap) {
                                window.candidatosDataMap.clear();
                            } else {
                                window.candidatosDataMap = new Map();
                            }
                            candidatosConsolidados.forEach(function(c) {
                                if (c.id) {
                                    var docPayload = {
                                        documentos: c.documentos || [],
                                        verificacion_expediente: c.verificacion_expediente || null,
                                        metricas: c.metricas || null
                                    };
                                    window.candidatosDataMap.set(parseInt(c.id, 10), docPayload);
                                }
                            });

                            // ==========================================
                            // MAPEAR DATOS PARA LA TABLA (ESTRUCTURA IDÃ‰NTICA A GESTIÃ“N)
                            // ==========================================
                            var escapeTablaCandidato = function(valor) {
                                return String(valor || "")
                                    .replace(/&/g, "&amp;")
                                    .replace(/</g, "&lt;")
                                    .replace(/>/g, "&gt;")
                                    .replace(/"/g, "&quot;")
                                    .replace(/'/g, "&#039;");
                            };
                            var datos = candidatosConsolidados.map(function(c) {
                                var nombre = [c.nombres, c.segundo_nombre, c.apellidop, c.apellidom].filter(Boolean).join(" ");
                                var tienePuestos = c.puestos && c.puestos.length > 1;
                                var correo = c.email || "";
                                var telefono = c.telefono || "";
                                var nombreContacto = '<div class="d-flex flex-column">' +
                                    '<span class="fw-semibold text-uppercase">' + escapeTablaCandidato(nombre || "Sin nombre") + '</span>' +
                                    '<small class="text-muted">' + escapeTablaCandidato(correo || "Sin correo") + '</small>' +
                                    '<small class="text-muted">' + escapeTablaCandidato(telefono || "Sin teléfono") + '</small>' +
                                    '</div>';

                                // Generar HTML para puesto/departamento
                                var puestoDeptoHTML = "";
                                if (tienePuestos) {
                                    puestoDeptoHTML = '<div class="d-flex flex-column gap-1">';
                                    c.puestos.forEach(function(puesto) {
                                        puestoDeptoHTML += '<small class="text-muted d-flex align-items-center gap-1">' +
                                            '<i class="fa fa-building"></i>' +
                                            (puesto.nombre_departamento || 'Sin departamento') +
                                            '</small>' +
                                            '<small class="text-muted d-flex align-items-center gap-1">' +
                                            '<i class="fa fa-briefcase"></i>' +
                                            (puesto.nombre_puesto || 'Sin puesto') +
                                            '</small>';
                                    });
                                    puestoDeptoHTML += '</div>';
                                } else {
                                    puestoDeptoHTML = '<small class="text-muted d-flex align-items-center gap-1">' +
                                        '<i class="fa fa-building"></i>' +
                                        (c.nombre_departamento || 'Sin departamento') +
                                        '</small>' +
                                        '<small class="text-muted d-flex align-items-center gap-1">' +
                                        '<i class="fa fa-briefcase"></i>' +
                                        (c.nombre_puesto || 'Sin puesto') +
                                        '</small>';
                                }

                                var id = (c.id || 0).toString();
                                var paisTexto = c.nombre_pais || "";
                                var estadoTexto = c.nombre_div_nivel1 || "";
                                var municipioTexto = c.nombre_div_nivel2 || "";
                                var coloniaTexto = c.nombre_div_nivel3 || "";
                                var ubicacionPartes = [paisTexto, estadoTexto, municipioTexto, coloniaTexto].filter(function(v) { return !!v; });
                                var ubicacion = ubicacionPartes.length ? ubicacionPartes.join(" / ") : "—";
                                var est = c.estatus || "Por evaluar";
                                var estBadge = est === "Validado"
                                    ? "bg-success"
                                    : (est === "Pendiente de validacion final"
                                        ? "bg-info text-dark"
                                        : (est === "Ingreso programado"
                                            ? "bg-primary"
                                            : (est === "Por evaluar" ? "bg-warning text-dark" : (est === "Proceso cerrado" ? "bg-dark" : "bg-secondary"))));

                                var acciones = '<div class="d-flex flex-wrap gap-1 align-items-center">' +
                                    '<button type="button" class="btn btn-sm btn-primary btn-editar-candidato" data-id="' + id + '" title="Editar"><i class="fa fa-edit"></i></button>' +
                                    '<button type="button" class="btn btn-sm btn-info text-white btn-reenviar-candidato" data-id="' + id + '" title="Reenviar correo"><i class="fa fa-envelope"></i></button>' +
                                    '<button type="button" class="btn btn-sm btn-secondary btn-documentacion-candidato" data-id="' + id + '" data-nombre="' + (nombre || "").replace(/"/g, "&quot;") + '" title="Documentación"><i class="fa fa-folder-open"></i></button>' +
                                    '<button type="button" class="btn btn-sm btn-danger btn-eliminar-candidato" data-id="' + id + '" title="Eliminar"><i class="fa fa-trash"></i></button></div>';

                                return {
                                    nombreContacto: nombreContacto,
                                    puestoDepto: puestoDeptoHTML.trim(),
                                    ubicacion: ubicacion,
                                    estatus: '<span class="badge ' + estBadge + '">' + est + '</span>',
                                    acciones: acciones
                                };
                            });

                            // Actualizar DataTable (usando $ como en Gestión)
                            try {
                                var tabla = $('#tablaCandidatos').DataTable();
                                if (tabla) {
                                    tabla.clear().rows.add(datos).draw();
                                } else {
                                    console.error('getCandidatos: No se pudo obtener la instancia de DataTable');
                                }
                            } catch (error) {
                                console.error('getCandidatos: Error al actualizar DataTable', error);
                            }

                            // Llenar filtros solo la primera vez
                            if (!candidatosFiltrosLlenos) {
                                candidatosFiltrosLlenos = true;
                                var deptMap = {};
                                var puestoMap = {};
                                candidatosConsolidados.forEach(function(c) {
                                    if (c.id_departamento && c.nombre_departamento) deptMap[c.id_departamento] = c.nombre_departamento;
                                    if (c.id_puesto && c.nombre_puesto) puestoMap[c.id_puesto] = c.nombre_puesto;
                                });
                                var selD = document.getElementById("UserRole");
                                var selP = document.getElementById("UserPlan");
                                if (selD) {
                                    var opts = selD.querySelectorAll("option");
                                    for (var i = opts.length - 1; i >= 1; i--) opts[i].remove();
                                    for (var k in deptMap) {
                                        var o = document.createElement("option");
                                        o.value = k;
                                        o.textContent = deptMap[k];
                                        selD.appendChild(o);
                                    }
                                }
                                if (selP) {
                                    var opts = selP.querySelectorAll("option");
                                    for (var i = opts.length - 1; i >= 1; i--) opts[i].remove();
                                    for (var k in puestoMap) {
                                        var o = document.createElement("option");
                                        o.value = k;
                                        o.textContent = puestoMap[k];
                                        selP.appendChild(o);
                                    }
                                }
                            }
                        } catch (error) {
                            console.error('getCandidatos: Error en el procesamiento', error);
                            if (typeof Swal !== "undefined") {
                                Swal.fire({
                                    icon: "error",
                                    title: "Error",
                                    text: "Error al procesar los candidatos. Intente recargar la página."
                                });
                            }
                        }
                    },
                    onError: function(err) {
                        console.error('getCandidatos: Error en la petición', err);
                        if (typeof Swal !== "undefined") {
                            Swal.fire({
                                icon: "error",
                                title: "Error",
                                text: "Error al cargar los candidatos. Por favor, recarga la página."
                            });
                        }
                    }
                });
            }

            function kpiTogglePanelCandidatos() {
                var pan = document.getElementById("kpiCollapsibleCandidatos");
                var btn = document.getElementById("kpiToggleBtnCandidatos");
                var controls = document.getElementById("kpiViewControlsCand");
                var sep = document.getElementById("kpiViewControlsSepCand");
                if (!pan || !btn) return;
                var isOpen = pan.classList.toggle("open");
                btn.classList.toggle("open", isOpen);
                if (controls) controls.classList.toggle("kpi-vc-hidden", !isOpen);
                if (sep) sep.classList.toggle("kpi-sep-hidden", !isOpen);
                kpiCandPanelOpen = isOpen;
                if (typeof localStorage !== "undefined") localStorage.setItem(KPI_CAND_STORAGE_OPEN, isOpen);
            }

            var KPI_CAND_STORAGE_MODE = "kpi_cand_mode";
            var KPI_CAND_STORAGE_OPEN = "kpi_cand_open";
            var kpiCandCurrentMode = (typeof localStorage !== "undefined" && localStorage.getItem(KPI_CAND_STORAGE_MODE)) || "default";
            var kpiCandPanelOpen = (typeof localStorage !== "undefined" && localStorage.getItem(KPI_CAND_STORAGE_OPEN) !== "false");

            function kpiAnimateDonutCand(arcId, pct, delay) {
                var el = document.getElementById(arcId);
                if (!el) return;
                var CIRC = 2 * Math.PI * 36;
                el.style.strokeDasharray = "0 " + CIRC;
                setTimeout(function() {
                    var filled = (pct / 100) * CIRC;
                    el.style.strokeDasharray = filled + " " + (CIRC - filled);
                }, (delay || 0) + 100);
            }

            function kpiApplyModeCand(mode, animate) {
                var row = document.getElementById("kpiRowNewCand");
                if (!row) return;
                row.classList.remove("mode-default", "mode-vision", "mode-ministat");
                row.classList.add("mode-" + mode);
                ["default", "vision", "ministat"].forEach(function(m) {
                    var btn = document.getElementById("vbtn-cand-" + (m === "default" ? "default" : m === "vision" ? "vision" : "ministat"));
                    if (btn) btn.classList.toggle("active", m === mode);
                });
                if (animate && mode === "vision") {
                    var total = parseInt(document.getElementById("kpi-total-candidatos").textContent, 10) || 0;
                    var porEval = parseInt(document.getElementById("kpi-por-evaluar").textContent, 10) || 0;
                    var enviadas = parseInt(document.getElementById("kpi-postulaciones-enviadas").textContent, 10) || 0;
                    var pctTotal = total > 0 ? 100 : 0;
                    var pctEval = total > 0 ? Math.min(100, Math.round((porEval / total) * 100)) : 0;
                    var pctEnv = total > 0 ? Math.min(100, Math.round((enviadas / total) * 100)) : 0;
                    kpiAnimateDonutCand("kpi-arc-cand-total", pctTotal, 80);
                    kpiAnimateDonutCand("kpi-arc-cand-evaluar", pctEval, 160);
                    kpiAnimateDonutCand("kpi-arc-cand-enviadas", pctEnv, 240);
                }
            }

            function kpiSetModeCand(mode) {
                kpiCandCurrentMode = mode;
                if (typeof localStorage !== "undefined") localStorage.setItem(KPI_CAND_STORAGE_MODE, mode);
                kpiApplyModeCand(mode, true);
            }

            function kpiResetPrefsCand() {
                if (typeof localStorage !== "undefined") {
                    localStorage.removeItem(KPI_CAND_STORAGE_MODE);
                    localStorage.removeItem(KPI_CAND_STORAGE_OPEN);
                }
                location.reload();
            }

            (function applyKpiCandInitialState() {
                function run() {
                    var pan = document.getElementById("kpiCollapsibleCandidatos");
                    var btn = document.getElementById("kpiToggleBtnCandidatos");
                    var controls = document.getElementById("kpiViewControlsCand");
                    var sep = document.getElementById("kpiViewControlsSepCand");
                    if (pan) pan.classList.toggle("open", kpiCandPanelOpen);
                    if (btn) btn.classList.toggle("open", kpiCandPanelOpen);
                    if (controls) controls.classList.toggle("kpi-vc-hidden", !kpiCandPanelOpen);
                    if (sep) sep.classList.toggle("kpi-sep-hidden", !kpiCandPanelOpen);
                    kpiApplyModeCand(kpiCandCurrentMode, false);
                }
                if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", run);
                else run();
            })();

            function initFlatpickrFechaPostulacion() {
                var input = document.getElementById("candidato_fecha_postulacion");
                if (!input || typeof flatpickr === "undefined") return;
                if (input._flatpickr) return;
                var hoy = new Date().toISOString().slice(0, 10);
                flatpickr(input, { dateFormat: "Y-m-d", defaultDate: hoy, maxDate: hoy, allowInput: false, clickOpens: true, appendTo: document.body, static: false, locale: (typeof flatpickr !== "undefined" && flatpickr.l10ns && flatpickr.l10ns.es) ? flatpickr.l10ns.es : undefined });
            }

            function refreshSelectBuscadorCandidato(selectId) {
                var el = document.getElementById(selectId);
                if (!el || !el.classList.contains("js-select-buscador")) return;
                if (typeof window.jQuery === "undefined" || !window.jQuery.fn.select2) return;
                var $ = window.jQuery;
                var $el = $("#" + selectId);
                var prev = el.value;
                if ($el.hasClass("select2-hidden-accessible")) {
                    $el.select2("destroy");
                }
                $el.prop("disabled", !!el.disabled);
                $el.select2({
                    width: "100%",
                    dropdownParent: $("#offcanvasAddCandidato"),
                    minimumResultsForSearch: 0,
                    language: {
                        noResults: function () { return "Sin resultados"; },
                        searching: function () { return "Buscando..."; }
                    }
                });
                $el.prop("disabled", !!el.disabled);
                if (prev) {
                    $el.val(prev).trigger("change");
                }
            }

            function catalogoOrganizacionCandidato() {
                return Array.isArray(window.departamentosCandidatoBackend) ? window.departamentosCandidatoBackend : [];
            }

            function normalizarTextoCandidato(txt) {
                return String(txt || '').trim();
            }

            function resetPuestoJefeCandidato() {
                var selPuesto = document.getElementById("candidato_id_puesto");
                var selJefe = document.getElementById("candidato_id_posible_jefe");
                if (selPuesto) {
                    selPuesto.innerHTML = "<option value=''>Seleccione departamento primero</option>";
                    selPuesto.disabled = true;
                    refreshSelectBuscadorCandidato(selPuesto.id);
                }
                if (selJefe) {
                    selJefe.innerHTML = "<option value=''>Seleccione departamento y puesto primero</option>";
                    selJefe.disabled = true;
                    refreshSelectBuscadorCandidato(selJefe.id);
                }
            }

            function resetCascadaOrganizacionCandidato() {
                var direccion = document.getElementById("candidato_id_direccion");
                var area = document.getElementById("candidato_id_area");
                var depto = document.getElementById("candidato_id_departamento");
                if (direccion) {
                    direccion.innerHTML = "<option value=''>Seleccione dirección</option>";
                    direccion.disabled = false;
                }
                if (area) {
                    area.innerHTML = "<option value=''>Seleccione dirección primero</option>";
                    area.disabled = true;
                }
                if (depto) {
                    depto.innerHTML = "<option value=''>Seleccione área primero</option>";
                    depto.disabled = true;
                }
                resetPuestoJefeCandidato();
                ["candidato_id_direccion", "candidato_id_area", "candidato_id_departamento"].forEach(refreshSelectBuscadorCandidato);
            }

            function renderDireccionesCandidato(valorSeleccionado) {
                var select = document.getElementById("candidato_id_direccion");
                if (!select) return;
                var mapa = new Map();
                catalogoOrganizacionCandidato().forEach(function(dep) {
                    var id = String(dep.id_direccion || 0);
                    var nombre = normalizarTextoCandidato(dep.direccion_nombre || "Sin dirección");
                    if (!mapa.has(id)) mapa.set(id, nombre);
                });
                select.innerHTML = "<option value=''>Seleccione dirección</option>";
                Array.from(mapa.entries()).sort(function(a, b) { return a[1].localeCompare(b[1]); }).forEach(function(row) {
                    var opt = document.createElement("option");
                    opt.value = row[0];
                    opt.textContent = row[1];
                    select.appendChild(opt);
                });
                select.disabled = mapa.size === 0;
                if (valorSeleccionado !== undefined && valorSeleccionado !== null) {
                    select.value = String(valorSeleccionado);
                }
                refreshSelectBuscadorCandidato(select.id);
            }

            function renderAreasCandidato(idDireccion, valorSeleccionado) {
                var select = document.getElementById("candidato_id_area");
                var depto = document.getElementById("candidato_id_departamento");
                if (!select) return;
                var direccionSeleccionada = String(idDireccion || "");
                var mapa = new Map();
                catalogoOrganizacionCandidato().forEach(function(dep) {
                    if (String(dep.id_direccion || 0) !== direccionSeleccionada) return;
                    var id = String(dep.id_departamento_organizacional || 0);
                    var nombre = normalizarTextoCandidato(dep.departamento_organizacional_nombre || "Sin área");
                    if (!mapa.has(id)) mapa.set(id, nombre);
                });
                select.innerHTML = "<option value=''>Seleccione área</option>";
                Array.from(mapa.entries()).sort(function(a, b) { return a[1].localeCompare(b[1]); }).forEach(function(row) {
                    var opt = document.createElement("option");
                    opt.value = row[0];
                    opt.textContent = row[1];
                    select.appendChild(opt);
                });
                select.disabled = direccionSeleccionada === "" || mapa.size === 0;
                if (valorSeleccionado !== undefined && valorSeleccionado !== null) {
                    select.value = String(valorSeleccionado);
                }
                if (depto) {
                    depto.innerHTML = "<option value=''>Seleccione área primero</option>";
                    depto.disabled = true;
                    refreshSelectBuscadorCandidato(depto.id);
                }
                resetPuestoJefeCandidato();
                refreshSelectBuscadorCandidato(select.id);
            }

            function renderDepartamentosCandidato(idArea, valorSeleccionado) {
                var select = document.getElementById("candidato_id_departamento");
                if (!select) return;
                var areaSeleccionada = String(idArea || "");
                var mapa = new Map();
                catalogoOrganizacionCandidato().forEach(function(dep) {
                    if (String(dep.id_departamento_organizacional || 0) !== areaSeleccionada) return;
                    var id = String(dep.id || dep.departamento_id || "");
                    var nombre = normalizarTextoCandidato(dep.nombre || dep.departamento_nombre || "");
                    if (id && nombre && !mapa.has(id)) mapa.set(id, nombre);
                });
                select.innerHTML = "<option value=''>Seleccione departamento</option>";
                Array.from(mapa.entries()).sort(function(a, b) { return a[1].localeCompare(b[1]); }).forEach(function(row) {
                    var opt = document.createElement("option");
                    opt.value = row[0];
                    opt.textContent = row[1];
                    select.appendChild(opt);
                });
                select.disabled = areaSeleccionada === "" || mapa.size === 0;
                if (valorSeleccionado !== undefined && valorSeleccionado !== null) {
                    select.value = String(valorSeleccionado);
                }
                resetPuestoJefeCandidato();
                refreshSelectBuscadorCandidato(select.id);
            }

            function seleccionarOrganizacionPorDepartamentoCandidato(idDepartamento) {
                var dep = catalogoOrganizacionCandidato().find(function(item) {
                    return String(item.id || item.departamento_id || "") === String(idDepartamento || "");
                });
                renderDireccionesCandidato(dep ? (dep.id_direccion || 0) : "");
                if (!dep) {
                    renderAreasCandidato("", "");
                    renderDepartamentosCandidato("", "");
                    return;
                }
                renderAreasCandidato(dep.id_direccion || 0, dep.id_departamento_organizacional || 0);
                renderDepartamentosCandidato(dep.id_departamento_organizacional || 0, idDepartamento);
                var selDepto = document.getElementById("candidato_id_departamento");
                if (selDepto && idDepartamento) {
                    if (typeof window.jQuery !== "undefined") window.jQuery(selDepto).trigger("change");
                    else selDepto.dispatchEvent(new Event("change", { bubbles: true }));
                }
            }

            function ocultarSeccionesDomicilioCandidato() {
                ["estado", "municipio", "colonia", "calle_texto", "num_extint"].forEach(function (k) {
                    var el = document.getElementById("div_candidato_" + k);
                    if (el) el.style.display = "none";
                });
            }

            function limpiarDomicilioTextoCandidato() {
                ["candidato_domicilio_calle_texto", "candidato_domicilio_num_exterior", "candidato_domicilio_num_interior"].forEach(function(id) {
                    var el = document.getElementById(id);
                    if (el) el.value = "";
                });
            }

            function resetCascadaDomicilioCandidato() {
                var estado = document.getElementById("candidato_id_div_nivel1");
                var mun = document.getElementById("candidato_id_div_nivel2");
                var col = document.getElementById("candidato_id_div_nivel3");
                if (estado) { estado.innerHTML = "<option value=''>Seleccione un estado</option>"; estado.disabled = true; }
                if (mun) { mun.innerHTML = "<option value=''>Seleccione una alcaldía / municipio</option>"; mun.disabled = true; }
                if (col) { col.innerHTML = "<option value=''>Seleccione una colonia</option>"; col.disabled = true; }
                ocultarSeccionesDomicilioCandidato();
                limpiarDomicilioTextoCandidato();
                if (estado) refreshSelectBuscadorCandidato(estado.id);
                if (mun) refreshSelectBuscadorCandidato(mun.id);
                if (col) refreshSelectBuscadorCandidato(col.id);
            }

            function cargarEstadosCandidato(idPais, done) {
                var estado = document.getElementById("candidato_id_div_nivel1");
                if (!estado) { if (done) done(false); return; }
                estado.innerHTML = "<option value=''>Cargando...</option>";
                estado.disabled = true;
                fetch("/caphum/getEstados", {
                    method: "POST",
                    headers: { "Content-Type": "application/json", "Accept": "application/json" },
                    credentials: "same-origin",
                    body: JSON.stringify({ id_pais: idPais })
                }).then(function(r){ return r.json(); }).then(function(res){
                    estado.innerHTML = "<option value=''>Seleccione un estado</option>";
                    var ok = res && res.success && Array.isArray(res.datos) && res.datos.length > 0;
                    if (ok) {
                        res.datos.forEach(function(e){
                            var opt = document.createElement("option");
                            opt.value = e.id;
                            opt.textContent = e.nombre || "";
                            estado.appendChild(opt);
                        });
                        estado.disabled = false;
                    }
                    refreshSelectBuscadorCandidato("candidato_id_div_nivel1");
                    if (done) done(ok);
                }).catch(function(){
                    estado.innerHTML = "<option value=''>Error al cargar</option>";
                    refreshSelectBuscadorCandidato("candidato_id_div_nivel1");
                    if (done) done(false);
                });
            }

            function cargarMunicipiosCandidato(idEstado, done) {
                var mun = document.getElementById("candidato_id_div_nivel2");
                if (!mun) { if (done) done(false); return; }
                mun.innerHTML = "<option value=''>Cargando...</option>";
                mun.disabled = true;
                fetch("/caphum/getMunicipios", {
                    method: "POST",
                    headers: { "Content-Type": "application/json", "Accept": "application/json" },
                    credentials: "same-origin",
                    body: JSON.stringify({ id_estado: idEstado })
                }).then(function(r){ return r.json(); }).then(function(res){
                    mun.innerHTML = "<option value=''>Seleccione una alcaldía / municipio</option>";
                    var ok = res && res.success && Array.isArray(res.datos) && res.datos.length > 0;
                    if (ok) {
                        res.datos.forEach(function(e){
                            var opt = document.createElement("option");
                            opt.value = e.id;
                            opt.textContent = e.nombre || "";
                            mun.appendChild(opt);
                        });
                        mun.disabled = false;
                    }
                    refreshSelectBuscadorCandidato("candidato_id_div_nivel2");
                    if (done) done(ok);
                }).catch(function(){
                    mun.innerHTML = "<option value=''>Error al cargar</option>";
                    refreshSelectBuscadorCandidato("candidato_id_div_nivel2");
                    if (done) done(false);
                });
            }

            function cargarColoniasCandidato(idMunicipio, done) {
                var col = document.getElementById("candidato_id_div_nivel3");
                if (!col) { if (done) done(false); return; }
                col.innerHTML = "<option value=''>Cargando...</option>";
                col.disabled = true;
                fetch("/caphum/getColonias", {
                    method: "POST",
                    headers: { "Content-Type": "application/json", "Accept": "application/json" },
                    credentials: "same-origin",
                    body: JSON.stringify({ id_municipio: idMunicipio })
                }).then(function(r){ return r.json(); }).then(function(res){
                    col.innerHTML = "<option value=''>Seleccione una colonia</option>";
                    var ok = res && res.success && Array.isArray(res.datos) && res.datos.length > 0;
                    if (ok) {
                        res.datos.forEach(function(e){
                            var opt = document.createElement("option");
                            opt.value = e.id;
                            opt.textContent = e.nombre || "";
                            col.appendChild(opt);
                        });
                        col.disabled = false;
                    }
                    refreshSelectBuscadorCandidato("candidato_id_div_nivel3");
                    if (done) done(ok);
                }).catch(function(){
                    col.innerHTML = "<option value=''>Error al cargar</option>";
                    refreshSelectBuscadorCandidato("candidato_id_div_nivel3");
                    if (done) done(false);
                });
            }

            function precargarCascadaDomicilioCandidato(c) {
                var idPais = c && c.id_pais ? String(c.id_pais) : "";
                var idEstado = c && c.id_div_nivel1 ? String(c.id_div_nivel1) : "";
                var idMunicipio = c && c.id_div_nivel2 ? String(c.id_div_nivel2) : "";
                var idColonia = c && c.id_div_nivel3 ? String(c.id_div_nivel3) : "";
                if (!idPais) {
                    resetCascadaDomicilioCandidato();
                    return;
                }
                var divEstado = document.getElementById("div_candidato_estado");
                if (divEstado) divEstado.style.display = "";
                cargarEstadosCandidato(idPais, function(tieneEstados) {
                    if (!tieneEstados) return;
                    var estado = document.getElementById("candidato_id_div_nivel1");
                    if (!estado) return;
                    if (idEstado) {
                        estado.value = idEstado;
                        refreshSelectBuscadorCandidato("candidato_id_div_nivel1");
                        var divMunicipio = document.getElementById("div_candidato_municipio");
                        if (divMunicipio) divMunicipio.style.display = "";
                        cargarMunicipiosCandidato(idEstado, function(tieneMunicipios) {
                            if (!tieneMunicipios) return;
                            var municipio = document.getElementById("candidato_id_div_nivel2");
                            if (!municipio) return;
                            if (idMunicipio) {
                                municipio.value = idMunicipio;
                                refreshSelectBuscadorCandidato("candidato_id_div_nivel2");
                                var divColonia = document.getElementById("div_candidato_colonia");
                                if (divColonia) divColonia.style.display = "";
                                cargarColoniasCandidato(idMunicipio, function(tieneColonias) {
                                    if (!tieneColonias) return;
                                    var colonia = document.getElementById("candidato_id_div_nivel3");
                                    if (!colonia) return;
                                    if (idColonia) {
                                        colonia.value = idColonia;
                                        refreshSelectBuscadorCandidato("candidato_id_div_nivel3");
                                    }
                                    var calle = document.getElementById("div_candidato_calle_texto");
                                    var extInt = document.getElementById("div_candidato_num_extint");
                                    if (calle) calle.style.display = "";
                                    if (extInt) extInt.style.display = "";
                                });
                            }
                        });
                    }
                });
            }

            function toggleLegionCandidato() {
                var div = document.getElementById("div_candidato_legion"); var chk = document.getElementById("candidato_asignar_legion");
                div.style.display = chk && chk.checked ? "block" : "none";
                if (!chk.checked) document.getElementById("candidato_id_legion").value = "";
            }

            function candidatosTableClick(e) {
                var target = e.target; var tabla = document.getElementById("tablaCandidatos");
                if (!tabla || !tabla.contains(target)) return;
                var btn = target.closest(".btn-editar-candidato");
                if (btn) { e.preventDefault(); e.stopPropagation(); var id = btn.getAttribute("data-id"); if (id) editarCandidato(parseInt(id, 10)); return; }
                btn = target.closest(".btn-reenviar-candidato");
                if (btn) { e.preventDefault(); e.stopPropagation(); var id = btn.getAttribute("data-id"); if (id) abrirModalReenviarPostulacion(parseInt(id, 10)); return; }
                btn = target.closest(".btn-documentacion-candidato");
                if (btn) { e.preventDefault(); e.stopPropagation(); var id = btn.getAttribute("data-id"); var nombre = btn.getAttribute("data-nombre") || ""; if (id) abrirModalDocumentacionCandidato(parseInt(id, 10), nombre); return; }
                btn = target.closest(".btn-eliminar-candidato");
                if (btn) { e.preventDefault(); e.stopPropagation(); var id = btn.getAttribute("data-id"); if (id) eliminarCandidato(parseInt(id, 10)); }
            }

            function renderMetricasDoc(bloqueMetricas, m) {
                if (!bloqueMetricas || !m) return;
                bloqueMetricas.classList.remove("d-none");
                var total = m.total_documentos != null ? m.total_documentos : 0;
                var requeridos = m.documentos_requeridos != null ? m.documentos_requeridos : 10;
                var pct = m.porcentaje != null ? m.porcentaje : (requeridos > 0 ? Math.min(100, Math.round((total / requeridos) * 100)) : 0);
                var completo = m.expediente_completo === true;
                var html = "<div class=\"card border shadow-none h-100\"><div class=\"card-header py-2 bg-light\"><strong><i class=\"fa fa-chart-pie me-1\"></i>Métricas del expediente</strong></div><div class=\"card-body py-2 small overflow-auto\">";
                html += "<p class=\"text-muted mb-2\">Resumen de documentación recibida (cuántos documentos obligatorios ha subido el candidato).</p>";
                html += "<div class=\"row g-2 align-items-center\">";
                html += "<div class=\"col-6\"><span class=\"text-muted d-block\">Documentos subidos</span><strong class=\"text-primary\">" + total + " de " + requeridos + "</strong></div>";
                html += "<div class=\"col-6\"><span class=\"text-muted d-block\">Avance</span><strong>" + pct + "%</strong>";
                if (pct < 100) html += " <div class=\"progress mt-1\" style=\"height:6px;\"><div class=\"progress-bar\" role=\"progressbar\" style=\"width:" + pct + "%\" aria-valuenow=\"" + pct + "\" aria-valuemin=\"0\" aria-valuemax=\"100\"></div></div>";
                html += "</div>";
                html += "<div class=\"col-12\"><span class=\"text-muted d-block\">Expediente completo</span><strong class=\"" + (completo ? "text-success" : "text-secondary") + "\">" + (completo ? "Sí" : "No") + "</strong></div>";
                html += "</div></div></div>";
                bloqueMetricas.innerHTML = html;
            }

            function obtenerCandidatoLocalPorId(idCandidato) {
                var id = parseInt(idCandidato, 10);
                if (!id || !window.candidatosData || !Array.isArray(window.candidatosData)) return null;
                for (var i = 0; i < window.candidatosData.length; i++) {
                    if (parseInt(window.candidatosData[i].id, 10) === id) return window.candidatosData[i];
                }
                return null;
            }

            function renderAccionesProcesoCandidato(bloqueAccionesProceso, metricas, idCandidato) {
                if (!bloqueAccionesProceso) return;
                var validados = metricas && metricas.validados != null ? parseInt(metricas.validados, 10) : 0;
                var requeridos = metricas && metricas.documentos_requeridos != null ? parseInt(metricas.documentos_requeridos, 10) : 10;
                if (validados >= requeridos && requeridos >= 10) {
                    var candidato = obtenerCandidatoLocalPorId(idCandidato);
                    var estatus = candidato && candidato.estatus ? String(candidato.estatus) : "";
                    var permisosCand = window.candidatosPermisos || {};
                    var puedeDocumental = !!permisosCand.documental;
                    var puedeFinal = !!permisosCand.final;
                    var pendienteFinal = estatus === "Pendiente de validacion final";
                    var ingresoProgramado = !!(candidato && candidato.fecha_ingreso_programada) || estatus === "Ingreso programado";
                    if (puedeDocumental && !pendienteFinal && !ingresoProgramado) {
                        bloqueAccionesProceso.classList.remove("d-none");
                        bloqueAccionesProceso.innerHTML = "<div class=\"w-100 text-start text-lg-end\"><p class=\"text-muted small mb-2 mb-lg-3\">Los documentos estan validados. Envia el expediente a validacion final para continuar el proceso.</p><div class=\"d-flex flex-wrap gap-2 justify-content-end\"><button type=\"button\" class=\"btn btn-outline-danger btn-cerrar-proceso-candidato\" data-id=\"" + idCandidato + "\"><i class=\"fa fa-times-circle me-1\"></i>Cerrar proceso</button><button type=\"button\" class=\"btn btn-primary btn-enviar-validacion-final-candidato\" data-id=\"" + idCandidato + "\"><i class=\"fa fa-paper-plane me-1\"></i>Enviar a validacion final</button></div></div>";
                        return;
                    }
                    if (puedeDocumental && !puedeFinal && (pendienteFinal || ingresoProgramado)) {
                        bloqueAccionesProceso.classList.remove("d-none");
                        bloqueAccionesProceso.innerHTML = "<div class=\"w-100 text-start text-lg-end\"><p class=\"text-muted small mb-0\">El expediente ya fue enviado a validacion final.</p></div>";
                        return;
                    }
                    if (!puedeFinal || (!pendienteFinal && !ingresoProgramado)) {
                        bloqueAccionesProceso.classList.add("d-none");
                        bloqueAccionesProceso.innerHTML = "";
                        return;
                    }
                    var btnClase = ingresoProgramado ? "btn-confirmar-firma-candidato" : "btn-continuar-proceso-candidato";
                    var btnIcon = ingresoProgramado ? "fa-file-signature" : "fa-check-circle";
                    var btnTexto = ingresoProgramado ? "Confirmar firma" : "Continuar proceso";
                    var ayuda = ingresoProgramado
                        ? "El ingreso ya fue notificado. Confirma la firma del contrato para pasarlo a Gestión."
                        : "Los 10 documentos han sido validados. Elige una acción:";
                    bloqueAccionesProceso.classList.remove("d-none");
                    bloqueAccionesProceso.innerHTML = "<div class=\"w-100 text-start text-lg-end\"><p class=\"text-muted small mb-2 mb-lg-3\">" + ayuda + "</p><div class=\"d-flex flex-wrap gap-2 justify-content-end\"><button type=\"button\" class=\"btn btn-outline-danger btn-cerrar-proceso-candidato\" data-id=\"" + idCandidato + "\"><i class=\"fa fa-times-circle me-1\"></i>Cerrar proceso</button><button type=\"button\" class=\"btn btn-primary " + btnClase + "\" data-id=\"" + idCandidato + "\"><i class=\"fa " + btnIcon + " me-1\"></i>" + btnTexto + "</button></div></div>";
                } else {
                    bloqueAccionesProceso.classList.add("d-none");
                    bloqueAccionesProceso.innerHTML = "";
                }
            }

            function renderVerificacionApiCard(bloqueVerif, v) {
                if (!bloqueVerif || !v) return;
                bloqueVerif.classList.remove("d-none");
                var scoreFrente = v.identificacion_frente_score != null ? Number(v.identificacion_frente_score) : null;
                var scoreReverso = v.identificacion_reverso_score != null ? Number(v.identificacion_reverso_score) : null;
                var checksOk = v.checks_ok != null ? parseInt(v.checks_ok, 10) : null;
                var checksTotales = v.checks_totales != null ? parseInt(v.checks_totales, 10) : null;
                var todoCoincide = v.todo_coincide === true;
                var verificacionEnProceso = v.verificacion_en_proceso === true;
                var alertas = Array.isArray(v.alertas) && v.alertas.length ? v.alertas.filter(function(a) { return !esAvisoCurpOcrResuelto(a); }) : [];
                var confianzaNum = null;
                if (scoreFrente != null && scoreReverso != null) { confianzaNum = Math.round((scoreFrente + scoreReverso) / 2); }
                else if (scoreFrente != null) { confianzaNum = scoreFrente; }
                else if (scoreReverso != null) { confianzaNum = scoreReverso; }
                else if (checksTotales > 0 && checksOk != null) { confianzaNum = Math.round((checksOk / checksTotales) * 100); }
                var confianzaTexto = confianzaNum != null ? confianzaNum + "%" : "—";
                var confianzaClase = "text-secondary";
                if (confianzaNum != null) {
                    if (confianzaNum >= 80) confianzaClase = "text-success";
                    else if (confianzaNum >= 50) confianzaClase = "text-warning";
                    else confianzaClase = "text-danger";
                }
                var usuarioPuedeRevalidar = (typeof window.miUsuarioId !== "undefined" && parseInt(window.miUsuarioId, 10) === 1);
                var btnHeaderRevalidar = usuarioPuedeRevalidar ? "<button type=\"button\" class=\"btn btn-xs btn-outline-primary py-0 px-1 btn-reintentar-verif-expediente\" data-reintentar-api=\"1\" title=\"Volver a validar expediente\"><i class=\"fa fa-sync-alt\"></i></button>" : "";
                var html = "<div class=\"card border shadow-none h-100\"><div class=\"card-header py-2 bg-light d-flex align-items-center justify-content-between gap-2\"><strong><i class=\"fa fa-shield-alt me-1\"></i>Resultado de la verificación API</strong>" + btnHeaderRevalidar + "</div><div class=\"card-body py-2 small overflow-auto\">";
                html = html.replace(/Resultado de .*?API/, "Resultado de revisi&oacute;n documental");
                if (v.modo_verificacion === "solo_identificacion") {
                    html += "<div class=\"alert alert-info py-1 px-2 mb-2 small\" role=\"status\"><strong>Modo prueba:</strong> esta corrida solo envió el PDF de identificación a la API (sin CURP, NSS, constancia ni acta).</div>";
                }
                var errApi = (v.error_api != null && String(v.error_api).trim() !== "") ? String(v.error_api) : "";
                var checksTotNum = checksTotales != null ? parseInt(checksTotales, 10) : null;
                var sinPuntuaciones = (scoreFrente == null || scoreFrente === "") && (scoreReverso == null || scoreReverso === "");
                var respuestaVaciaApi = !errApi && checksTotNum === 0 && sinPuntuaciones && alertas.length === 0 && v.todo_coincide !== true;
                if (!verificacionEnProceso && errApi) {
                    candidatosDocConsola("error", "verificacion API - error_api (detalle tecnico)", errApi);
                    if (!checksTotNum || checksTotNum <= 0) {
                        bloqueVerif.classList.add("d-none");
                        bloqueVerif.innerHTML = "";
                        return;
                    }
                    errApi = "";
                }
                if (!verificacionEnProceso && respuestaVaciaApi) {
                    candidatosDocConsola("warn", "verificacion API - respuesta sin datos utiles", v);
                    html += "<div class=\"alert alert-warning py-2 px-2 mb-2 small\" role=\"alert\"><strong>Revisi&oacute;n manual requerida.</strong><br><span class=\"text-muted\">La validaci&oacute;n autom&aacute;tica no gener&oacute; datos suficientes. El expediente queda disponible para dictamen manual.</span></div>";
                    respuestaVaciaApi = false;
                }
                if (verificacionEnProceso) {
                    html += "<div class=\"alert alert-info py-2 px-2 mb-2 small\" role=\"status\"><strong>Verificaci&oacute;n en proceso.</strong><br><span class=\"text-muted\">No hay dictamen autom&aacute;tico todav&iacute;a. Si tarda demasiado, quedar&aacute; como API pendiente para reintento.</span></div>";
                    errApi = "";
                    respuestaVaciaApi = false;
                /*
                } else if (false) {
                    html += "";
                } else if (errApi) {
                    candidatosDocConsola("error", "verificación API - error_api (detalle técnico)", errApi);
                    html += "";
                */
                } else if (respuestaVaciaApi) {
                    candidatosDocConsola("warn", "verificación API - respuesta vacía / sin datos útiles (objeto)", v);
                    html += "<div class=\"alert alert-warning py-2 px-2 mb-2 small\" role=\"alert\"><strong>No hubo resultado útil de la verificación automática.</strong><br><span class=\"text-muted\">Intente \"Reintentar API\" más tarde.</span></div>";
                }
                if (errApi || respuestaVaciaApi) {
                    html += "<div class=\"d-grid gap-2 mb-2\"><button type=\"button\" class=\"btn btn-sm btn-outline-primary btn-reintentar-verif-expediente\" id=\"btnReintentarVerifExpediente\" title=\"Volver a ejecutar la verificaci&oacute;n contra la API\"><i class=\"fa fa-sync-alt me-1\"></i>Reintentar API</button></div>";
                }
                html += "<div class=\"row g-2 mb-2 align-items-center\">";
                html += "<div class=\"col-6\"><span class=\"text-muted d-block\">Confianza</span><strong class=\"fs-6 " + confianzaClase + "\">" + confianzaTexto + "</strong></div>";
                html += "<div class=\"col-6\"><span class=\"text-muted d-block\">Checks</span><strong>" + (checksOk != null && checksTotales != null ? checksOk + "/" + checksTotales : "&mdash;") + "</strong></div>";
                html += "<div class=\"col-12\"><span class=\"text-muted d-block\">Coinciden</span><strong class=\"" + (todoCoincide ? "text-success" : (v.todo_coincide === false ? "text-danger" : "text-secondary")) + "\">" + (v.todo_coincide === true ? "S&iacute;" : (v.todo_coincide === false ? "No" : (verificacionEnProceso ? "En proceso" : "&mdash;"))) + "</strong></div>";
                html += "</div>";
                if (alertas.length) {
                    html += "<div class=\"mt-2 pt-2 border-top\"><span class=\"text-muted d-block mb-1\"><strong>Alertas</strong></span><ul class=\"mb-0 ps-3\">";
                    alertas.forEach(function(a) {
                        var txt = typeof a === "string" ? a : String(a);
                        html += "<li class=\"text-warning\">" + escHtmlComparaciones(txt) + "</li>";
                    });
                    html += "</ul></div>";
                }
                html += "</div></div>";
                bloqueVerif.innerHTML = html;
            }

            function normalizarTextoDocModalGlobal(s) {
                var t = String(s === null || s === undefined ? "" : s);
                for (var i = 0; i < 2 && /[\u00c2\u00c3\u00e2\u00ef\u00bf]/.test(t); i++) {
                    try {
                        var reparado = decodeURIComponent(escape(t));
                        if (!reparado || reparado === t) break;
                        t = reparado;
                    } catch (e) {
                        break;
                    }
                }
                return t
                    .replace(/\u2026/g, "...")
                    .replace(/[\u00ab\u00bb\u201c\u201d]/g, "\"")
                    .replace(/\u00ef\u00bf\u00bd/g, "")
                    .replace(/\s+/g, " ")
                    .trim();
            }

            function escHtmlComparaciones(s) {
                var t = normalizarTextoDocModalGlobal(s);
                return t.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
            }

            function esAvisoCurpOcrResuelto(s) {
                var t = normalizarTextoDocModalGlobal(s);
                var k = claveDocModalGlobal(t);
                return /^Advertencia OCR:/i.test(t)
                    || (k.indexOf("CURP LEIDA EN IDENTIFICACION") !== -1 && k.indexOf("NOMBRES COINCIDEN") !== -1)
                    || (k.indexOf("CURP DE IDENTIFICACION") !== -1 && k.indexOf("NOMBRES COINCIDEN") !== -1 && k.indexOf("DOCUMENTO OFICIAL") !== -1);
            }

            /** Solo mostrar la tarjeta si la API guardó comparaciones reales (objeto con al menos una clave conocida). */
            function hayComparacionesEvaluables(v) {
                if (!v || typeof v !== "object") return false;
                var comp = v.comparaciones;
                if (!comp || typeof comp !== "object") return false;
                var conocidas = {
                    curp_id_vs_documento: 1, nombre_frente_vs_reverso: 1, nombre_registro_vs_documentos: 1, nombre_id_vs_curp_pdf: 1,
                    fecha_nac_curp_vs_mrz: 1, curp_pdf_frescura: 1, curp_vs_fiscal: 1, nombre_vs_fiscal: 1, curp_vs_nss: 1, nombre_vs_nss: 1,
                    nombre_vs_acta: 1, fecha_nac_vs_acta: 1, nombre_registro_vs_acta: 1
                };
                for (var k in comp) {
                    if (Object.prototype.hasOwnProperty.call(comp, k) && conocidas[k]) return true;
                }
                return false;
            }

            /** No mezclar comparaciones de una corrida anterior con un fallo reciente de la API (timeout, health-check, etc.). */
            function expedienteVerifApiInconsistente(v) {
                if (!v || typeof v !== "object") return false;
                if (v.error_api != null && String(v.error_api).trim() !== "") return true;
                var ct = v.checks_totales != null ? parseInt(v.checks_totales, 10) : null;
                var sinScores = (v.identificacion_frente_score == null || v.identificacion_frente_score === "") && (v.identificacion_reverso_score == null || v.identificacion_reverso_score === "");
                if (ct === 0 && sinScores && hayComparacionesEvaluables(v)) return true;
                return false;
            }

            function renderComparacionesDocFullWidth(bloqueComp, v) {
                if (!bloqueComp) return;
                if (!v || expedienteVerifApiInconsistente(v) || !hayComparacionesEvaluables(v)) {
                    bloqueComp.classList.add("d-none");
                    bloqueComp.innerHTML = "";
                    return;
                }
                var comp = v.comparaciones || {};
                var gruposDef = [
                    { titulo: "INE", keys: [
                        { k: "curp_id_vs_documento", label: "CURP en credencial INE (frente)" },
                        { k: "nombre_frente_vs_reverso", label: "Nombre INE frente vs nombre INE reverso" },
                        { k: "nombre_id_vs_curp_pdf", label: "Nombre en INE vs nombre en CURP (PDF)" },
                        { k: "nombre_registro_vs_documentos", label: "Nombre del expediente vs nombre en documentos" }
                    ]},
                    { titulo: "CURP", keys: [
                        { k: "fecha_nac_curp_vs_mrz", label: "Fecha de nacimiento en CURP vs fecha en reverso INE" },
                        { k: "curp_pdf_frescura", label: "CURP en PDF vigente (no mayor a 3 meses)", kind: "frescura" },
                        { k: "curp_vs_fiscal", label: "CURP del PDF vs CURP en constancia fiscal" }
                    ]},
                    { titulo: "Fiscal / NSS", keys: [
                        { k: "nombre_vs_fiscal", label: "Nombre en constancia fiscal vs nombre en INE" },
                        { k: "curp_vs_fiscal", label: "CURP en constancia vs CURP en INE" },
                        { k: "nombre_vs_nss", label: "Nombre en NSS vs nombre en INE" },
                        { k: "curp_vs_nss", label: "CURP en NSS vs CURP en INE" }
                    ]},
                    { titulo: "Acta", keys: [
                        { k: "nombre_vs_acta", label: "Nombre en INE vs nombre en acta" },
                        { k: "fecha_nac_vs_acta", label: "Fecha de nacimiento INE vs fecha en acta" },
                        { k: "nombre_registro_vs_acta", label: "Nombre del expediente vs nombre en acta" }
                    ]}
                ];

                function esAdvertenciaOcr(entry) {
                    return !!(entry && (entry.advertencia_ocr === true || String(entry.nota || "").toLowerCase().indexOf("ocr") !== -1));
                }

                function lineaHtml(entry, def) {
                    var kind = def.kind || "coincide";
                    var ok = null;
                    var warn = false;
                    if (kind === "frescura") {
                        if (!entry || entry.es_reciente === undefined || entry.es_reciente === null) return "";
                        ok = entry.es_reciente === true;
                    } else {
                        if (!entry || !Object.prototype.hasOwnProperty.call(entry, "coincide")) return "";
                        if (entry.coincide === true) ok = true;
                        else if (entry.coincide === false) ok = false;
                        else {
                            return "<div class=\"small mb-1\"><span class=\"text-secondary\">—</span> <span class=\"text-muted\">" + escHtmlComparaciones(def.label) + " <span class=\"fst-italic\">(sin evaluar)</span></span></div>";
                        }
                        warn = ok && esAdvertenciaOcr(entry);
                    }
                    var sym = warn ? "<span class=\"text-warning\">!</span>" : (ok ? "<span class=\"text-success\">&#10003;</span>" : "<span class=\"text-danger\">&#10007;</span>");
                    var txtCls = warn ? "text-warning" : (ok ? "text-muted" : "text-danger");
                    return "<div class=\"small mb-1\">" + sym + " <span class=\"" + txtCls + "\">" + escHtmlComparaciones(def.label) + "</span></div>";
                }

                var totalOk = 0, totalLin = 0, algunaTarjeta = false;
                var tarjetas = [];
                gruposDef.forEach(function(gr) {
                    var lineas = [];
                    var okG = 0, nG = 0, failG = false;
                    gr.keys.forEach(function(def) {
                        var entry = comp[def.k];
                        if (def.kind === "frescura") {
                            if (!entry || entry.es_reciente === undefined || entry.es_reciente === null) return;
                            lineas.push(lineaHtml(entry, def));
                            nG++;
                            totalLin++;
                            if (entry.es_reciente === true) { okG++; totalOk++; }
                            else failG = true;
                            return;
                        }
                        if (!entry || !Object.prototype.hasOwnProperty.call(entry, "coincide")) return;
                        lineas.push(lineaHtml(entry, def));
                        if (entry.coincide === true || entry.coincide === false) {
                            nG++;
                            totalLin++;
                            if (entry.coincide === true) { okG++; totalOk++; }
                            else failG = true;
                        }
                    });
                    if (lineas.length === 0) return;
                    algunaTarjeta = true;
                    var scoreTxt = nG > 0 ? (okG + "/" + nG + (okG === nG ? " OK" : " X")) : "-";
                    var scoreCls = failG ? "text-danger" : "text-success";
                    var borde = failG ? " border border-danger" : "";
                    tarjetas.push("<div class=\"col-12 col-md-6 col-xl-3\"><div class=\"card p-2 h-100" + borde + "\"><div class=\"d-flex justify-content-between align-items-center mb-2\"><span class=\"fw-semibold fs-6\">" + escHtmlComparaciones(gr.titulo) + "</span><span class=\"small " + scoreCls + "\">" + escHtmlComparaciones(scoreTxt) + "</span></div>" + lineas.join("") + "</div></div>");
                });

                if (!algunaTarjeta) {
                    bloqueComp.classList.add("d-none");
                    bloqueComp.innerHTML = "";
                    return;
                }

                var alertas = Array.isArray(v.alertas) ? v.alertas : [];
                var alertasCriticas = [];
                alertas.forEach(function(a) {
                    var txt = typeof a === "string" ? a : String(a);
                    if (esAvisoCurpOcrResuelto(txt)) return;
                    alertasCriticas.push(txt);
                });
                var html = "<div class=\"card border shadow-none\"><div class=\"card-body py-2 small\">";
                html += "<div class=\"d-flex flex-wrap justify-content-between align-items-center gap-2 mb-2\">";
                html += "<span class=\"fw-semibold small\">Comparaciones entre documentos</span>";
                html += "<span>";
                if (totalLin > 0) html += "<span class=\"badge bg-success me-1\">" + totalOk + "/" + totalLin + " coinciden</span>";
                if (alertasCriticas.length) html += "<span class=\"badge bg-danger\">" + alertasCriticas.length + " alerta" + (alertasCriticas.length === 1 ? "" : "s") + "</span>";
                html += "</span></div>";
                if (alertasCriticas.length) {
                    html += "<div class=\"alert alert-danger py-1 px-2 mb-2\" role=\"alert\"><div class=\"d-flex flex-wrap gap-2 small\">";
                    alertasCriticas.forEach(function(a) { html += "<span>&#10007; " + escHtmlComparaciones(a) + "</span>"; });
                    html += "</div></div>";
                }
                html += "<div class=\"row g-2 mb-0\">" + tarjetas.join("") + "</div></div></div>";
                bloqueComp.classList.remove("d-none");
                bloqueComp.innerHTML = html;
            }

            function claveDocModalGlobal(s) {
                try {
                    return String(s === null || s === undefined ? "" : s)
                        .normalize("NFD")
                        .replace(/[\u0300-\u036f]/g, "")
                        .toUpperCase()
                        .replace(/\s+/g, " ")
                        .trim();
                } catch (e) {
                    return String(s === null || s === undefined ? "" : s).toUpperCase();
                }
            }

            function badgeVerificacionDoc(tipoDoc, v) {
                if (!v || !tipoDoc) return "";
                if (expedienteVerifApiInconsistente(v)) return "";
                var t = claveDocModalGlobal(tipoDoc);
                if (t.indexOf("REVERSO") !== -1) { var r = v.identificacion_reverso_score; if (r == null) return ""; return "<span class=\"badge bg-primary ms-1\" title=\"Veracidad con el candidato\">" + r + "%</span>"; }
                if (t === "IDENTIFICACION OFICIAL") { var s = v.identificacion_frente_score; if (s == null) return ""; return "<span class=\"badge bg-primary ms-1\" title=\"Veracidad con el candidato\">" + s + "%</span>"; }
                if (!hayComparacionesEvaluables(v)) return "";
                var comp = v.comparaciones || {};
                if (t.indexOf("CURP") !== -1 && t.indexOf("ACTA") === -1) { var c1 = comp.nombre_id_vs_curp_pdf || comp.curp_id_vs_documento; if (c1 && c1.coincide !== undefined) return c1.coincide ? "<span class=\"badge bg-success ms-1\" title=\"Coincide con INE\">Coincide</span>" : "<span class=\"badge bg-danger ms-1\" title=\"No coincide\">No coincide</span>"; }
                if (t.indexOf("CONSTANCIA") !== -1 || t.indexOf("FISCAL") !== -1) { var c2 = comp.curp_vs_fiscal || comp.nombre_vs_fiscal; if (c2 && c2.coincide !== undefined) return c2.coincide ? "<span class=\"badge bg-success ms-1\">Coincide</span>" : "<span class=\"badge bg-danger ms-1\">No coincide</span>"; }
                if (t.indexOf("NSS") !== -1 || t.indexOf("SEGURIDAD SOCIAL") !== -1) { var c3 = comp.curp_vs_nss || comp.nombre_vs_nss; if (c3 && c3.coincide !== undefined) return c3.coincide ? "<span class=\"badge bg-success ms-1\">Coincide</span>" : "<span class=\"badge bg-danger ms-1\">No coincide</span>"; }
                if (t.indexOf("ACTA") !== -1) { var c4 = comp.nombre_vs_acta || comp.fecha_nac_vs_acta; if (c4 && c4.coincide !== undefined) return c4.coincide ? "<span class=\"badge bg-success ms-1\">Coincide</span>" : "<span class=\"badge bg-danger ms-1\">No coincide</span>"; }
                return "";
            }

            function eliminarDocYRecargarModal(idDoc, idCandidato, comentario) {
                if (typeof Swal !== "undefined") {
                    Swal.fire({
                        title: "Procesando...",
                        html: "Eliminando documento, guardando el motivo y notificando al candidato.",
                        allowOutsideClick: false,
                        allowEscapeKey: false,
                        showConfirmButton: false,
                        didOpen: function() { Swal.showLoading(); }
                    });
                }
                fetch("/caphum/eliminarDocumentoCandidato", { method: "POST", headers: { "Content-Type": "application/json", "Accept": "application/json", "X-Requested-With": "XMLHttpRequest" }, body: JSON.stringify({ id: idDoc, comentario: comentario || "" }) })
                .then(function(r){ return r.json(); }).then(function(res) {
                    if (typeof Swal !== "undefined") Swal.close();
                    if (res.success) { if (typeof Swal !== "undefined") Swal.fire({ icon: "success", title: "Eliminado", text: res.mensaje || "Documento eliminado." }); cargarDocumentosModal(idCandidato); }
                    else { if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: res.mensaje || "No se pudo eliminar." }); }
                }).catch(function() {
                    if (typeof Swal !== "undefined") Swal.close();
                    if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: "Error de conexión." });
                });
            }

            function subirDocumentoManualCandidato(idCandidato, tipoNum, tipoNombre) {
                idCandidato = parseInt(idCandidato, 10) || 0;
                tipoNum = parseInt(tipoNum, 10) || 0;
                if (!idCandidato || !tipoNum) return;
                var input = document.createElement("input");
                input.type = "file";
                input.accept = "application/pdf,.pdf";
                input.style.display = "none";
                document.body.appendChild(input);
                input.addEventListener("change", function() {
                    var archivo = input.files && input.files[0] ? input.files[0] : null;
                    try { document.body.removeChild(input); } catch (e0) {}
                    if (!archivo) return;
                    if (!/\.pdf$/i.test(archivo.name || "")) {
                        if (typeof Swal !== "undefined") Swal.fire({ icon: "warning", title: "Archivo no permitido", text: "Solo se acepta PDF." });
                        return;
                    }
                    var fd = new FormData();
                    fd.append("id_candidato", String(idCandidato));
                    fd.append("tipo_documento", String(tipoNum));
                    fd.append("archivo", archivo);
                    if (typeof Swal !== "undefined") {
                        Swal.fire({
                            title: "Subiendo documento...",
                            html: "Guardando " + (tipoNombre || "documento") + " en el expediente.",
                            allowOutsideClick: false,
                            allowEscapeKey: false,
                            showConfirmButton: false,
                            didOpen: function() { Swal.showLoading(); }
                        });
                    }
                    fetch("/caphum/subirDocumentoManualCandidato", {
                        method: "POST",
                        headers: { "X-Requested-With": "XMLHttpRequest", "Accept": "application/json" },
                        body: fd
                    })
                    .then(function(r) { return r.json(); })
                    .then(function(res) {
                        if (typeof Swal !== "undefined") Swal.close();
                        if (res && res.success) {
                            if (typeof Swal !== "undefined") {
                                Swal.fire({ icon: "success", title: "Documento agregado", text: res.mensaje || "Documento subido manualmente.", timer: 2400, showConfirmButton: false });
                            }
                            cargarDocumentosModal(idCandidato);
                            if (typeof getCandidatos === "function") getCandidatos();
                        } else if (typeof Swal !== "undefined") {
                            Swal.fire({ icon: "error", title: "No se pudo subir", text: (res && res.mensaje) ? res.mensaje : "No se pudo guardar el documento." });
                        }
                    })
                    .catch(function() {
                        if (typeof Swal !== "undefined") {
                            Swal.fire({ icon: "error", title: "Error", text: "No se pudo conectar con el servidor." });
                        }
                    });
                });
                input.click();
            }

            function renderListaDocumentos(lista, cargando, vacio, datos, verif, idCandidato) {
                if (!lista) return;
                disposeDocModalTooltips();
                if (!document.getElementById("docModalTooltipStyle")) {
                    var stDocTooltip = document.createElement("style");
                    stDocTooltip.id = "docModalTooltipStyle";
                    stDocTooltip.textContent = ".doc-modal-tooltip{--bs-tooltip-max-width:420px}.doc-modal-tooltip .tooltip-inner{max-width:420px;text-align:left;padding:.65rem .75rem}.doc-modal-tooltip table{color:inherit;margin:0}.doc-modal-tooltip td{padding:.25rem .35rem!important;border-color:rgba(255,255,255,.22)!important}.doc-modal-tooltip .text-muted{color:rgba(255,255,255,.78)!important}";
                    document.head.appendChild(stDocTooltip);
                }
                if (cargando) cargando.classList.add("d-none");
                lista.innerHTML = "";
                datos = Array.isArray(datos) ? datos : [];
                if (!datos || datos.length === 0) { if (vacio) vacio.classList.add("d-none"); }
                if (vacio) vacio.classList.add("d-none");
                function escHtml(s) { var t = normalizarTextoDocModal(s); return t.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;"); }
                function normalizarTextoDocModal(s) {
                    var t = String(s === null || s === undefined ? "" : s);
                    for (var i = 0; i < 2 && /[\u00c2\u00c3\u00e2\u00ef\u00bf]/.test(t); i++) {
                        try {
                            var reparado = decodeURIComponent(escape(t));
                            if (!reparado || reparado === t) break;
                            t = reparado;
                        } catch (e) {
                            break;
                        }
                    }
                    return t
                        .replace(/IDENTIFICACI\u00c3\u201cN/gi, "IDENTIFICACION")
                        .replace(/IDENTIFICACI\u00c3\u0192\u00e2\u20ac\u0153N/gi, "IDENTIFICACION")
                        .replace(/IDENTIFICACI\u00c4\u201cN/gi, "IDENTIFICACION")
                        .replace(/N\u00c3\u0161MERO/gi, "NUMERO")
                        .replace(/N\u00c3\u0192\u00c5\u00a1MERO/gi, "NUMERO")
                        .replace(/DOCUMENTACI\u00c4\u201cN/gi, "DOCUMENTACION")
                        .replace(/SITUACI\u00c4\u201cN/gi, "SITUACION")
                        .replace(/VERIFICACI\u00c4\u201cN/gi, "VERIFICACION")
                        .replace(/REVISI\u00c4\u201cN/gi, "REVISION")
                        .replace(/\u00c3\u201c/g, "O")
                        .replace(/\u00c3\u0161/g, "U")
                        .replace(/\u00c3\u00a9/g, "e")
                        .replace(/\u00c3\u00b3/g, "o")
                        .replace(/\u00c3\u00a1/g, "a")
                        .replace(/\u00c3\u00ad/g, "i")
                        .replace(/\u00c3\u00ba/g, "u")
                        .replace(/\u00c3\u2018/g, "N")
                        .replace(/\u00c3\u00b1/g, "n")
                        .replace(/\u00c3\u201a\u00c2\u00b7/g, " - ")
                        .replace(/\u00c2\u00b7/g, " - ")
                        .replace(/\u2026/g, "...")
                        .replace(/[\u00ab\u00bb\u201c\u201d]/g, "\"")
                        .replace(/\u00ef\u00bf\u00bd/g, "")
                        .replace(/\s+/g, " ")
                        .trim();
                }
                function claveDocModal(s) {
                    return normalizarTextoDocModal(s).normalize("NFD").replace(/[\u0300-\u036f]/g, "").toUpperCase();
                }
                var documentosRequeridosManual = [
                    [1, "SOLICITUD INTERNA"],
                    [2, "CV O SOLICITUD DE TRABAJO"],
                    [3, "ACTA DE NACIMIENTO Certificada"],
                    [4, "CURP"],
                    [5, "IDENTIFICACION OFICIAL"],
                    [6, "COMPROBANTE DE DOMICILIO"],
                    [7, "CONSTANCIA DE SITUACION FISCAL"],
                    [8, "NUMERO DE SEGURIDAD SOCIAL"],
                    [9, "HOJA DE RETENCION FONACOT O INFONAVIT"],
                    [10, "ESTADO DE CUENTA"]
                ];
                function numeroTipoDocModal(tipo) {
                    var t = claveDocModal(tipo);
                    if (t.indexOf("SOLICITUD INTERNA") !== -1) return 1;
                    if (t.indexOf("CV") !== -1 || t.indexOf("SOLICITUD DE TRABAJO") !== -1) return 2;
                    if (t.indexOf("ACTA DE NACIMIENTO") !== -1) return 3;
                    if (t === "CURP" || (t.indexOf("CURP") !== -1 && t.indexOf("ACTA") === -1)) return 4;
                    if (t.indexOf("IDENTIFICACION OFICIAL") !== -1) return 5;
                    if (t.indexOf("COMPROBANTE DE DOMICILIO") !== -1) return 6;
                    if (t.indexOf("CONSTANCIA") !== -1 && t.indexOf("FISCAL") !== -1) return 7;
                    if (t.indexOf("SEGURIDAD SOCIAL") !== -1 || t.indexOf("NSS") !== -1) return 8;
                    if (t.indexOf("FONACOT") !== -1 || t.indexOf("INFONAVIT") !== -1) return 9;
                    if (t.indexOf("ESTADO DE CUENTA") !== -1) return 10;
                    return 0;
                }
                var tiposPresentesManual = {};
                datos.forEach(function(dPresente) {
                    var nPresente = numeroTipoDocModal(dPresente && dPresente.tipo_documento ? dPresente.tipo_documento : "");
                    if (nPresente > 0) tiposPresentesManual[nPresente] = true;
                });
                datos.forEach(function(d) {
                    var item = document.createElement("div");
            item.className = "list-group-item list-group-item-action d-flex justify-content-between align-items-center";
            var fecha = d.fecha_carga ? new Date(d.fecha_carga).toLocaleDateString("es-MX") : "";
