                        return t.split(" ").filter(function(w){ return w.length > 2; });
                    };
                    var n1 = norm(verif.nombre_ocr), n2 = norm(nombreTicket);
                    var comunes = n1.filter(function(w){ return n2.indexOf(w) !== -1; });
