                el.textContent = "";
                el.className = "alert alert-secondary small py-2 mb-2 d-none";
            }
            /** Detalle técnico solo en consola; no mostrar cadenas largas a usuarios finales. */
            function registrarTrazaDocModalTecnico(titulo, datos) {
                try {
                    if (datos !== undefined && datos !== null) {
                        candidatosDocConsola("info", titulo, datos);
                    } else {
                        candidatosDocConsola("info", titulo);
                    }
                } catch (e2) {}
            }
            /** Mensaje breve en la franja del modal (solo lo que debe ver Capital Humano). */
            function setDocModalApiTraceUsuario(message, kind) {
                var el = document.getElementById("modalDocumentacionCandidatoApiTrace");
                if (!el) return;
                if (!message || String(message).trim() === "") {
                    clearDocModalApiTrace();
                    return;
                }
                var map = { wait: "alert-info", ok: "alert-success", err: "alert-danger", warn: "alert-warning", neutral: "alert-secondary" };
                el.className = "alert small py-2 mb-2 " + (map[kind] || map.neutral);
                el.textContent = String(message);
                el.classList.remove("d-none");
            }

            function ejecutarVerificacionExpedienteCandidatoPost(idC, soloIdentificacion, btn) {
                if (!idC) return;
                var prevHtml = btn ? btn.innerHTML : "";
                if (btn) { btn.disabled = true; btn.innerHTML = "<i class=\"fa fa-spinner fa-spin\"></i>"; }
                var fd = new FormData();
                fd.append("id_candidato", String(idC));
                fd.append("async", "1");
                if (soloIdentificacion) {
                    fd.append("solo_identificacion", "1");
                }
                var ctrl = new AbortController();
                var toMs = 30000;
                var tid = setTimeout(function() { try { ctrl.abort(); } catch (e) {} }, toMs);
                var t0 = (typeof performance !== "undefined" && performance.now) ? performance.now() : Date.now();
                candidatosDocConsola("info", "verificarExpedienteCandidato - inicio POST", { id_candidato: idC, url: "/caphum/verificarExpedienteCandidato", timeout_ms: toMs, solo_identificacion: !!soloIdentificacion });
                registrarTrazaDocModalTecnico("verificarExpedienteCandidato - POST (detalle)", { id_candidato: idC, url: "/caphum/verificarExpedienteCandidato", timeout_ms: toMs, solo_identificacion: !!soloIdentificacion });
                setDocModalApiTraceUsuario("Verificación iniciada en segundo plano. Si no responde pronto, quedará como API pendiente para reintento.", "wait");
                fetch("/caphum/verificarExpedienteCandidato", { method: "POST", body: fd, headers: { "X-Requested-With": "XMLHttpRequest" }, signal: ctrl.signal })
                    .then(function(r) {
                        clearTimeout(tid);
                        var ms = (typeof performance !== "undefined" && performance.now) ? Math.round(performance.now() - t0) : null;
                        return r.text().then(function(body) {
                            var res;
                            try { res = body ? JSON.parse(body) : {}; } catch (e) {
                                candidatosDocConsola("error", "verificarExpedienteCandidato - respuesta no JSON", { id_candidato: idC, http_status: r.status, ms: ms, body_head: body ? String(body).slice(0, 2500) : "", parse_error: String(e) });
                                registrarTrazaDocModalTecnico("verificarExpedienteCandidato - no JSON", { http_status: r.status, ms: ms, parse_error: String(e) });
                                setDocModalApiTraceUsuario("No se pudo leer la respuesta del servidor. Cierre el recuadro e inténtelo de nuevo.", "err");
                                throw e;
                            }
                            return { r: r, res: res, ms: ms };
                        });
                    })
                    .then(function(box) {
                        var r = box.r, res = box.res, ms = box.ms;
                        var linea = "HTTP " + r.status + (ms != null ? " - " + ms + " ms" : "") + ". ";
                        var nivelCons = res && res.success ? "log" : "warn";
                        candidatosDocConsola(nivelCons, "verificarExpedienteCandidato - respuesta", { id_candidato: idC, http_status: r.status, ms: ms, success: !!(res && res.success), mensaje: res && res.mensaje, datos: res && res.datos });
                        registrarTrazaDocModalTecnico("verificarExpedienteCandidato - respuesta (técnico)", { id_candidato: idC, resumen_http: linea, success: !!(res && res.success), mensaje: res && res.mensaje, datos: res && res.datos });
                        if (res && res.success) {
                            clearDocModalApiTrace();
                        } else {
                            setDocModalApiTraceUsuario("No se pudo completar la verificación. Puede intentar \"Reintentar API\" más tarde.", "warn");
                        }
                        if (typeof Swal !== "undefined") {
                            if (res && res.success) {
                                Swal.fire({ icon: "success", title: "Verificación", text: res.mensaje || "Listo.", toast: true, position: "top-end", showConfirmButton: false, timer: 2600 });
                            } else {
                                Swal.fire({ icon: "warning", title: "Verificación", text: (res && res.mensaje) ? res.mensaje : "No se pudo completar la verificación.", toast: true, position: "top-end", showConfirmButton: true });
                            }
                        }
                        cargarDocumentosModal(idC);
                    })
                    .catch(function(err) {
                        clearTimeout(tid);
                        candidatosDocConsola("error", "verificarExpedienteCandidato - error (catch)", { id_candidato: idC, name: err && err.name, message: err && err.message, stack: err && err.stack });
                        registrarTrazaDocModalTecnico("verificarExpedienteCandidato - catch (técnico)", { id_candidato: idC, name: err && err.name, message: err && err.message, stack: err && err.stack, timeout_ms: toMs });
                        if (typeof Swal !== "undefined") {
                            var msg = (err && err.name === "AbortError") ? "La verificación tardó demasiado. Cuando la red o el servidor estén disponibles, use \"Reintentar API\"." : "No hubo respuesta del servidor. Revise su conexión e inténtelo de nuevo.";
                            Swal.fire({ icon: "error", title: "Error", text: msg, toast: true, position: "top-end", showConfirmButton: true });
                        }
                        setDocModalApiTraceUsuario((err && err.name === "AbortError") ? "Tiempo de espera agotado. Use \"Reintentar API\" más tarde." : "Error de conexión o del servidor.", "err");
                        cargarDocumentosModal(idC);
                    })
                    .finally(function() {
                        clearTimeout(tid);
                        if (btn) { btn.disabled = false; btn.innerHTML = prevHtml; }
                    });
            }

            function reintentarVerificacionExpedienteApi(btnOrigen) {
                var modal = document.getElementById("modalDocumentacionCandidato");
                var idC = modal && modal.dataset.idCandidato ? parseInt(modal.dataset.idCandidato, 10) : 0;
                if (!idC) return;
                var chkSolo = document.getElementById("chkCandidatoVerifSoloIdentificacion");
                var solo = !!(chkSolo && chkSolo.checked);
                var btn = btnOrigen || document.getElementById("btnReintentarVerifExpediente");
                ejecutarVerificacionExpedienteCandidatoPost(idC, solo, btn);
            }

            function cargarDocumentosModal(idCandidato, opts) {
                opts = opts || {};
                if (docModalFetchInFlight) {
                    if (opts.fromPoll) {
                        return;
                    }
                    clearDocModalPoll();
                    return;
                }
                docModalFetchInFlight = true;
                if (!opts.fromPoll) {
                    clearDocModalPoll();
                }
                var lista = document.getElementById("modalDocumentacionCandidatoLista");
                var cargando = document.getElementById("modalDocumentacionCandidatoCargando");
                var vacio = document.getElementById("modalDocumentacionCandidatoVacio");
                var bloqueVerif = document.getElementById("modalDocumentacionCandidatoVerificacion");
                var bloqueComp = document.getElementById("modalDocumentacionCandidatoComparaciones");
                var bloqueMetricas = document.getElementById("modalDocumentacionCandidatoMetricas");
                var bloqueAccionVerificar = document.getElementById("modalDocumentacionCandidatoAccionVerificar");
                var bloqueAccionesProceso = document.getElementById("modalDocumentacionCandidatoAccionesProceso");
                var listaTieneContenidoPrevio = !!(lista && lista.children && lista.children.length > 0);
                var mostrarLoaderPrincipal = !opts.fromPoll && !listaTieneContenidoPrevio;
                if (cargando && mostrarLoaderPrincipal) {
                    cargando.classList.remove("d-none");
                }
                var urlList = "/caphum/getDocumentosCandidatoList?id_candidato=" + encodeURIComponent(String(idCandidato));
                var t0List = (typeof performance !== "undefined" && performance.now) ? performance.now() : Date.now();
                if (!opts.fromPoll) {
                    clearDocModalApiTrace();
                    registrarTrazaDocModalTecnico("getDocumentosCandidatoList - GET (técnico)", { id_candidato: idCandidato, url: urlList });
                }
                candidatosDocConsola("info", "getDocumentosCandidatoList - inicio", { id_candidato: idCandidato, fromPoll: !!opts.fromPoll, url: urlList });
                fetch(urlList, { headers: { "X-Requested-With": "XMLHttpRequest" } }).then(function(r) {
                    var ms = (typeof performance !== "undefined" && performance.now) ? Math.round(performance.now() - t0List) : null;
                    var cacheHdr = r.headers.get("X-Doc-List-Cache") || "";
                    return r.text().then(function(body) {
                        var res;
                        try { res = body ? JSON.parse(body) : {}; } catch (e) {
                            candidatosDocConsola("error", "getDocumentosCandidatoList - JSON inválido", { id_candidato: idCandidato, http_status: r.status, ms: ms, cache: cacheHdr, body_head: body ? String(body).slice(0, 2500) : "", parse_error: String(e) });
                            registrarTrazaDocModalTecnico("getDocumentosCandidatoList - JSON inválido (técnico)", { http_status: r.status, ms: ms, cache: cacheHdr, parse_error: String(e) });
                            var bodyTxt = String(body || "");
                            var pareceHtml = r.redirected || /<(html|body|!doctype)/i.test(bodyTxt);
                            var msgJson = pareceHtml
                                ? "No se pudo cargar la documentaci&oacute;n porque la sesi&oacute;n o los permisos no devolvieron JSON. Recargue la p&aacute;gina e intente de nuevo."
                                : "No se pudo cargar la lista de documentos por una respuesta inv&aacute;lida del servidor.";
                            setDocModalApiTraceUsuario(msgJson, "err");
                            var errJson = new Error(msgJson);
                            errJson.name = "DocListInvalidJson";
                            errJson.userMessage = msgJson;
                            throw errJson;
                        }
                        return { r: r, res: res, ms: ms, cacheHdr: cacheHdr };
                    });
                }).then(function(box) {
                    var modalActualListado = document.getElementById("modalDocumentacionCandidato");
                    if (modalActualListado && modalActualListado.dataset.idCandidato && String(modalActualListado.dataset.idCandidato) !== String(idCandidato)) {
                        return;
                    }
                    var r = box.r, res = box.res, ms = box.ms, cacheHdr = box.cacheHdr;
                    var cacheNote = cacheHdr ? (" - caché listado: " + cacheHdr) : "";
                    if (!res.success) {
                        registrarTrazaDocModalTecnico("getDocumentosCandidatoList - success=false (técnico)", { http_status: r.status, ms: ms, cache: cacheHdr, mensaje: res.mensaje || null });
                        setDocModalApiTraceUsuario("No se pudo obtener la documentación del candidato.", "warn");
                        var errListado = new Error(res.mensaje || "No se pudo obtener la documentación del candidato.");
                        errListado.name = "DocListBusinessError";
                        errListado.userMessage = res.mensaje || "No se pudo obtener la documentación del candidato.";
                        throw errListado;
                    } else {
                        var nDocs = (res.datos && res.datos.documentos) ? res.datos.documentos.length : (res.datos && Array.isArray(res.datos) ? res.datos.length : 0);
                        var verifPrev = (res.datos && res.datos.verificacion_expediente) ? res.datos.verificacion_expediente : null;
                        var errApi = verifPrev && verifPrev.error_api ? String(verifPrev.error_api).trim() : "";
                        var baseOk = "Listado: HTTP " + r.status + (ms != null ? " - " + ms + " ms" : "") + cacheNote + ". JSON OK - " + nDocs + " documento(s).";
                        registrarTrazaDocModalTecnico("getDocumentosCandidatoList - resumen (técnico)", { id_candidato: idCandidato, texto: baseOk, error_api: errApi || null, verificacion_en_bd: !!verifPrev, expediente_completo: !!(res.datos && res.datos.metricas && res.datos.metricas.expediente_completo) });
                        if (errApi) {
                            clearDocModalApiTrace();
                        } else if (verifPrev) {
                            clearDocModalApiTrace();
                        } else if (res.datos && res.datos.metricas && res.datos.metricas.expediente_completo) {
                            setDocModalApiTraceUsuario("Expediente completo. La verificación automática corre en segundo plano; si no responde quedará como API pendiente.", "neutral");
                        } else {
                            clearDocModalApiTrace();
                        }
                    }
                    var docs = (res.datos && res.datos.documentos) ? res.datos.documentos : (res.datos && Array.isArray(res.datos) ? res.datos : []);
                    var verif = (res.datos && res.datos.verificacion_expediente) ? res.datos.verificacion_expediente : null;
                    var metricas = (res.datos && res.datos.metricas) ? res.datos.metricas : null;
                    if (lista && docs.length > 0) {
                        var escBasico = function(s) {
                            return String(s === null || s === undefined ? "" : s)
                                .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
                        };
                        if (cargando) cargando.classList.add("d-none");
                        if (vacio) vacio.classList.add("d-none");
                        lista.innerHTML = docs.map(function(d) {
                            var disponible = String(d.archivo_disponible == null ? "1" : d.archivo_disponible) !== "0";
                            var fechaBasica = d.fecha_carga ? (" - " + new Date(d.fecha_carga).toLocaleDateString("es-MX")) : "";
                            return "<div class=\"list-group-item d-flex justify-content-between align-items-center\">" +
                                "<div><strong>" + escBasico(d.tipo_documento || "Documento") + "</strong><br><small class=\"text-muted\">" + escBasico(d.nombre_archivo || "") + fechaBasica + "</small></div>" +
                                (disponible ? "<span class=\"badge bg-light text-dark\">PDF</span>" : "<span class=\"badge bg-secondary\">Solo registro local</span>") +
                                "</div>";
                        }).join("");
                    }

                    candidatosDocConsola("log", "getDocumentosCandidatoList - respuesta", { id_candidato: idCandidato, http_status: r.status, ms: ms, cache_listado: cacheHdr || null, success: !!res.success, mensaje: res.mensaje || null, n_documentos: docs.length, metricas: metricas || null, verificacion_resumen: verif ? { error_api: verif.error_api || null, checks_ok: verif.checks_ok, checks_totales: verif.checks_totales, todo_coincide: verif.todo_coincide } : null });
                    if (!res.success) {
                        candidatosDocConsola("warn", "getDocumentosCandidatoList - success=false (objeto completo)", res);
                    }
                    if (verif && verif.error_api != null && String(verif.error_api).trim() !== "") {
                        candidatosDocConsola("warn", "verificación expediente - último intento falló (detalle en BD; use Reintentar verificación si ya corrigió la API)", { id_candidato: idCandidato, error_api: String(verif.error_api) });
                    }

                    try {
                    // Actualizar el Map global con los nuevos datos
                    actualizarDocumentosEnMap(idCandidato, {
                        documentos: docs,
                        verificacion_expediente: verif,
                        metricas: metricas
                    });

                    if (verif && verif.verificacion_en_proceso !== true) {
                        clearDocModalPoll();
                    }

                    renderListaDocumentos(lista, cargando, vacio, docs, verif, idCandidato);
                    renderMetricasDoc(bloqueMetricas, metricas);
                    renderAccionesProcesoCandidato(bloqueAccionesProceso, metricas, idCandidato);
                    if (bloqueAccionVerificar) bloqueAccionVerificar.classList.add("d-none");
                    if (verif) {
                        renderVerificacionApiCard(bloqueVerif, verif);
                        renderComparacionesDocFullWidth(bloqueComp, verif);
                    } else if (metricas && metricas.expediente_completo) {
                        if (bloqueVerif) { bloqueVerif.classList.remove("d-none"); bloqueVerif.innerHTML = "<div class=\"alert alert-info small mb-0\"><i class=\"fa fa-hourglass-half me-1\"></i>Verificación automática en proceso. Si la API no entrega resultado pronto, quedará como API pendiente para reintento.</div>"; }
                        if (bloqueComp) { bloqueComp.classList.add("d-none"); bloqueComp.innerHTML = ""; }
                    } else {
                        if (bloqueVerif) { bloqueVerif.classList.add("d-none"); bloqueVerif.innerHTML = ""; }
                        if (bloqueComp) { bloqueComp.classList.add("d-none"); bloqueComp.innerHTML = ""; }
                    }
                    maybeScheduleDocModalPoll(idCandidato, metricas, verif, opts);
                    } catch (uiErr) {
                        candidatosDocConsola("error", "getDocumentosCandidatoList - error al pintar modal", { id_candidato: idCandidato, name: uiErr && uiErr.name, message: uiErr && uiErr.message, stack: uiErr && uiErr.stack });
                        registrarTrazaDocModalTecnico("getDocumentosCandidatoList - error UI (tecnico)", { name: uiErr && uiErr.name, message: uiErr && uiErr.message });
                        if (cargando) cargando.classList.add("d-none");
                        if (vacio) vacio.classList.toggle("d-none", docs.length > 0);
                        if (lista && docs.length > 0) {
                            var escUiFallback = function(s) {
                                return String(s === null || s === undefined ? "" : s)
                                    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
                            };
                            lista.innerHTML = docs.map(function(d) {
                                return "<div class=\"border rounded p-2 mb-1\"><strong>" + escUiFallback(d.tipo_documento || "Documento") + "</strong><br><small class=\"text-muted\">" + escUiFallback(d.nombre_archivo || "") + "</small></div>";
                            }).join("");
                        }
                    }
                }).catch(function(err) {
                    var modalActualCatch = document.getElementById("modalDocumentacionCandidato");
                    if (modalActualCatch && modalActualCatch.dataset.idCandidato && String(modalActualCatch.dataset.idCandidato) !== String(idCandidato)) {
                        return;
                    }
                    candidatosDocConsola("error", "getDocumentosCandidatoList - catch", { id_candidato: idCandidato, name: err && err.name, message: err && err.message, stack: err && err.stack });
                    if (!opts.fromRetry && (!err || !err.userMessage)) {
                        if (cargando) cargando.classList.add("d-none");
                        setTimeout(function() {
                            cargarDocumentosModal(idCandidato, Object.assign({}, opts, { fromRetry: true }));
                        }, 450);
                        return;
                    }
                    if (err && err.userMessage) {
                        setDocModalApiTraceUsuario(err.userMessage, "err");
                    } else if (!err || (err.name !== "SyntaxError" && err.message && String(err.message).indexOf("JSON") === -1)) {
                        registrarTrazaDocModalTecnico("getDocumentosCandidatoList - red/catch (técnico)", { name: err && err.name, message: err && err.message });
                        setDocModalApiTraceUsuario("No se pudo consultar el listado de documentos. El servidor no respondió correctamente; recargue la página e intente de nuevo.", "err");
                    }
                    if (cargando) {
                        cargando.classList.add("d-none");
                    }
                    if (vacio) vacio.classList.add("d-none");
                    if (!listaTieneContenidoPrevio && lista) {
                        lista.innerHTML = "";
                        if (bloqueAccionesProceso) { bloqueAccionesProceso.classList.add("d-none"); bloqueAccionesProceso.innerHTML = ""; }
                        if (bloqueMetricas) { bloqueMetricas.classList.add("d-none"); bloqueMetricas.innerHTML = ""; }
                        if (bloqueVerif) { bloqueVerif.classList.add("d-none"); bloqueVerif.innerHTML = ""; }
                        if (bloqueComp) { bloqueComp.classList.add("d-none"); bloqueComp.innerHTML = ""; }
                    }
                }).finally(function() {
                    docModalFetchInFlight = false;
                });
            }

            function abrirModalDocumentacionCandidato(idCandidato, nombreCandidato) {
                disposeDocModalTooltips();
                var modal = document.getElementById("modalDocumentacionCandidato");
                var label = document.getElementById("modalDocumentacionCandidatoNombre");
                var bloqueVerif = document.getElementById("modalDocumentacionCandidatoVerificacion");
                var bloqueComp = document.getElementById("modalDocumentacionCandidatoComparaciones");
                var bloqueMetricas = document.getElementById("modalDocumentacionCandidatoMetricas");
                var bloqueAccionVerificar = document.getElementById("modalDocumentacionCandidatoAccionVerificar");
                var bloqueAccionesProceso = document.getElementById("modalDocumentacionCandidatoAccionesProceso");
                var lista = document.getElementById("modalDocumentacionCandidatoLista");
                var cargando = document.getElementById("modalDocumentacionCandidatoCargando");
                var vacio = document.getElementById("modalDocumentacionCandidatoVacio");
                if (modal) {
                    modal.dataset.nombreCandidato = (nombreCandidato != null && nombreCandidato !== undefined) ? String(nombreCandidato) : "";
                    modal.dataset.idCandidato = String(idCandidato);
                }
                if (label) label.textContent = nombreCandidato ? "Candidato: " + nombreCandidato : "";
                if (bloqueVerif) { bloqueVerif.classList.add("d-none"); bloqueVerif.innerHTML = ""; }
                if (bloqueComp) { bloqueComp.classList.add("d-none"); bloqueComp.innerHTML = ""; }
                if (bloqueMetricas) { bloqueMetricas.classList.add("d-none"); bloqueMetricas.innerHTML = ""; }
                if (bloqueAccionVerificar) bloqueAccionVerificar.classList.add("d-none");
                if (bloqueAccionesProceso) { bloqueAccionesProceso.classList.add("d-none"); bloqueAccionesProceso.innerHTML = ""; }
                if (lista) lista.innerHTML = "<div class=\"p-3 text-center text-muted\">Cargando documentos...</div>";
                if (vacio) vacio.classList.add("d-none");
                if (cargando) cargando.classList.remove("d-none");
                clearDocModalApiTrace();

                var bsModal = modal && window.bootstrap && window.bootstrap.Modal ? new window.bootstrap.Modal(modal) : null;
                if (bsModal) bsModal.show();
                cargarDocumentosModal(idCandidato);
            }

            function abrirModalReenviarPostulacion(idCandidato) {
        candidatoDatosEnvio = null;
        prepararBloqueLinkDocumentos();

        // Intentar obtener datos desde la memoria primero (eager loading)
        var candidato = null;
        if (window.candidatosData && Array.isArray(window.candidatosData)) {
            candidato = window.candidatosData.find(function(c) {
                return c.id === idCandidato || parseInt(c.id, 10) === idCandidato;
            });
        }

        if (candidato) {
            // Usar datos de memoria
            var nombreCompleto = [candidato.nombres, candidato.segundo_nombre, candidato.apellidop, candidato.apellidom].filter(Boolean).join(" ");
            var resumenEl = document.getElementById("resumenPostulacionTexto");
            if (resumenEl) {
                resumenEl.innerHTML = buildResumenCandidatoHTML({
                    nombreCompleto: nombreCompleto || "—",
                    telefono: (candidato.telefono ? "(" + candidato.telefono + ")" : "—"),
                    email: candidato.email || "—",
                    puesto: candidato.nombre_puesto || "—",
                    departamento: candidato.nombre_departamento || "—"
                });
            }
            var btnEnviar = document.getElementById("btnEnviarPostulacion");
            if (btnEnviar) {
                btnEnviar.disabled = false;
                btnEnviar.innerHTML = "<i class='bx bx-send me-2'></i> Reenviar postulación por correo";
            }
            candidatoReenviarId = candidato.id || idCandidato;
            candidatoReenviarEmail = candidato.email || "";
            var modalEl = document.getElementById("modalResumenPostulacion");
            if (modalEl) {
                modalEl.dataset.idCandidato = String(candidato.id || idCandidato);
                var modal = new bootstrap.Modal(modalEl);
                modal.show();
            }
            cargarLinkDocumentosCandidato(candidato.id || idCandidato);
        } else {
            // Fallback: obtener desde el servidor
            fetch("/caphum/getCandidato/" + idCandidato)
                .then(function(r) {
                    if (!r.ok) {
                        throw new Error("Error HTTP: " + r.status);
                    }
                    return r.json();
                })
                .then(function(res) {
                    if (!res || !res.success || !res.datos) {
                        if (typeof Swal !== "undefined") {
                            Swal.fire({ icon: "error", title: "Error", text: "No se encontró el candidato." });
                        }
                        return;
                    }
                    var c = res.datos;
                    var nombreCompleto = [c.nombres, c.segundo_nombre, c.apellidop, c.apellidom].filter(Boolean).join(" ");
                    var resumenEl = document.getElementById("resumenPostulacionTexto");
                    if (resumenEl) {
                        resumenEl.innerHTML = buildResumenCandidatoHTML({
                            nombreCompleto: nombreCompleto || "—",
                            telefono: (c.telefono ? "(" + c.telefono + ")" : "—"),
                            email: c.email || "—",
                            puesto: c.nombre_puesto || "—",
                            departamento: c.nombre_departamento || "—"
                        });
                    }
                    var btnEnviar = document.getElementById("btnEnviarPostulacion");
                    if (btnEnviar) {
                        btnEnviar.disabled = false;
                        btnEnviar.innerHTML = "<i class='bx bx-send me-2'></i> Reenviar postulación por correo";
                    }
                    candidatoReenviarId = c.id;
                    candidatoReenviarEmail = c.email || "";
                    var modalEl = document.getElementById("modalResumenPostulacion");
                    if (modalEl) {
                        modalEl.dataset.idCandidato = String(c.id);
                        var modal = new bootstrap.Modal(modalEl);
                        modal.show();
                    }
                    cargarLinkDocumentosCandidato(c.id);
                })
                .catch(function(err) {
                    console.error("Error al cargar candidato:", err);
                    if (typeof Swal !== "undefined") {
                        Swal.fire({
                            icon: "error",
                            title: "Error",
                            text: "No se pudo cargar el candidato. " + (err.message || "Error de conexión.")
                        });
                    }
                });
        }
        }

            function prepararBloqueLinkDocumentos() {
        var bloque = document.getElementById("bloqueLinkDocumentos");
        var input = document.getElementById("inputUrlDocumentos");
        var estado = document.getElementById("estadoUrlDocumentos");
        var btnReactivar = document.getElementById("btnReactivarUrlDocumentos");
        var btnCopiar = document.getElementById("btnCopiarUrlDocumentos");
        var btnAbrir = document.getElementById("btnAbrirUrlDocumentos");
        if (bloque) bloque.style.display = "block";
        if (input) {
            input.value = "";
            input.placeholder = "Generando enlace...";
            input.setAttribute("title", "");
        }
        if (estado) { estado.textContent = ""; estado.classList.remove("is-expired"); }
        if (btnReactivar) { btnReactivar.style.display = "none"; btnReactivar.disabled = false; }
        if (btnCopiar) btnCopiar.disabled = false;
        if (btnAbrir) btnAbrir.disabled = false;
        }

            function buildResumenCandidatoHTML(o) {
        var n = o.nombreCompleto || "—"; var t = o.telefono || "—"; var e = o.email || "—"; var p = o.puesto || "—"; var d = o.departamento || "—";
        return "<div class=\"resumen-row\"><span class=\"resumen-label\">Candidato</span><span class=\"resumen-value\">" + escapeHtml(n) + "</span></div>" +
            "<div class=\"resumen-row\"><span class=\"resumen-label\">Teléfono</span><span class=\"resumen-value\">" + escapeHtml(t) + "</span></div>" +
            "<div class=\"resumen-row\"><span class=\"resumen-label\">Correo</span><span class=\"resumen-value\">" + escapeHtml(e) + "</span></div>" +
            "<div class=\"resumen-row\"><span class=\"resumen-label\">Puesto</span><span class=\"resumen-value\">" + escapeHtml(p) + "</span></div>" +
            "<div class=\"resumen-row\"><span class=\"resumen-label\">Departamento</span><span class=\"resumen-value\">" + escapeHtml(d) + "</span></div>";
        }

            function escapeHtml(s) {
        if (!s) return ""; var div = document.createElement("div"); div.textContent = s; return div.innerHTML;
        }

            function actualizarEstadoLinkDocumentos(datos) {
        var input = document.getElementById("inputUrlDocumentos");
        var estado = document.getElementById("estadoUrlDocumentos");
        var btnReactivar = document.getElementById("btnReactivarUrlDocumentos");
        var btnCopiar = document.getElementById("btnCopiarUrlDocumentos");
        var btnAbrir = document.getElementById("btnAbrirUrlDocumentos");
        var url = datos && datos.url ? datos.url : "";
        var vencido = !!(datos && datos.vencido);
        var expiraTexto = datos && datos.expira_texto ? datos.expira_texto : "";
        if (input) {
            input.value = url;
            input.setAttribute("title", url);
            input.placeholder = url ? "" : "No se pudo obtener el enlace";
        }
        if (estado) {
            estado.classList.toggle("is-expired", vencido);
            if (expiraTexto) {
                estado.textContent = vencido ? ("Link expirado el " + expiraTexto) : ("Vigente hasta el " + expiraTexto);
            } else {
                estado.textContent = vencido ? "Link expirado" : "";
            }
        }
        if (btnReactivar) btnReactivar.style.display = vencido ? "flex" : "none";
        if (btnCopiar) btnCopiar.disabled = vencido || !url;
        if (btnAbrir) btnAbrir.disabled = vencido || !url;
        }

            function reactivarLinkDocumentosCandidato() {
        var id = candidatoReenviarId || candidatoNuevoId;
        if (!id) {
            var modal = document.getElementById("modalResumenPostulacion");
            id = modal && modal.dataset ? parseInt(modal.dataset.idCandidato || "0", 10) : 0;
        }
        if (!id) return;
        var btn = document.getElementById("btnReactivarUrlDocumentos");
        if (btn) { btn.disabled = true; btn.innerHTML = "<i class='bx bx-loader-alt bx-spin' aria-hidden='true'></i> Reactivando..."; }
        fetch("/caphum/reactivarTokenDocumentosCandidato", { method: "POST", headers: { "Content-Type": "application/json", "Accept": "application/json" }, body: JSON.stringify({ id: id }) })
            .then(function(r){ return r.json(); })
            .then(function(res){
                if (btn) { btn.disabled = false; btn.innerHTML = "<i class='bx bx-refresh' aria-hidden='true'></i> Reactivar link"; }
                if (res && res.success && res.datos && res.datos.url) {
                    actualizarEstadoLinkDocumentos(res.datos);
                    showToastUrl("Link reactivado correctamente");
                    return;
                }
                if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: (res && res.mensaje) ? res.mensaje : "No se pudo reactivar el link." });
            })
            .catch(function(){
                if (btn) { btn.disabled = false; btn.innerHTML = "<i class='bx bx-refresh' aria-hidden='true'></i> Reactivar link"; }
                if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: "No se pudo reactivar el link." });
            });
        }

            function cargarLinkDocumentosCandidato(idCandidato) {
        if (!idCandidato) return;
        var bloque = document.getElementById("bloqueLinkDocumentos");
        var input = document.getElementById("inputUrlDocumentos");
        if (!bloque || !input) return;
        bloque.style.display = "block";
        input.value = "";
        input.placeholder = "Generando enlace...";
        input.setAttribute("title", "");
        fetch("/caphum/getTokenDocumentosCandidato", { method: "POST", headers: { "Content-Type": "application/json", "Accept": "application/json" }, body: JSON.stringify({ id: idCandidato }) })
            .then(function(r){ return r.json(); })
            .then(function(res){
                if (res && res.success && res.datos && res.datos.url) {
                    actualizarEstadoLinkDocumentos(res.datos);
                    return;
                }
                input.placeholder = "No se pudo obtener el enlace";
                actualizarEstadoLinkDocumentos(null);
            })
            .catch(function(){
                input.placeholder = "No se pudo obtener el enlace";
                actualizarEstadoLinkDocumentos(null);
            });
        }

            function showToastUrl(msg) {
        var t = document.getElementById("toastUrlDocumentos");
        if (!t) return;
        t.textContent = msg; t.classList.add("show");
        setTimeout(function() { t.classList.remove("show"); }, 2200);
        }

            function initCopiarUrlDocumentos() {
        var btn = document.getElementById("btnCopiarUrlDocumentos");
        var input = document.getElementById("inputUrlDocumentos");
        if (!btn || !input) return;
        if (btn._copiarBound) return;
        btn._copiarBound = true;
        btn.addEventListener("click", function() {
            if (btn.disabled) return;
            var url = input.value;
            if (!url) { showToastUrl("Ingresa una URL primero"); return; }
            if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(url).then(function() { showToastUrl("URL copiada al portapapeles"); }).catch(function() { input.select(); input.setSelectionRange(0, 99999); try { document.execCommand("copy"); showToastUrl("URL copiada al portapapeles"); } catch (e) { if (typeof Swal !== "undefined") Swal.fire({ icon: "success", title: "Copiado", text: "URL copiada.", timer: 1500, showConfirmButton: false }); } });
            } else { input.select(); input.setSelectionRange(0, 99999); try { document.execCommand("copy"); showToastUrl("URL copiada al portapapeles"); } catch (e) { if (typeof Swal !== "undefined") Swal.fire({ icon: "success", title: "Copiado", text: "URL copiada.", timer: 1500, showConfirmButton: false }); } }
        });
        var btnAbrir = document.getElementById("btnAbrirUrlDocumentos");
        if (btnAbrir && !btnAbrir._abrirBound) {
            btnAbrir._abrirBound = true;
            btnAbrir.addEventListener("click", function() { if (btnAbrir.disabled) return; var url = input.value; if (!url) return; if (!/^https?:\/\//i.test(url)) url = "https://" + url; window.open(url, "_blank", "noopener,noreferrer"); });
        }
        var btnReactivar = document.getElementById("btnReactivarUrlDocumentos");
        if (btnReactivar && !btnReactivar._reactivarBound) {
            btnReactivar._reactivarBound = true;
            btnReactivar.addEventListener("click", reactivarLinkDocumentosCandidato);
        }
        }

            function editarCandidato(id) {
        candidatoEditId = id;
        var titulo = document.getElementById("offcanvasCandidatoTitulo");
        if (titulo) titulo.textContent = "Editar Candidato";
        var btnSubmit = document.getElementById("btnSubmitCandidato");
        if (btnSubmit) { btnSubmit.innerHTML = "<i class=\"bx bx-edit-alt me-1\"></i> Actualizar"; btnSubmit.className = "btn btn-success me-2"; }
        fetch("/caphum/getCandidato/" + id).then(function(r){ return r.json(); }).then(function(res){
            if (!res.success || !res.datos) { if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: "No se encontró el candidato." }); return; }
            var c = res.datos;
            var form = document.getElementById("formAgregarCandidato");
            if (!form) return;
            if (form.nombres) form.nombres.value = c.nombres || "";
            if (form.segundo_nombre) form.segundo_nombre.value = c.segundo_nombre || "";
            if (form.apellidop) form.apellidop.value = c.apellidop || "";
            if (form.apellidom) form.apellidom.value = c.apellidom || "";
            if (form.telefono) form.telefono.value = c.telefono || "";
            if (form.email) form.email.value = c.email || "";
            if (form.id_pais) form.id_pais.value = c.id_pais || "";
            var selPais = document.getElementById("candidato_id_pais");
            if (selPais) refreshSelectBuscadorCandidato(selPais.id);
            if (form.id_div_nivel1) form.id_div_nivel1.value = c.id_div_nivel1 || "";
            if (form.id_div_nivel2) form.id_div_nivel2.value = c.id_div_nivel2 || "";
            if (form.id_div_nivel3) form.id_div_nivel3.value = c.id_div_nivel3 || "";
            if (form.domicilio_calle_texto) form.domicilio_calle_texto.value = c.domicilio_calle_texto || "";
            if (form.domicilio_num_exterior) form.domicilio_num_exterior.value = c.domicilio_num_exterior || "";
            if (form.domicilio_num_interior) form.domicilio_num_interior.value = c.domicilio_num_interior || "";
            if (form.id_departamento) form.id_departamento.value = c.id_departamento || "";
            seleccionarOrganizacionPorDepartamentoCandidato(c.id_departamento || "");
            if (form.usuario) form.usuario.value = c.usuario || "";
            if (form.contrasena) form.contrasena.value = c.contrasena || "";
            var fpInput = document.getElementById("candidato_fecha_postulacion");
            if (fpInput && c.fecha_postulacion) fpInput.value = c.fecha_postulacion;
            var chkLegion = document.getElementById("candidato_asignar_legion");
            var divLegion = document.getElementById("div_candidato_legion");
            var selLegion = document.getElementById("candidato_id_legion");
            if (c.id_legion) { if (chkLegion) chkLegion.checked = true; if (divLegion) divLegion.style.display = "block"; if (selLegion) selLegion.value = c.id_legion; }
            else { if (chkLegion) chkLegion.checked = false; if (divLegion) divLegion.style.display = "none"; if (selLegion) selLegion.value = ""; }
            var selPuesto = document.getElementById("candidato_id_puesto");
            var selJefe = document.getElementById("candidato_id_posible_jefe");
            selPuesto.innerHTML = "<option value=''>Seleccione puesto</option>";
            selJefe.innerHTML = "<option value=''>—</option>";
            setTimeout(function() { abrirOffcanvasCandidato(); }, 0);
            precargarCascadaDomicilioCandidato(c);
            if (!c.id_departamento) { selJefe.innerHTML = "<option value=''>Seleccione departamento y puesto primero</option>"; return; }
            fetch("/caphum/getPuestos", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id_departamento: c.id_departamento }) })
            .then(function(r){ return r.json(); })
            .then(function(rPuestos){
                if (rPuestos.success && rPuestos.datos) rPuestos.datos.forEach(function(p){ var opt = document.createElement("option"); opt.value = p.id; opt.textContent = p.nombre || ""; selPuesto.appendChild(opt); });
                selPuesto.value = c.id_puesto || "";
                return fetch("/caphum/getJefeDirecto", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id_departamento: c.id_departamento, id_puesto: c.id_puesto || null }) });
            })
            .then(function(r){ return r.json(); })
            .then(function(rJefes){
                if (!selJefe) return;
                selJefe.innerHTML = "<option value=''>Seleccione posible jefe</option>";
                if (rJefes && rJefes.success && rJefes.datos) rJefes.datos.forEach(function(j){ var opt = document.createElement("option"); opt.value = j.id; opt.textContent = (j.nombre_completo || "").trim() || "ID " + j.id; selJefe.appendChild(opt); });
                selJefe.value = c.id_posible_jefe || "";
            })
            .catch(function(){ if (selJefe) selJefe.innerHTML = "<option value=''>Seleccione posible jefe</option>"; });
        }).catch(function(){ if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: "No se pudo cargar el candidato." }); });
        }

            function abrirOffcanvasCandidato() {
        var el = document.getElementById("offcanvasAddCandidato");
        if (!el) return;
        if (el.parentNode !== document.body) document.body.appendChild(el);
        if (typeof bootstrap !== "undefined" && bootstrap.Offcanvas) { var inst = bootstrap.Offcanvas.getOrCreateInstance(el); if (inst) inst.show(); }
        else { el.classList.add("show"); el.setAttribute("aria-hidden", "false"); var back = document.createElement("div"); back.className = "offcanvas-backdrop fade show"; back.style.cssText = "position:fixed;top:0;left:0;z-index:1040;width:100vw;height:100vh;background:#000;opacity:0.5;"; back.setAttribute("data-bs-dismiss", "offcanvas"); document.body.appendChild(back); }
        }

            function guardarCandidatoEdicion() {
        var form = document.getElementById("formAgregarCandidato");
        if (!form || !form.checkValidity()) { form.reportValidity(); return; }
        if (!validarDomicilioCandidato()) return;
        var id = candidatoEditId; if (!id) return;
        var data = buildCandidatoPayloadFromForm(); data.id = id;
        fetch("/caphum/actualizarCandidato", { method: "POST", headers: { "Content-Type": "application/json", "Accept": "application/json" }, body: JSON.stringify(data) })
        .then(function(r){ return r.json(); }).then(function(res){
            if (res.success) {
                if (typeof Swal !== "undefined") Swal.fire({ icon: "success", title: "Listo", text: "Candidato actualizado correctamente." });
                candidatoEditId = null;
                document.getElementById("offcanvasCandidatoTitulo").textContent = "Nuevo Candidato";
                var btnSubmit = document.getElementById("btnSubmitCandidato");
                if (btnSubmit) { btnSubmit.innerHTML = "<i class=\"bx bx-save me-1\"></i> Guardar"; btnSubmit.className = "btn btn-primary me-2"; }
                form.reset();
                var fpInput = document.getElementById("candidato_fecha_postulacion");
                if (fpInput && fpInput._flatpickr) fpInput._flatpickr.setDate(new Date(), true);
                var inst = bootstrap.Offcanvas.getInstance(document.getElementById("offcanvasAddCandidato"));
                if (inst) inst.hide();
                getCandidatos();
            } else { if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: res.mensaje || "No se pudo actualizar." }); }
        }).catch(function(){ if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: "Error de conexión." }); });
        }

            function guardarCandidatoAbrirResumen() {
        var form = document.getElementById("formAgregarCandidato");
        if (!form || !form.checkValidity()) { form.reportValidity(); return; }
        if (!validarDomicilioCandidato()) return;
        var data = buildCandidatoPayloadFromForm();
        if (!data.nombres || !data.apellidop) { if (typeof Swal !== "undefined") Swal.fire({ icon: "warning", title: "Faltan datos", text: "Nombre y apellido paterno son obligatorios." }); return; }
        var btnSubmit = document.getElementById("btnSubmitCandidato");
        if (btnSubmit) { btnSubmit.disabled = true; }
        fetch("/caphum/guardarCandidato", { method: "POST", headers: { "Content-Type": "application/json", "Accept": "application/json" }, body: JSON.stringify(data) })
        .then(function(r){ return r.json(); }).then(function(res){
            if (btnSubmit) { btnSubmit.disabled = false; btnSubmit.innerHTML = "<i class=\"bx bx-save me-1\"></i> Guardar"; }
            if (!res.success) { if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: res.mensaje || res.error || "No se pudo guardar." }); return; }
            var idCand = res.datos && res.datos.id; if (!idCand) return;
            candidatoNuevoId = idCand; candidatoNuevoEmail = data.email || ""; candidatoDatosEnvio = null; candidatoReenviarId = null; candidatoReenviarEmail = null;
            var nombreCompleto = [data.nombres, data.segundo_nombre, data.apellidop, data.apellidom].filter(Boolean).join(" ");
            var puestoTexto = (document.getElementById("candidato_id_puesto") && document.getElementById("candidato_id_puesto").selectedIndex >= 0) ? document.getElementById("candidato_id_puesto").options[document.getElementById("candidato_id_puesto").selectedIndex].text : "—";
            var deptoTexto = (document.getElementById("candidato_id_departamento") && document.getElementById("candidato_id_departamento").selectedIndex >= 0) ? document.getElementById("candidato_id_departamento").options[document.getElementById("candidato_id_departamento").selectedIndex].text : "—";
            document.getElementById("resumenPostulacionTexto").innerHTML = buildResumenCandidatoHTML({ nombreCompleto: nombreCompleto || "—", telefono: (data.telefono ? "(" + data.telefono + ")" : "—"), email: data.email || "—", puesto: puestoTexto, departamento: deptoTexto });
            document.getElementById("btnEnviarPostulacion").disabled = false;
            document.getElementById("btnEnviarPostulacion").innerHTML = "<i class='bx bx-send me-2'></i> Enviar postulación al candidato";
            prepararBloqueLinkDocumentos();
            var bloqueLink = document.getElementById("bloqueLinkDocumentos"); var inputUrl = document.getElementById("inputUrlDocumentos");
            if (bloqueLink) bloqueLink.style.display = "none"; if (inputUrl) inputUrl.value = "";
            cargarLinkDocumentosCandidato(idCand);
            var offcanvas = document.getElementById("offcanvasAddCandidato");
            if (offcanvas && typeof bootstrap !== "undefined") bootstrap.Offcanvas.getInstance(offcanvas).hide();
            var modalElResumen = document.getElementById("modalResumenPostulacion");
            if (modalElResumen) {
                modalElResumen.dataset.idCandidato = String(idCand);
                var modal = new bootstrap.Modal(modalElResumen); modal.show();
            }
            if (form) form.reset();
            var fpInput = document.getElementById("candidato_fecha_postulacion");
            if (fpInput && fpInput._flatpickr) fpInput._flatpickr.setDate(new Date(), true);
            getCandidatos();
        }).catch(function(){ if (typeof Swal !== "undefined") Swal.close(); if (btnSubmit) { btnSubmit.disabled = false; btnSubmit.innerHTML = "<i class=\"bx bx-save me-1\"></i> Guardar"; } if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: "Error de conexión." }); });
        }

            function buildCandidatoPayloadFromForm() {
        var form = document.getElementById("formAgregarCandidato"); if (!form) return {};
        return {
            nombres: (form.nombres && form.nombres.value.trim()) || "",
            segundo_nombre: (form.segundo_nombre && form.segundo_nombre.value.trim()) || "",
            apellidop: (form.apellidop && form.apellidop.value.trim()) || "",
            apellidom: (form.apellidom && form.apellidom.value.trim()) || "",
            email: (form.email && form.email.value.trim()) || "",
            telefono: (form.telefono && form.telefono.value.trim()) || "",
            id_pais: (form.id_pais && form.id_pais.value) || null,
            id_div_nivel1: (form.id_div_nivel1 && form.id_div_nivel1.value) || null,
            id_div_nivel2: (form.id_div_nivel2 && form.id_div_nivel2.value) || null,
            id_div_nivel3: (form.id_div_nivel3 && form.id_div_nivel3.value) || null,
            domicilio_calle_texto: (form.domicilio_calle_texto && form.domicilio_calle_texto.value.trim()) || null,
            domicilio_num_exterior: (form.domicilio_num_exterior && form.domicilio_num_exterior.value.trim()) || null,
            domicilio_num_interior: (form.domicilio_num_interior && form.domicilio_num_interior.value.trim()) || null,
            id_departamento: (form.id_departamento && form.id_departamento.value) || null,
            id_puesto: (form.id_puesto && form.id_puesto.value) || null,
            id_posible_jefe: (form.id_posible_jefe && form.id_posible_jefe.value) || null,
            fecha_postulacion: (form.fecha_postulacion && form.fecha_postulacion.value) || null,
            id_legion: document.getElementById("candidato_asignar_legion") && document.getElementById("candidato_asignar_legion").checked && document.getElementById("candidato_id_legion") && document.getElementById("candidato_id_legion").value ? document.getElementById("candidato_id_legion").value : null,
            usuario: (form.usuario && form.usuario.value.trim()) || "",
            contrasena: (form.contrasena && form.contrasena.value.trim()) || "",
            estatus: "Por evaluar", notas: null, postulacion_enviada: 1
        };
        }

            function validarDomicilioCandidato() {
        return true;
        var paisSel = document.getElementById("candidato_id_pais");
        var paisTxt = paisSel && paisSel.selectedIndex >= 0 ? String(paisSel.options[paisSel.selectedIndex].textContent || "").toLowerCase() : "";
        var esMexico = paisTxt.indexOf("mex") >= 0;
        if (!esMexico) return true;
        var estado = document.getElementById("candidato_id_div_nivel1");
        var municipio = document.getElementById("candidato_id_div_nivel2");
        var colonia = document.getElementById("candidato_id_div_nivel3");
        var calle = document.getElementById("candidato_domicilio_calle_texto");
        var ext = document.getElementById("candidato_domicilio_num_exterior");
        if (!estado || !estado.value) { if (typeof Swal !== "undefined") Swal.fire({ icon: "warning", title: "Domicilio", text: "Selecciona el estado." }); return false; }
        if (!municipio || !municipio.value) { if (typeof Swal !== "undefined") Swal.fire({ icon: "warning", title: "Domicilio", text: "Selecciona la alcaldía/municipio." }); return false; }
        if (!colonia || !colonia.value) { if (typeof Swal !== "undefined") Swal.fire({ icon: "warning", title: "Domicilio", text: "Selecciona la colonia." }); return false; }
        if (!calle || !String(calle.value || "").trim()) { if (typeof Swal !== "undefined") Swal.fire({ icon: "warning", title: "Domicilio", text: "Escribe la calle." }); return false; }
        if (!ext || !String(ext.value || "").trim()) { if (typeof Swal !== "undefined") Swal.fire({ icon: "warning", title: "Domicilio", text: "Captura el número exterior." }); return false; }
        return true;
        }

            function enviarPostulacionAlCandidato() {
        var btn = document.getElementById("btnEnviarPostulacion");
        if (btn.disabled) return;
        btn.disabled = true; btn.innerHTML = "<i class='bx bx-loader-alt bx-spin me-2'></i> Enviando...";
        if (candidatoReenviarId) {
            var urlReenviar = "/caphum/enviarPostulacionCandidato";
            fetch(urlReenviar, { method: "POST", headers: { "Content-Type": "application/json", "Accept": "application/json" }, body: JSON.stringify({ id: candidatoReenviarId, email: candidatoReenviarEmail || "" }) })
            .then(function(r){ return r.text().then(function(text) { var res; try { res = text ? JSON.parse(text) : {}; } catch (e) { res = null; } return { ok: r.ok, status: r.status, res: res, raw: text }; }); })
            .then(function(o){
                var res = o.res; candidatoReenviarId = null; candidatoReenviarEmail = null; btn.disabled = false;
                btn.innerHTML = "<i class='bx bx-send me-2'></i> Reenviar postulación por correo";
                if (!res && !o.ok) { if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: "El servidor respondió con " + o.status + ". Verifique la URL o intente más tarde." }); return; }
                if (res && res.success) { if (res.datos) actualizarEstadoLinkDocumentos(res.datos); if (typeof Swal !== "undefined") Swal.fire({ icon: "success", title: "Listo", text: "Correo de postulación reenviado correctamente." }); getCandidatos(); setTimeout(function() { bootstrap.Modal.getInstance(document.getElementById("modalResumenPostulacion")).hide(); }, 1500); }
                else { if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: (res && res.mensaje) ? res.mensaje : "No se pudo enviar el correo." }); }
            }).catch(function(err){ btn.disabled = false; btn.innerHTML = "<i class='bx bx-send me-2'></i> Reenviar postulación por correo"; if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: (err && err.message) ? err.message : "Error de conexión." }); });
            return;
        }
        if (candidatoNuevoId) {
            var idCand = candidatoNuevoId; var email = candidatoNuevoEmail || "";
            fetch("/caphum/enviarPostulacionCandidato", { method: "POST", headers: { "Content-Type": "application/json", "Accept": "application/json" }, body: JSON.stringify({ id: idCand, email: email }) })
            .then(function(r){ return r.json(); }).then(function(resMail){
                candidatoNuevoId = null; candidatoNuevoEmail = null; btn.disabled = false;
                if (resMail && resMail.success) { if (resMail.datos) actualizarEstadoLinkDocumentos(resMail.datos); btn.innerHTML = "<i class=\"bx bx-check me-2\"></i> Enviada postulación"; if (typeof Swal !== "undefined") Swal.fire({ icon: "success", title: "Listo", text: "Correo enviado. El enlace para subir documentos está en el correo y arriba." }); }
                else { btn.innerHTML = "<i class='bx bx-send me-2'></i> Enviar postulación al candidato"; if (typeof Swal !== "undefined") Swal.fire({ icon: "warning", title: "Correo no enviado", text: (resMail && resMail.mensaje) ? resMail.mensaje : "Configure [mail] en backend/config/config.ini para SMTP. Use el enlace de arriba para compartir con el candidato." }); }
                getCandidatos(); setTimeout(function() { bootstrap.Modal.getInstance(document.getElementById("modalResumenPostulacion")).hide(); }, 2500);
            }).catch(function(){ btn.disabled = false; btn.innerHTML = "<i class='bx bx-send me-2'></i> Enviar postulación al candidato"; if (typeof Swal !== "undefined") Swal.fire({ icon: "warning", title: "Error", text: "El correo no se pudo enviar. Use el enlace de arriba para compartir con el candidato." }); });
            return;
        }
        var data = candidatoDatosEnvio || buildCandidatoPayloadFromForm();
        if (!data.nombres || !data.apellidop) { btn.disabled = false; btn.innerHTML = "<i class='bx bx-send me-2'></i> Enviar postulación al candidato"; if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: "Nombre y apellido paterno son obligatorios." }); return; }
        var form = document.getElementById("formAgregarCandidato");
        fetch("/caphum/guardarCandidato", { method: "POST", headers: { "Content-Type": "application/json", "Accept": "application/json" }, body: JSON.stringify(data) })
        .then(function(r){ return r.json(); }).then(function(res){
            if (res.success) {
                candidatoDatosEnvio = null; var idCand = res.datos && res.datos.id; cargarLinkDocumentosCandidato(idCand);
                fetch("/caphum/enviarPostulacionCandidato", { method: "POST", headers: { "Content-Type": "application/json", "Accept": "application/json" }, body: JSON.stringify({ id: idCand, email: data.email }) })
                .then(function(r2){ return r2.json(); }).then(function(resMail){
                    btn.disabled = false; btn.innerHTML = "<i class=\"bx bx-send me-2\"></i> Enviar postulación al candidato";
                    if (resMail && resMail.success) { if (resMail.datos) actualizarEstadoLinkDocumentos(resMail.datos); btn.innerHTML = "<i class=\"bx bx-check me-2\"></i> Enviada postulación"; if (typeof Swal !== "undefined") Swal.fire({ icon: "success", title: "Listo", text: "Candidato registrado y correo enviado. El enlace para subir documentos está en el correo y arriba." }); }
                    else { if (typeof Swal !== "undefined") Swal.fire({ icon: "warning", title: "Candidato guardado", text: (resMail && resMail.mensaje) ? "El correo no se envió: " + resMail.mensaje + ". Configure [mail] en backend/config/config.ini para SMTP o revise que mail() funcione." : "El correo no se pudo enviar. Use el enlace de arriba para compartir con el candidato." }); }
                    getCandidatos(); setTimeout(function() { bootstrap.Modal.getInstance(document.getElementById("modalResumenPostulacion")).hide(); }, 2500);
                }).catch(function(){ btn.disabled = false; btn.innerHTML = "<i class=\"bx bx-send me-2\"></i> Enviar postulación al candidato"; if (typeof Swal !== "undefined") Swal.fire({ icon: "warning", title: "Candidato guardado", text: "El correo no se pudo enviar (error de conexión). Use el enlace de arriba para compartir con el candidato." }); getCandidatos(); });
                if (form) form.reset(); var fpInput = document.getElementById("candidato_fecha_postulacion"); if (fpInput && fpInput._flatpickr) fpInput._flatpickr.setDate(new Date(), true);
            } else { btn.disabled = false; btn.innerHTML = "<i class='bx bx-send me-2'></i> Enviar postulación al candidato"; if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: res.mensaje || res.error || "No se pudo guardar." }); }
        }).catch(function(){ btn.disabled = false; btn.innerHTML = "<i class='bx bx-send me-2'></i> Enviar postulación al candidato"; if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: "Error de conexión." }); });
        }

            function eliminarCandidato(id) {
        if (typeof Swal === "undefined") { if (confirm("¿Eliminar candidato?")) fetch("/caphum/eliminarCandidato", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id: id }) }).then(function(r){ return r.json(); }).then(function(d){ if (d.success) getCandidatos(); }); return; }
        Swal.fire({ title: "¿Eliminar?", text: "Se eliminará el candidato.", icon: "warning", showCancelButton: true }).then(function(r){ if (r.isConfirmed) fetch("/caphum/eliminarCandidato", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id: id }) }).then(function(res){ return res.json(); }).then(function(d){ if (d.success) { Swal.fire({ icon: "success", text: d.mensaje }); getCandidatos(); } else Swal.fire({ icon: "error", text: d.mensaje || d.error }); }); });
        }


        $(document).ready(function() {
        configuraTabla("#tablaCandidatos", {
            registrosPorPagina: 10,
            columns: [
                { data: null, defaultContent: '', className: 'control', orderable: false },
                { data: 'nombreContacto', title: 'Nombre / Contacto' },
                { data: 'puestoDepto', title: 'Puesto / Departamento' },
                { data: 'ubicacion', title: 'Ubicación' },
                { data: 'estatus', title: 'Estatus', render: function(d) { return d != null ? d : ''; } },
                { data: 'acciones', title: 'Acciones', orderable: false }
            ]
        });
        getCandidatos();
        var selDepto = document.getElementById("UserRole");
        var selPuesto = document.getElementById("UserPlan");
        var selEstatus = document.getElementById("FilterTransaction");
        if (selDepto) selDepto.addEventListener("change", function() { getCandidatos(); });
        if (selPuesto) selPuesto.addEventListener("change", function() { getCandidatos(); });
        if (selEstatus) selEstatus.addEventListener("change", function() { getCandidatos(); });
        var form = document.getElementById("formAgregarCandidato");
        if (form) { form.addEventListener("submit", function(e) { e.preventDefault(); if (candidatoEditId) guardarCandidatoEdicion(); else guardarCandidatoAbrirResumen(); }); }
        document.addEventListener("click", candidatosTableClick);
        var modalDocPollEl = document.getElementById("modalDocumentacionCandidato");
        if (modalDocPollEl) modalDocPollEl.addEventListener("hidden.bs.modal", function() { clearDocModalPoll(); disposeDocModalTooltips(); });
        ["modalResumenPostulacion", "modalDocumentacionCandidato"].forEach(function(mid) {
            var m = document.getElementById(mid);
            if (!m) return;
            m.addEventListener("hide.bs.modal", function() {
                var ae = document.activeElement;
                if (ae && m.contains(ae) && typeof ae.blur === "function") ae.blur();
            });
        });
        document.addEventListener("click", function(e) {
            var btnReintentarVerif = e.target.closest(".btn-reintentar-verif-expediente, [data-reintentar-api='1'], #btnReintentarVerifExpediente");
            if (btnReintentarVerif) {
                e.preventDefault();
                e.stopPropagation();
                reintentarVerificacionExpedienteApi(btnReintentarVerif);
                return;
            }
            var btn = e.target.closest(".btn-cerrar-proceso-candidato");
            if (btn) {
                e.preventDefault();
                e.stopPropagation();
                var id = btn.getAttribute("data-id");
                if (!id) return;
                var idNum = parseInt(id, 10);
                if (typeof Swal !== "undefined") {
                    Swal.fire({
                        title: "¿Estás seguro?",
                        text: "Podrás indicar el motivo del cierre en el siguiente paso.",
                        icon: "warning",
                        showCancelButton: true,
                        confirmButtonText: "Sí, continuar",
                        cancelButtonText: "Cancelar"
                    }).then(function(r) {
                        if (r.isConfirmed) abrirModalCerrarProceso(idNum);
                    });
                } else if (confirm("¿Estás seguro de cerrar el proceso de este candidato?")) {
                    abrirModalCerrarProceso(idNum);
                }
                return;
            }
            btn = e.target.closest(".btn-enviar-validacion-final-candidato");
            if (btn) {
                e.preventDefault();
                e.stopPropagation();
                var idValFinal = btn.getAttribute("data-id");
                if (idValFinal) enviarCandidatoAValidacionFinal(parseInt(idValFinal, 10), btn);
                return;
            }
            btn = e.target.closest(".btn-continuar-proceso-candidato");
            if (btn) {
                e.preventDefault();
                e.stopPropagation();
                var idC = btn.getAttribute("data-id");
                if (idC) abrirModalFechaIngresoCandidato(parseInt(idC, 10));
                return;
            }
            btn = e.target.closest(".btn-confirmar-firma-candidato");
            if (btn) {
                e.preventDefault();
                e.stopPropagation();
                var idFirma = btn.getAttribute("data-id");
                if (idFirma) confirmarFirmaContratoCandidato(parseInt(idFirma, 10));
            }
        });
        function enviarCandidatoAValidacionFinal(idCandidato, btn) {
            if (!idCandidato || idCandidato <= 0) return;
            var prevHtml = btn ? btn.innerHTML : "";
            var ejecutar = function() {
                if (btn) { btn.disabled = true; btn.innerHTML = "<i class=\"fa fa-spinner fa-spin me-1\"></i>Enviando"; }
                fetch("/caphum/enviarCandidatoValidacionFinal", {
                    method: "POST",
                    headers: { "Content-Type": "application/json", "Accept": "application/json" },
                    body: JSON.stringify({ id_candidato: idCandidato })
                }).then(function(r){ return r.json(); }).then(function(res) {
                    if (btn) { btn.disabled = false; btn.innerHTML = prevHtml; }
                    if (!res.success) {
                        if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: res.mensaje || "No se pudo enviar a validacion final." });
                        return;
                    }
                    var candidato = obtenerCandidatoLocalPorId(idCandidato);
                    if (candidato) candidato.estatus = "Pendiente de validacion final";
                    cargarDocumentosModal(idCandidato);
                    if (typeof getCandidatos === "function") getCandidatos();
                    if (typeof Swal !== "undefined") Swal.fire({ icon: "success", title: "Enviado", text: res.mensaje || "Expediente enviado a validacion final.", timer: 2200, showConfirmButton: false });
                }).catch(function() {
                    if (btn) { btn.disabled = false; btn.innerHTML = prevHtml; }
                    if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: "Error de conexion." });
                });
            };
            if (typeof Swal === "undefined") {
                if (confirm("Enviar este expediente a validacion final?")) ejecutar();
                return;
            }
            Swal.fire({
                title: "Enviar a validacion final",
                text: "El responsable final podra aprobar el ingreso o rechazar documentos.",
                icon: "question",
                showCancelButton: true,
                confirmButtonText: "Enviar",
                cancelButtonText: "Cancelar"
            }).then(function(r) { if (r.isConfirmed) ejecutar(); });
        }
        function initFlatpickrFechaIngresoCandidato() {
            var input = document.getElementById("fechaIngresoCandidato");
            if (!input || typeof flatpickr === "undefined") return;
            if (input._flatpickr) return;
            flatpickr(input, {
                dateFormat: "Y-m-d",
                minDate: "today",
                allowInput: false,
                clickOpens: true,
                static: true,
                locale: (typeof flatpickr !== "undefined" && flatpickr.l10ns && flatpickr.l10ns.es) ? flatpickr.l10ns.es : undefined
            });
        }
        function abrirModalFechaIngresoCandidato(idCandidato) {
            var hid = document.getElementById("fechaIngresoIdCandidato");
            var input = document.getElementById("fechaIngresoCandidato");
            if (hid) hid.value = idCandidato || "";
            if (input) {
                input.value = "";
                if (input._flatpickr) input._flatpickr.clear();
            }
            var modalEl = document.getElementById("modalFechaIngresoCandidato");
            if (modalEl && window.bootstrap && window.bootstrap.Modal) {
                initFlatpickrFechaIngresoCandidato();
                new window.bootstrap.Modal(modalEl).show();
            } else {
                ejecutarContinuarProceso(idCandidato, "");
            }
        }
        function abrirModalCerrarProceso(idCandidato) {
            var hid = document.getElementById("cerrarProcesoIdCandidato");
            var sel = document.getElementById("cerrarProcesoMotivo");
            var ta = document.getElementById("cerrarProcesoDescripcion");
            if (hid) hid.value = idCandidato || "";
            if (sel) sel.value = "";
            if (ta) ta.value = "";
            var modalEl = document.getElementById("modalCerrarProcesoCandidato");
            if (modalEl && window.bootstrap && window.bootstrap.Modal) {
                var isDark = document.body.classList.contains("dark-mode");
                var opts = isDark ? { backdrop: false } : {};
                var m = new window.bootstrap.Modal(modalEl, opts);
                m.show();
            }
        }
        (function() {
            var modalCerrar = document.getElementById("modalCerrarProcesoCandidato");
            if (!modalCerrar) return;
            modalCerrar.addEventListener("shown.bs.modal", function() {
                if (document.body.classList.contains("dark-mode")) return;
                var backdrops = document.querySelectorAll(".modal-backdrop");
                var zScrim = "1094";
                for (var i = 0; i < backdrops.length; i++) {
                    if (i === backdrops.length - 1) {
                        backdrops[i].style.setProperty("z-index", zScrim, "important");
                    } else {
                        backdrops[i].style.setProperty("z-index", "1089", "important");
                    }
                }
                modalCerrar.style.setProperty("z-index", "10050", "important");
            });
        })();
        var btnConfirmarCerrar = document.getElementById("btnConfirmarCerrarProceso");
        if (btnConfirmarCerrar) {
            btnConfirmarCerrar.addEventListener("click", function() {
                var idInput = document.getElementById("cerrarProcesoIdCandidato");
                var idCandidato = idInput ? parseInt(idInput.value, 10) : 0;
                var motivoSelect = document.getElementById("cerrarProcesoMotivo");
                var motivo = motivoSelect ? (motivoSelect.value || "").trim() : "";
                var descInput = document.getElementById("cerrarProcesoDescripcion");
                var descripcion = descInput ? (descInput.value || "").trim() : null;
                if (idCandidato <= 0) { if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: "ID de candidato no válido." }); return; }
                if (!motivo) { if (typeof Swal !== "undefined") Swal.fire({ icon: "warning", title: "Requerido", text: "Selecciona un motivo para el cierre." }); return; }
                btnConfirmarCerrar.disabled = true;
                fetch("/caphum/cerrarProcesoCandidato", { method: "POST", headers: { "Content-Type": "application/json", "Accept": "application/json" }, body: JSON.stringify({ id_candidato: idCandidato, motivo: motivo, descripcion: descripcion || null }) })
                    .then(function(r){ return r.json(); })
                    .then(function(res) {
                        btnConfirmarCerrar.disabled = false;
                        if (res.success) {
                            var modalCerrar = document.getElementById("modalCerrarProcesoCandidato");
                            var modalDoc = document.getElementById("modalDocumentacionCandidato");
                            if (modalCerrar && window.bootstrap && window.bootstrap.Modal) { var inst = window.bootstrap.Modal.getInstance(modalCerrar); if (inst) inst.hide(); }
                            if (modalDoc && window.bootstrap && window.bootstrap.Modal) { var instDoc = window.bootstrap.Modal.getInstance(modalDoc); if (instDoc) instDoc.hide(); }
                            if (typeof getCandidatos === "function") getCandidatos();
                            if (typeof Swal !== "undefined") Swal.fire({ icon: "success", title: "Listo", text: res.mensaje || "Proceso cerrado correctamente." });
                        } else {
                            if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: res.mensaje || "No se pudo cerrar el proceso." });
                        }
                    })
                    .catch(function() { btnConfirmarCerrar.disabled = false; if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: "Error de conexión." }); });
            });
        }
        function finalizarCandidatoFirmado(idCandidato) {
            function cerrarModalYRefrescar() {
                var modalDoc = document.getElementById("modalDocumentacionCandidato");
                if (modalDoc && window.bootstrap && window.bootstrap.Modal) {
                    var instDoc = window.bootstrap.Modal.getInstance(modalDoc);
                    if (instDoc) instDoc.hide();
                }
                if (typeof getCandidatos === "function") getCandidatos();
            }
            if (typeof Swal === "undefined") {
                fetch("/caphum/pasarCandidatoAGestion", { method: "POST", headers: { "Content-Type": "application/json", "Accept": "application/json" }, body: JSON.stringify({ id_candidato: idCandidato }) })
                    .then(function(r){ return r.json(); })
                    .then(function(res) {
                        if (res.success) {
                            cerrarModalYRefrescar();
                            alert("Listo. El colaborador pasó a Gestión y se envió el correo de bienvenida.");
                        } else {
                            alert(res.mensaje || "No se pudo pasar a Gestión.");
                        }
                    })
                    .catch(function() { alert("Error de conexión."); });
                return;
            }
            Swal.fire({
                title: "Procesando...",
                text: "Pasando a Gestión y enviando correo de bienvenida.",
                allowOutsideClick: false,
                allowEscapeKey: false,
                didOpen: function() { Swal.showLoading(); }
            });
            fetch("/caphum/pasarCandidatoAGestion", { method: "POST", headers: { "Content-Type": "application/json", "Accept": "application/json" }, body: JSON.stringify({ id_candidato: idCandidato }) })
                .then(function(r){ return r.json(); })
                .then(function(res) {
                    Swal.close();
                    if (res.success) {
                        cerrarModalYRefrescar();
                        Swal.fire({ icon: "success", title: "Listo", text: res.mensaje || "El colaborador pasó a Gestión y se envió el correo de bienvenida." });
                    } else {
                        Swal.fire({ icon: "error", title: "Error", text: res.mensaje || "No se pudo pasar a Gestión." });
                    }
                })
                .catch(function() {
                    Swal.close();
                    Swal.fire({ icon: "error", title: "Error", text: "Error de conexión." });
                });
        }

        function confirmarFirmaContratoCandidato(idCandidato) {
            if (!idCandidato || idCandidato <= 0) return;
            if (typeof Swal === "undefined") {
                if (confirm("¿El usuario ya firmó el contrato?")) {
                    finalizarCandidatoFirmado(idCandidato);
                } else {
                    alert("No se puede mandar el usuario a la plantilla hasta que firme su contrato.");
                }
                return;
            }
            Swal.fire({
                title: "¿Ya firmó contrato?",
                text: "Solo se pasará a Gestión cuando el contrato esté firmado.",
                icon: "question",
                showCancelButton: true,
                confirmButtonText: "Sí, firmó",
                cancelButtonText: "No",
                confirmButtonColor: "#198754",
                cancelButtonColor: "#6c757d"
            }).then(function(result) {
                if (result.isConfirmed) {
                    finalizarCandidatoFirmado(idCandidato);
                    return;
                }
                Swal.fire({
                    icon: "info",
                    title: "Firma pendiente",
                    text: "No se puede mandar el usuario a la plantilla hasta que firme su contrato."
                });
            });
        }

        function marcarIngresoProgramadoLocal(idCandidato, fechaIngreso, datos) {
            var candidato = obtenerCandidatoLocalPorId(idCandidato);
            if (candidato) {
                candidato.estatus = "Ingreso programado";
                candidato.fecha_ingreso_programada = fechaIngreso || (datos && datos.fecha_ingreso) || candidato.fecha_ingreso_programada || "";
                candidato.fecha_ingreso_notificada_en = (datos && datos.fecha_ingreso_notificada_en) || candidato.fecha_ingreso_notificada_en || "";
            }
            if (typeof cargarDocumentosModal === "function") {
                cargarDocumentosModal(idCandidato);
            }
            if (typeof getCandidatos === "function") {
                getCandidatos();
            }
        }

        function ejecutarContinuarProceso(idCandidato, fechaIngreso) {
            if (!fechaIngreso) {
                if (typeof Swal !== "undefined") Swal.fire({ icon: "warning", title: "Fecha requerida", text: "Selecciona la fecha de ingreso del candidato." });
                else alert("Selecciona la fecha de ingreso del candidato.");
                return;
            }
            if (typeof Swal === "undefined") {
                fetch("/caphum/continuarProcesoCandidato", { method: "POST", headers: { "Content-Type": "application/json", "Accept": "application/json" }, body: JSON.stringify({ id_candidato: idCandidato, fecha_ingreso: fechaIngreso }) })
                    .then(function(r){ return r.json(); })
                    .then(function(res) {
                        if (!res.success) return alert(res.mensaje || "No se pudo continuar el proceso.");
                        marcarIngresoProgramadoLocal(idCandidato, fechaIngreso, res.datos || null);
                        alert(res.mensaje || "Notificaciones enviadas. Ahora confirma la firma del contrato.");
                    })
                    .catch(function() { alert("Error de conexión."); });
                return;
            }
            Swal.fire({
                title: "Enviando notificaciones...",
                text: "Se notificará al candidato y al jefe del área.",
                allowOutsideClick: false,
                allowEscapeKey: false,
                didOpen: function() { Swal.showLoading(); }
            });
            fetch("/caphum/continuarProcesoCandidato", { method: "POST", headers: { "Content-Type": "application/json", "Accept": "application/json" }, body: JSON.stringify({ id_candidato: idCandidato, fecha_ingreso: fechaIngreso }) })
                .then(function(r){ return r.json(); })
                .then(function(res) {
                    Swal.close();
                    if (!res.success) {
                        Swal.fire({ icon: "error", title: "Error", text: res.mensaje || "No se pudo continuar el proceso." });
                        return;
                    }
                    var detalle = res.mensaje || "Se notificó al candidato correctamente.";
                    if (res.datos && res.datos.correo_jefe_intentado && !res.datos.correo_jefe_enviado) {
                        detalle += " Revisa el correo del jefe; no se pudo enviar esa notificación.";
                    }
                    marcarIngresoProgramadoLocal(idCandidato, fechaIngreso, res.datos || null);
                    Swal.fire({ icon: "success", title: "Notificaciones enviadas", text: detalle + " Ahora confirma la firma del contrato para pasarlo a Gestión.", timer: 2200, showConfirmButton: false });
                })
                .catch(function() {
                    Swal.close();
                    Swal.fire({ icon: "error", title: "Error", text: "Error de conexión." });
                });
        }
        var btnConfirmarFechaIngreso = document.getElementById("btnConfirmarFechaIngresoCandidato");
        if (btnConfirmarFechaIngreso) {
            btnConfirmarFechaIngreso.addEventListener("click", function() {
                var hid = document.getElementById("fechaIngresoIdCandidato");
                var input = document.getElementById("fechaIngresoCandidato");
                var idCandidato = hid ? parseInt(hid.value, 10) : 0;
                var fechaIngreso = input ? (input.value || "").trim() : "";
                if (idCandidato <= 0) {
                    if (typeof Swal !== "undefined") Swal.fire({ icon: "error", title: "Error", text: "ID de candidato no válido." });
                    return;
                }
                if (!fechaIngreso) {
                    if (typeof Swal !== "undefined") Swal.fire({ icon: "warning", title: "Fecha requerida", text: "Selecciona la fecha de ingreso del candidato." });
                    return;
                }
                var modalFecha = document.getElementById("modalFechaIngresoCandidato");
                if (modalFecha && window.bootstrap && window.bootstrap.Modal) {
                    var instFecha = window.bootstrap.Modal.getInstance(modalFecha);
                    if (instFecha) instFecha.hide();
                }
                ejecutarContinuarProceso(idCandidato, fechaIngreso);
            });
        }
        var offcanvasEl = document.getElementById("offcanvasAddCandidato");
        if (offcanvasEl) {
            offcanvasEl.addEventListener("show.bs.offcanvas", function() { var btnSubmit = document.getElementById("btnSubmitCandidato"); if (!btnSubmit) return; if (candidatoEditId) { btnSubmit.innerHTML = "<i class=\"bx bx-edit-alt me-1\"></i> Actualizar"; btnSubmit.className = "btn btn-success me-2"; } else { btnSubmit.innerHTML = "<i class=\"bx bx-save me-1\"></i> Guardar"; btnSubmit.className = "btn btn-primary me-2"; } });
            offcanvasEl.addEventListener("shown.bs.offcanvas", function() {
                [
                    "candidato_id_pais",
                    "candidato_id_div_nivel1",
                    "candidato_id_div_nivel2",
                    "candidato_id_div_nivel3",
                    "candidato_id_direccion",
                    "candidato_id_area",
                    "candidato_id_departamento",
                    "candidato_id_puesto",
                    "candidato_id_posible_jefe",
                    "candidato_id_legion"
                ].forEach(function(id) { refreshSelectBuscadorCandidato(id); });
                var pais = document.getElementById("candidato_id_pais");
                var depto = document.getElementById("candidato_id_departamento");
                var puesto = document.getElementById("candidato_id_puesto");
                if (pais && pais.value && !document.getElementById("candidato_id_div_nivel1").value) {
                    if (typeof window.jQuery !== "undefined") window.jQuery(pais).trigger("change");
                    else pais.dispatchEvent(new Event("change", { bubbles: true }));
