            'apellidop'       => trim($c['apellidop'] ?? ''),
            'apellidom'       => trim($c['apellidom'] ?? ''),
            'email'           => trim($c['email'] ?? ''),
            'telefono'        => trim($c['telefono'] ?? ''),
            'puesto'          => trim($c['nombre_puesto'] ?? ''),
            'departamento'    => trim($c['nombre_departamento'] ?? ''),
            'fecha'           => date('d/m/Y'),
            'curp'            => trim($c['curp'] ?? ''),
        ];
    }

    private function docVerifNormalizarNombre($nombre): string
    {
        $s = strtoupper(trim((string) $nombre));
        if (function_exists('iconv')) {
            $tmp = @iconv('UTF-8', 'ASCII//TRANSLIT//IGNORE', $s);
            if ($tmp !== false) $s = $tmp;
        }
        $s = preg_replace('/[^A-Z\s]/', ' ', $s);
        return trim(preg_replace('/\s+/', ' ', $s));
    }

    private function docVerifNombresCoinciden($a, $b): bool
    {
        $pa = array_filter(explode(' ', $this->docVerifNormalizarNombre($a)), function ($p) { return strlen($p) > 2; });
        $pb = array_filter(explode(' ', $this->docVerifNormalizarNombre($b)), function ($p) { return strlen($p) > 2; });
        return count($pa) >= 2 && count($pb) >= 2 && count(array_intersect($pa, $pb)) >= 2;
    }

    private function docVerifCurpComparable($curp): string
    {
        return strtoupper(preg_replace('/[^A-Z0-9]/', '', (string) $curp));
    }

    private function docVerifBoolComp(array &$comparaciones, string $key, string $aLabel, $a, string $bLabel, $b, bool $coincide): void
    {
        $comparaciones[$key] = [$aLabel => $a, $bLabel => $b, 'coincide' => $coincide];
    }

    private function expedientePayloadDesdeCacheDocumentos(array $documentos, string $nombreCandidatoRegistro, bool $soloIdentificacion = false): ?array
    {
        $idCurp = $idNombre = $idScoreFrente = $idScoreReverso = null;
        $curpDoc = $curpNombre = $curpReciente = $curpMeses = $curpFecha = null;
        $nssCurp = $nssNombre = null;
        $fiscalCurp = $fiscalNombre = null;
        $actaNombre = null;
        $alertas = [];

        foreach ($documentos as $d) {
            $tipo = strtoupper(trim((string) ($d['tipo_documento'] ?? '')));
            $cal = $d['verificacion_calidad'] ?? null;
            if (!$cal && !empty($d['verificacion_calidad_json'])) {
                $dec = json_decode($d['verificacion_calidad_json'], true);
                $cal = is_array($dec) ? $dec : null;
            }
            $fis = $d['verificacion_fiscal'] ?? null;
            if (!$fis && !empty($d['verificacion_fiscal_json'])) {
                $dec = json_decode($d['verificacion_fiscal_json'], true);
                $fis = is_array($dec) ? $dec : null;
            }

            if (in_array($tipo, ['IDENTIFICACIÓN OFICIAL', 'IDENTIFICACION OFICIAL', 'IDENTIFICACIÃ“N OFICIAL'], true)) {
                $fr = is_array($cal['detalle_frente'] ?? null) ? $cal['detalle_frente'] : [];
                $rv = is_array($cal['detalle_reverso'] ?? null) ? $cal['detalle_reverso'] : [];
                $idCurp = $fr['curp_ocr'] ?? ($rv['curp_ocr'] ?? null);
                $idNombre = $fr['nombre_ocr'] ?? ($rv['nombre_ocr'] ?? null);
                $idScoreFrente = $fr['score_autenticidad'] ?? null;
                $idScoreReverso = $rv['score_autenticidad'] ?? null;
                foreach (($cal['notas'] ?? []) as $n) {
                    $txt = trim((string) $n);
                    if ($txt !== '') $alertas[] = $txt;
                }
            } elseif ($tipo === 'CURP' && is_array($cal)) {
                $curpDoc = $cal['curp_extraido'] ?? null;
                $curpNombre = $cal['nombre'] ?? null;
                $curpReciente = $cal['es_reciente'] ?? null;
                $curpMeses = $cal['meses_antiguedad'] ?? null;
                $curpFecha = $cal['fecha_emision'] ?? null;
            } elseif (in_array($tipo, ['NÚMERO DE SEGURIDAD SOCIAL', 'NUMERO DE SEGURIDAD SOCIAL', 'NÃšMERO DE SEGURIDAD SOCIAL'], true)) {
                $nssCurp = is_array($cal) ? ($cal['curp'] ?? null) : null;
                $nssNombre = is_array($cal) ? ($cal['nombre'] ?? null) : null;
            } elseif ($tipo === 'CONSTANCIA DE SITUACION FISCAL' && is_array($fis)) {
                $fiscalCurp = $fis['curp'] ?? null;
                $fiscalNombre = $fis['nombre'] ?? null;
            } elseif (($tipo === 'ACTA DE NACIMIENTO' || $tipo === 'ACTA DE NACIMIENTO CERTIFICADA') && is_array($cal)) {
                $actaNombre = $cal['nombre'] ?? null;
            }
        }

        if (!$idCurp && !$idNombre && !$curpDoc && !$curpNombre) return null;

        $comparaciones = [];
        if ($idCurp && $curpDoc) {
            $sameCurp = $this->docVerifCurpComparable($idCurp) === $this->docVerifCurpComparable($curpDoc);
            $coincide = $sameCurp || ($idNombre && $curpNombre && $this->docVerifNombresCoinciden($idNombre, $curpNombre));
            $this->docVerifBoolComp($comparaciones, 'curp_id_vs_documento', 'identificacion', $idCurp, 'documento_curp', $curpDoc, $coincide);
            if (!$sameCurp && $coincide) {
                $comparaciones['curp_id_vs_documento']['advertencia_ocr'] = true;
                $comparaciones['curp_id_vs_documento']['nota'] = 'CURP OCR de identificación difiere, pero nombres coinciden; se usa CURP oficial.';
            } elseif (!$coincide) {
                $alertas[] = 'CURP de identificación difiere del documento CURP y los nombres no coinciden.';
            }
        }
        if ($idNombre && $curpNombre) $this->docVerifBoolComp($comparaciones, 'nombre_id_vs_curp_pdf', 'identificacion', $idNombre, 'documento_curp', $curpNombre, $this->docVerifNombresCoinciden($idNombre, $curpNombre));
        if ($nombreCandidatoRegistro && $curpNombre) $this->docVerifBoolComp($comparaciones, 'nombre_registro_vs_documentos', 'registro', $nombreCandidatoRegistro, 'documento_curp', $curpNombre, $this->docVerifNombresCoinciden($nombreCandidatoRegistro, $curpNombre));
        if ($curpDoc) {
            $comparaciones['curp_pdf_frescura'] = ['fecha_emision' => $curpFecha, 'es_reciente' => $curpReciente, 'meses_antiguedad' => $curpMeses];
            if ($curpReciente === false) $alertas[] = 'Constancia CURP fuera de vigencia.';
        }
        if ($curpDoc && $fiscalCurp) $this->docVerifBoolComp($comparaciones, 'curp_vs_fiscal', 'documento_curp', $curpDoc, 'constancia_fiscal', $fiscalCurp, $this->docVerifCurpComparable($curpDoc) === $this->docVerifCurpComparable($fiscalCurp));
        if (($idNombre || $curpNombre) && $fiscalNombre) $this->docVerifBoolComp($comparaciones, 'nombre_vs_fiscal', 'identificacion', $idNombre ?: $curpNombre, 'constancia_fiscal', $fiscalNombre, $this->docVerifNombresCoinciden($idNombre ?: $curpNombre, $fiscalNombre));
        if ($curpDoc && $nssCurp) $this->docVerifBoolComp($comparaciones, 'curp_vs_nss', 'documento_curp', $curpDoc, 'nss', $nssCurp, $this->docVerifCurpComparable($curpDoc) === $this->docVerifCurpComparable($nssCurp));
        if (($idNombre || $curpNombre) && $nssNombre) $this->docVerifBoolComp($comparaciones, 'nombre_vs_nss', 'identificacion', $idNombre ?: $curpNombre, 'nss', $nssNombre, $this->docVerifNombresCoinciden($idNombre ?: $curpNombre, $nssNombre));
        if (($idNombre || $curpNombre) && $actaNombre) $this->docVerifBoolComp($comparaciones, 'nombre_vs_acta', 'identificacion', $idNombre ?: $curpNombre, 'acta_nacimiento', $actaNombre, $this->docVerifNombresCoinciden($idNombre ?: $curpNombre, $actaNombre));
        if ($nombreCandidatoRegistro && $actaNombre) $this->docVerifBoolComp($comparaciones, 'nombre_registro_vs_acta', 'registro', $nombreCandidatoRegistro, 'acta_nacimiento', $actaNombre, $this->docVerifNombresCoinciden($nombreCandidatoRegistro, $actaNombre));

        $checksOk = 0; $checksTot = 0;
        foreach ($comparaciones as $key => $cmp) {
            if ($key === 'curp_pdf_frescura') {
                if (array_key_exists('es_reciente', $cmp) && $cmp['es_reciente'] !== null) { $checksTot++; if ($cmp['es_reciente'] === true) $checksOk++; }
            } elseif (array_key_exists('coincide', $cmp)) {
                $checksTot++; if ($cmp['coincide'] === true) $checksOk++;
            }
        }
        if ($checksTot === 0) return null;

        return [
            'todo_coincide' => $checksOk === $checksTot,
            'foto_rechazada' => false,
            'curp_definitivo' => $curpDoc ?: $idCurp,
            'checks_ok' => $checksOk,
            'checks_totales' => $checksTot,
            'alertas' => array_values(array_unique(array_filter($alertas))),
            'identificacion_frente_score' => $idScoreFrente,
            'identificacion_reverso_score' => $idScoreReverso,
            'comparaciones' => $comparaciones,
            'nombre_ocr' => $idNombre ?: $curpNombre,
            'anio_nacimiento' => null,
            'tipo_documento' => 'cache_documentos',
            'tiempo_proceso_ms' => 0,
            'tiempos_fase_ms' => ['cruce_cache_ms' => 0],
            'modo_verificacion' => $soloIdentificacion ? 'solo_identificacion' : 'cache_documentos',
        ];
    }

    /**
     * Rellena el PDF con AcroForm usando los datos del candidato.
     * Usa pdftk si está disponible y config/campos_solicitud_pdf.ini para mapear nombres de campo.
     * @param string $rutaPdf Ruta absoluta al PDF con formulario (ej. solicitud_interna___SPARTA_SECRET_REDACTED___AcroForm.pdf)
     * @param array $datosCandidato Array de clave => valor (nombre_completo, email, etc.)
     * @param string $dirConfig Directorio donde está config (para campos_solicitud_pdf.ini)
     * @return string|null PDF binario rellenado o null si falla o pdftk no disponible
     */
    private function rellenarPdfAcroFormConDatos($rutaPdf, array $datosCandidato, $dirConfig)
    {
        $configFile = $dirConfig . '/config.ini';
        $pdftkPath = null;
        if (is_file($configFile)) {
            $cfg = @parse_ini_file($configFile, true);
            $pdftkPath = isset($cfg['pdf']['pdftk_path']) ? trim($cfg['pdf']['pdftk_path']) : null;
        }
        if ($pdftkPath === null || $pdftkPath === '') {
            $pdftkPath = 'pdftk';
            // En Windows pdftk suele no estar en PATH; intentar rutas habituales
            if (DIRECTORY_SEPARATOR === '\\' || (defined('PHP_OS_FAMILY') && strtoupper(substr(PHP_OS_FAMILY, 0, 3)) === 'WIN')) {
                $rutasWindows = [
                    'C:\\Program Files (x86)\\PDFtk Server\\bin\\pdftk.exe',
                    'C:\\Program Files\\PDFtk Server\\bin\\pdftk.exe',
                    'C:\\pdftk\\bin\\pdftk.exe',
                ];
                foreach ($rutasWindows as $r) {
                    if (is_file($r)) {
                        $pdftkPath = $r;
                        break;
                    }
                }
            }
        }
        $rutaPdf = str_replace('\\', '/', realpath($rutaPdf));
        if ($rutaPdf === false || !is_file($rutaPdf)) {
            return null;
        }

        // Mapeo: nombre_campo_pdf => clave en $datosCandidato
        $mapeo = $this->mapeoCamposSolicitudPdf($dirConfig);
        $fieldValues = [];
        foreach ($mapeo as $nombreCampoPdf => $claveDato) {
            if (array_key_exists($claveDato, $datosCandidato)) {
                $v = $datosCandidato[$claveDato];
                if ($v !== '' && $v !== null) {
                    $fieldValues[$nombreCampoPdf] = $v;
                }
            }
        }
        // CURP: repartir cada carácter en curp_1, curp_2, ... curp_18 (cuadros del PDF)
        if (!empty($datosCandidato['curp'])) {
            $curp = strtoupper(preg_replace('/[^A-Z0-9]/', '', (string) $datosCandidato['curp']));
            $len = min(18, strlen($curp));
            for ($i = 1; $i <= 18; $i++) {
                $fieldValues['curp_' . $i] = ($i <= $len) ? $curp[$i - 1] : '';
            }
        }
        if (empty($fieldValues)) {
            return null;
        }

        $fdf = $this->generarFdfCampos($fieldValues);
        if ($fdf === '') {
            return null;
        }

        $tempDir = defined('RAIZ') ? (RAIZ . '/storage/tmp_mpdf') : (__DIR__ . '/../storage/tmp_mpdf');
        if (!is_dir($tempDir)) {
            @mkdir($tempDir, 0755, true);
        }
        if (!is_dir($tempDir)) {
            $tempDir = sys_get_temp_dir();
        }
        $fdfFile = $tempDir . '/solicitud_' . uniqid('', true) . '.fdf';
        $outFile = $tempDir . '/solicitud_' . uniqid('', true) . '.pdf';
        $written = @file_put_contents($fdfFile, $fdf);
        if ($written === false) {
            return null;
        }

        $cmd = sprintf(
            '%s %s fill_form %s output %s 2>&1',
            escapeshellarg($pdftkPath),
            escapeshellarg($rutaPdf),
            escapeshellarg($fdfFile),
            escapeshellarg($outFile)
        );
        $output = [];
        $ret = 0;
        @exec($cmd, $output, $ret);
        @unlink($fdfFile);
        if ($ret !== 0 || !is_file($outFile)) {
            if (is_file($outFile)) {
                @unlink($outFile);
            }
            error_log('CapHum::rellenarPdfAcroFormConDatos pdftk failed: ret=' . $ret . ' cmd=' . $cmd . ' output=' . implode(' ', $output));
            return null;
        }
        $pdfContent = @file_get_contents($outFile);
        @unlink($outFile);
        return $pdfContent !== false ? $pdfContent : null;
    }

    /**
     * Mapeo nombre_campo_pdf => clave_dato_candidato.
     * Si existe config/campos_solicitud_pdf.ini [campos] se usa; si no, mapeo por defecto.
     */
    private function mapeoCamposSolicitudPdf($dirConfig)
    {
        $ini = $dirConfig . '/campos_solicitud_pdf.ini';
        if (is_file($ini)) {
            $parsed = @parse_ini_file($ini, true);
            if (!empty($parsed['campos']) && is_array($parsed['campos'])) {
                return $parsed['campos'];
            }
        }
        return [
            'nombre_completo' => 'nombre_completo',
            'email'           => 'email',
            'telefono'        => 'telefono',
            'puesto'          => 'puesto',
            'departamento'    => 'departamento',
            'fecha'           => 'fecha',
        ];
    }

    /**
     * Genera contenido FDF para rellenar campos del PDF (sintaxis FDF 1.2).
     * Escapa correctamente los valores para el formato ( \ ( ) ).
     */
    private function generarFdfCampos(array $fieldValues)
    {
        $entries = [];
        foreach ($fieldValues as $name => $value) {
            $nameEscaped = $this->escapeFdfString((string) $name);
            $valueEscaped = $this->escapeFdfString((string) $value);
            $entries[] = "<< /T ($nameEscaped) /V ($valueEscaped) >>";
        }
        $fields = "[\n" . implode("\n", $entries) . "\n]";
        return "%FDF-1.2\n1 0 obj\n<< /FDF << /Fields $fields >> >>\nendobj\ntrailer\n<< /Root 1 0 R >>\n%%EOF";
    }

    private function escapeFdfString($s)
    {
        return str_replace([ '\\', '(', ')' ], [ '\\\\', '\\(', '\\)' ], $s);
    }

    private function subirDocumentosCandidatoError($mensaje)
    {
        unset($_SESSION['candidato_documentos_token_publico']);
        $this->set('error_mensaje', $mensaje);
        $this->set('token', '');
        $this->set('api_verificacion_base', $this->getApiVerificacionBase());
        $this->render('subir_documentos_candidato', true);
    }

    /**
     * Base URL usada por la vista para validar documentos.
     * Importante: debe ser mismo origen (PHP) para evitar bloqueos CORS/PNA en navegador.
     */
    private function getApiVerificacionBase()
    {
        return '/CapHum/docVerificacionProxy';
    }

    /**
     * Proxy server-side para la API Python de verificación de documentos.
     * Evita llamadas directas del navegador a 127.0.0.1 (bloqueadas por CORS/PNA).
     */
    public function docVerificacionProxy($endpoint = '')
    {
        if (($_SERVER['REQUEST_METHOD'] ?? 'GET') !== 'POST') {
            http_response_code(405);
            header('Content-Type: application/json; charset=utf-8');
            echo json_encode(['ok' => false, 'mensaje' => 'Método no permitido.']);
            return;
        }

        if (empty($_SESSION['login'])) {
            $tokenPublico = trim((string) ($_SESSION['candidato_documentos_token_publico'] ?? ''));
            $resToken = $tokenPublico !== '' ? CandidatosDAO::getCandidatoPorToken($tokenPublico) : ['success' => false];
            if (!$resToken['success'] || empty($resToken['datos'])) {
                unset($_SESSION['candidato_documentos_token_publico']);
                http_response_code(401);
                header('Content-Type: application/json; charset=utf-8');
                echo json_encode(['ok' => false, 'mensaje' => 'Enlace público no válido o expirado.']);
                return;
            }
        }

        $endpoint = trim((string) $endpoint, " \t\n\r\0\x0B/");
        if ($endpoint === '') {
            $endpoint = trim((string) ($_GET['endpoint'] ?? ''), " \t\n\r\0\x0B/");
        }

        $permitidos = [
            'verificar',
            'verificar-calidad',
            'precheck-identificacion-pdf',
            'verificar-calidad-identificacion-pdf',
            'verificar-comprobante',
            'verificar-curp-documento',
            'verificar-constancia-fiscal-documento',
            'verificar-nss-documento',
            'verificar-estado-cuenta',
        ];
        if (!in_array($endpoint, $permitidos, true)) {
            http_response_code(400);
            header('Content-Type: application/json; charset=utf-8');
            echo json_encode(['ok' => false, 'mensaje' => 'Endpoint de verificación no permitido.']);
            return;
        }

        $cfg = $this->getDocVerificacionConfig();
        if ($cfg === null) {
            http_response_code(503);
            header('Content-Type: application/json; charset=utf-8');
            echo json_encode(['ok' => false, 'mensaje' => 'API de verificación no configurada.']);
            return;
        }

        $targetUrl = rtrim($cfg['base_url'], '/') . '/' . $endpoint;
        if (!empty($_SERVER['QUERY_STRING'])) {
            parse_str((string) $_SERVER['QUERY_STRING'], $queryParams);
            unset($queryParams['url'], $queryParams['endpoint']);
            if (!empty($queryParams)) {
                $targetUrl .= '?' . http_build_query($queryParams);
            }
        }

        $postFields = [];
        foreach ($_FILES as $name => $file) {
            $tmpName = $file['tmp_name'] ?? '';
            if ($tmpName === '' || !is_uploaded_file($tmpName)) {
                continue;
            }
            $mime = trim((string) ($file['type'] ?? ''));
            $filename = basename((string) ($file['name'] ?? 'documento.bin'));
            $postFields[$name] = new \CURLFile($tmpName, $mime !== '' ? $mime : 'application/octet-stream', $filename);
        }

        if (empty($postFields)) {
            http_response_code(400);
            header('Content-Type: application/json; charset=utf-8');
            echo json_encode(['ok' => false, 'mensaje' => 'No se recibió archivo para verificar.']);
            return;
        }

        $timeout = 15;
        if ($endpoint === 'verificar-calidad-identificacion-pdf') {
            // El análisis de PDFs de identificación puede tardar más de 60s.
            $timeout = 30;
        } elseif ($endpoint === 'verificar-curp-documento' || $endpoint === 'verificar-constancia-fiscal-documento') {
            $timeout = 12;
        }

        $ch = curl_init($targetUrl);
        curl_setopt_array($ch, [
            CURLOPT_POST => true,
            CURLOPT_POSTFIELDS => $postFields,
            CURLOPT_HTTPHEADER => ['X-API-Key: ' . $cfg['api_key']],
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_TIMEOUT => $timeout,
            CURLOPT_CONNECTTIMEOUT => 8,
        ]);
        $body = curl_exec($ch);
        $httpCode = (int) curl_getinfo($ch, CURLINFO_HTTP_CODE);
        $curlErr = curl_error($ch);
        $contentType = (string) curl_getinfo($ch, CURLINFO_CONTENT_TYPE);
        curl_close($ch);

        if ($body === false) {
            http_response_code(502);
            header('Content-Type: application/json; charset=utf-8');
            echo json_encode(['ok' => false, 'mensaje' => $curlErr !== '' ? $curlErr : 'No se pudo conectar con la API de verificación.']);
            return;
        }

        if ($httpCode <= 0) {
            $httpCode = 502;
        }
        http_response_code($httpCode);
        if (stripos($contentType, 'application/json') !== false) {
            header('Content-Type: application/json; charset=utf-8');
        } else {
            header('Content-Type: text/plain; charset=utf-8');
        }
        echo $body;
    }

    /**
     * Base HTTP de la API Python (â€¦/api/v1) a partir de [doc_verificacion] api_url.
     * Acepta p.ej. http://127.0.0.1:8000/api/v1/verificar, http://127.0.0.1:8000/verificar o solo host:puerto.
     */
    private function normalizarBaseUrlDocVerificacion(string $apiUrl): string
    {
        $apiUrl = trim($apiUrl);
        if ($apiUrl !== '' && ($apiUrl[0] === '"' || $apiUrl[0] === "'")) {
            $apiUrl = trim($apiUrl, " \t\n\r\0\x0B\"'");
        }
        $base = preg_replace('#/verificar\s*$#i', '', $apiUrl);
        $base = rtrim(trim((string) $base), '/');
        if ($base === '') {
            return '';
        }
        if (!preg_match('#/api/v1$#i', $base)) {
            $base .= '/api/v1';
        }

        return $base;
    }

    /** POST/GET solo_identificacion=1 solo para usuario de sesión id 1 (diagnóstico; no exponer al resto del módulo). */
    private function docVerificacionPetitorioSoloIdentificacion(): bool
    {
        if ((int) ($_SESSION['usuario_id'] ?? 0) !== 1) {
            return false;
        }
        $v = $_POST['solo_identificacion'] ?? $_GET['solo_identificacion'] ?? '';
        if ($v === '1' || $v === 1) {
            return true;
        }
        $s = strtolower(trim((string) $v));

        return in_array($s, ['true', 'yes', 'on'], true);
    }

    /** config.ini [doc_verificacion] validar_expediente_solo_identificacion = 1 */
    private function docVerificacionIniSoloIdentificacion(): bool
    {
        $configFile = defined('RAIZ') ? (RAIZ . '/config/config.ini') : (__DIR__ . '/../config/config.ini');
        if (!is_file($configFile)) {
            return false;
        }
        $config = @parse_ini_file($configFile, true);
        $iniVal = strtolower(trim((string) ($config['doc_verificacion']['validar_expediente_solo_identificacion'] ?? '0')));

        return in_array($iniVal, ['1', 'true', 'yes', 'on'], true);
    }

    /** config.ini [doc_verificacion] validar_expediente_incluir_acta = 1 para activar OCR/cotejo de acta en el cruce completo. */
    private function docVerificacionIniIncluirActa(): bool
    {
        $configFile = defined('RAIZ') ? (RAIZ . '/config/config.ini') : (__DIR__ . '/../config/config.ini');
        if (!is_file($configFile)) {
            return false;
        }
        $config = @parse_ini_file($configFile, true);
        $iniVal = strtolower(trim((string) ($config['doc_verificacion']['validar_expediente_incluir_acta'] ?? '0')));

        return in_array($iniVal, ['1', 'true', 'yes', 'on'], true);
    }

    /**
     * @param array<string, mixed> $rutasParaValidar referencia (identificacion_pdf + opcionales)
     */
    private function docVerificacionQuitarAdjuntosOpcionalesExpediente(array &$rutasParaValidar): void
    {
        foreach (['curp', 'nss', 'constancia_fiscal', 'acta_nacimiento'] as $k) {
            $rutasParaValidar[$k] = null;
        }
    }

    /**
     * Arma el JSON guardado en candidatos.ultima_verificacion_expediente a partir de la respuesta OK de la API.
     *
     * @param array<string, mixed> $resultadoApi
     * @return array<string, mixed>
     */
    private function expedientePayloadDesdeApi(array $resultadoApi, bool $soloIdentificacion): array
    {
        $alertaModo = $soloIdentificacion
            ? ['Modo prueba: solo se envió el PDF de identificación a la API (no se adjuntaron CURP, NSS, constancia fiscal ni acta). Desactive la casilla o validar_expediente_solo_identificacion=0 para verificación completa.']
            : [];

        return [
            'todo_coincide' => $resultadoApi['todo_coincide'] ?? false,
            'foto_rechazada' => $resultadoApi['foto_rechazada'] ?? false,
            'curp_definitivo' => $resultadoApi['curp_definitivo'] ?? null,
            'checks_ok' => $resultadoApi['checks_ok'] ?? 0,
            'checks_totales' => $resultadoApi['checks_totales'] ?? 0,
            'alertas' => array_merge($alertaModo, $resultadoApi['alertas'] ?? []),
            'identificacion_frente_score' => $resultadoApi['identificacion_frente_score'] ?? null,
            'identificacion_reverso_score' => $resultadoApi['identificacion_reverso_score'] ?? null,
            'comparaciones' => $resultadoApi['comparaciones'] ?? null,
            'nombre_ocr' => $resultadoApi['nombre_ocr'] ?? null,
            'anio_nacimiento' => $resultadoApi['anio_nacimiento'] ?? null,
            'tipo_documento' => $resultadoApi['tipo_documento'] ?? null,
            'tiempo_proceso_ms' => $resultadoApi['tiempo_proceso_ms'] ?? null,
            'tiempos_fase_ms' => $resultadoApi['tiempos_fase_ms'] ?? null,
            'modo_verificacion' => $soloIdentificacion ? 'solo_identificacion' : 'completo',
        ];
    }

    /**
     * Helpers para no degradar una lectura rápida buena con un timeout/fallo técnico posterior.
     */
    private function docVerifJsonArray($json): ?array
    {
        if (is_array($json)) {
            return $json;
        }
        if (!is_string($json) || trim($json) === '') {
            return null;
        }
        $dec = json_decode($json, true);
        return is_array($dec) ? $dec : null;
    }

    private function docVerifTextoNormalizado(array $resultado): string
    {
        $partes = [
            (string) ($resultado['mensaje'] ?? ''),
            (string) ($resultado['recomendacion'] ?? ''),
            (string) ($resultado['nota_backend'] ?? ''),
            (string) ($resultado['error'] ?? ''),
        ];
        foreach (['notas', 'alertas'] as $k) {
            if (!empty($resultado[$k]) && is_array($resultado[$k])) {
                foreach ($resultado[$k] as $v) {
                    $partes[] = is_scalar($v) ? (string) $v : '';
                }
            }
        }
        $txt = strtoupper(implode(' ', $partes));
        $txt = strtr($txt, ['Á' => 'A', 'É' => 'E', 'Í' => 'I', 'Ó' => 'O', 'Ú' => 'U', 'Ñ' => 'N']);
        return preg_replace('/\s+/', ' ', $txt) ?: '';
    }

    private function docVerifResultadoTecnico(array $resultado): bool
    {
        if (!empty($resultado['timeout']) || !empty($resultado['error_api']) || !empty($resultado['api_pendiente']) || !empty($resultado['pendiente_revision_backend']) || !empty($resultado['nota_backend'])) {
            return true;
        }
        $txt = $this->docVerifTextoNormalizado($resultado);
        foreach (['TIMEOUT', 'TARDO MAS', 'NO SE OBTUVO RESPUESTA', 'NO SE PUDO CONFIRMAR', 'NO SE PUDO LEER', 'NO SE PUDO REVISAR', 'NO SE PUDO CONTACTAR', 'API NO RESPOND', 'NO RESPONDIO CORRECTAMENTE', 'HTTP ', 'CURL', 'JSON VALIDO'] as $needle) {
            if (strpos($txt, $needle) !== false) {
                return true;
            }
        }
        return false;
    }

    private function docVerifTieneDatosUtiles(?array $resultado): bool
    {
        if (!$resultado) {
            return false;
        }
        if (($resultado['valido'] ?? null) === true || ($resultado['ok'] ?? null) === true || ($resultado['aceptado'] ?? null) === true) {
            return true;
        }
        foreach (['curp_extraido', 'curp', 'nombre', 'rfc', 'nss', 'banco', 'banco_detectado', 'tipo_documento', 'tipo_identificacion', 'documento_detectado'] as $k) {
            if (isset($resultado[$k]) && trim((string) $resultado[$k]) !== '') {
                return true;
            }
        }
        foreach (['detalle_frente', 'detalle_reverso', 'datos_extraidos', 'datos_titular'] as $k) {
            if (!empty($resultado[$k]) && is_array($resultado[$k])) {
                return true;
            }
        }
        return false;
    }

    private function docVerifDebeConservarAnterior(?array $anterior, ?array $nuevo): bool
    {
        if (!$anterior || !$nuevo) {
            return false;
        }
        return $this->docVerifTieneDatosUtiles($anterior)
            && !$this->docVerifTieneDatosUtiles($nuevo)
            && $this->docVerifResultadoTecnico($nuevo);
    }

    private function docVerifExpedientePendienteTecnico($verificacion): bool
    {
        if (!is_array($verificacion)) {
            return false;
        }
        if (!empty($verificacion['verificacion_en_proceso']) || !empty($verificacion['api_pendiente'])) {
            return true;
        }
        if (isset($verificacion['error_api']) && trim((string) $verificacion['error_api']) !== '') {
            return true;
        }
        $checks = isset($verificacion['checks_totales']) ? (int) $verificacion['checks_totales'] : null;
        return $checks === 0 && empty($verificacion['comparaciones']);
    }

    private function docListCacheTienePendienteTecnico(string $json): bool
    {
        $dec = json_decode($json, true);
        if (!is_array($dec)) {
            return false;
        }
        $verificacion = $dec['datos']['verificacion_expediente'] ?? null;
        return $this->docVerifExpedientePendienteTecnico($verificacion);
    }

    /**
     * Obtiene configuración de la API de verificación de documentos.
     */
    private function getDocVerificacionConfig()
    {
        $configFile = defined('RAIZ') ? (RAIZ . '/config/config.ini') : (__DIR__ . '/../config/config.ini');
        if (!is_file($configFile)) {
            return null;
        }
        $config = @parse_ini_file($configFile, true);
        $apiUrl = trim((string) ($config['doc_verificacion']['api_url'] ?? ''));
        $apiKey = trim((string) ($config['doc_verificacion']['api_key'] ?? ''));
        if ($apiUrl === '' || $apiKey === '') {
            return null;
        }
        $base = $this->normalizarBaseUrlDocVerificacion($apiUrl);
        if ($base === '') {
            return null;
        }
        return [
            'base_url' => $base,
            'api_key' => $apiKey,
        ];
    }

    /**
     * Listar documentos del expediente de un candidato (JSON). Requiere módulo Candidatos.
     * GET: id_candidato (query).
     * Optimizado: una sola conexión DB, caché 45s (file o APCu), invalidación al subir/eliminar/verificar.
     */
    public function getDocumentosCandidatoList()
    {
        header('Content-Type: application/json; charset=utf-8');
        $id_candidato = (int) ($_GET['id_candidato'] ?? 0);
        if ($id_candidato <= 0) {
            echo json_encode(self::respuesta(false, 'id_candidato inválido.'));
            return;
        }

        $cacheDir = defined('RAIZ') ? (RAIZ . '/storage/cache') : (__DIR__ . '/../storage/cache');
        $cacheKey = 'doc_candidato_v3_' . $id_candidato;
        $ttl = 45;

        if (function_exists('apcu_fetch')) {
            $cached = @\apcu_fetch($cacheKey);
            if ($cached !== false && is_array($cached) && isset($cached['ts']) && (time() - $cached['ts']) <= $ttl && isset($cached['json'])) {
                if (!$this->docListCacheTienePendienteTecnico((string) $cached['json'])) {
                    header('X-Doc-List-Cache: hit');
                    header('X-Doc-List-Cache-Ttl-Sec: ' . $ttl);
                    echo $cached['json'];
                    return;
                }
                @\apcu_delete($cacheKey);
            }
        } else {
            $cacheFile = $cacheDir . '/' . $cacheKey . '.json';
            if (is_file($cacheFile) && (time() - filemtime($cacheFile)) <= $ttl) {
                $raw = @file_get_contents($cacheFile);
                if ($raw !== false && $raw !== '') {
                    if (!$this->docListCacheTienePendienteTecnico((string) $raw)) {
                        header('X-Doc-List-Cache: hit');
                        header('X-Doc-List-Cache-Ttl-Sec: ' . $ttl);
                        echo $raw;
                        return;
                    }
                    @unlink($cacheFile);
                }
            }
        }

        $data = CandidatosDAO::getDocumentosYVerificacion($id_candidato);
        $documentos = $data['documentos'] ?? [];
        $verificacion = $data['verificacion'] ?? null;
        if (is_array($verificacion)) {
            $errApi = trim((string) ($verificacion['error_api'] ?? ''));
            if ($errApi !== '') {
                $verificacion['comparaciones'] = null;
            } else {
                $ct = isset($verificacion['checks_totales']) ? (int) $verificacion['checks_totales'] : -1;
                $noScores = empty($verificacion['identificacion_frente_score']) && empty($verificacion['identificacion_reverso_score']);
                if ($ct === 0 && $noScores && !empty($verificacion['comparaciones']) && is_array($verificacion['comparaciones'])) {
                    $verificacion['comparaciones'] = null;
                }
            }
        }

        $payload = ['documentos' => $documentos];
        if ($verificacion !== null) {
            $payload['verificacion_expediente'] = $verificacion;
        }
        $tiposRequeridos = [
            'SOLICITUD INTERNA' => 1, 'CV O SOLICITUD DE TRABAJO' => 2, 'ACTA DE NACIMIENTO' => 3, 'ACTA DE NACIMIENTO Certificada' => 3,
            'CURP' => 4, 'IDENTIFICACIÃ“N OFICIAL' => 5,
            'COMPROBANTE DE DOMICILIO' => 6, 'CONSTANCIA DE SITUACION FISCAL' => 7, 'NÃšMERO DE SEGURIDAD SOCIAL' => 8,
            'HOJA DE RETENCION FONACOT O INFONAVIT' => 9, 'ESTADO DE CUENTA' => 10,
        ];
        $clavesUnicas = [];
        $normalize = function ($s) {
            $s = trim(mb_strtoupper($s ?? ''));
            $s = str_replace(['', 'Ã“', 'Ãš', '', 'Ã‰', 'Ã‘'], ['I', 'O', 'U', 'A', 'E', 'N'], $s);
            return preg_replace('/\s+/', ' ', $s);
        };
        foreach ($documentos as $d) {
            $tipo = $normalize($d['tipo_documento'] ?? '');
            foreach ($tiposRequeridos as $nombre => $num) {
                $nombreNorm = $normalize($nombre);
                if ($tipo === $nombreNorm || strpos($tipo, $nombreNorm) !== false || strpos($nombreNorm, $tipo) !== false) {
                    $clavesUnicas[is_string($num) ? $num : $num] = true;
                    break;
                }
            }
        }
        $totalRequeridos = 10;
        $totalActual = count($clavesUnicas);
        $expedienteCompleto = ($totalActual >= $totalRequeridos
            && isset($clavesUnicas[1]) && isset($clavesUnicas[2]) && isset($clavesUnicas[3]) && isset($clavesUnicas[4])
            && isset($clavesUnicas[5]) && isset($clavesUnicas[6]) && isset($clavesUnicas[7]) && isset($clavesUnicas[8])
            && isset($clavesUnicas[9]) && isset($clavesUnicas[10]));
        $payload['metricas'] = [
            'total_documentos' => $totalActual,
            'documentos_requeridos' => $totalRequeridos,
            'porcentaje' => $totalRequeridos > 0 ? min(100, (int) round(($totalActual / $totalRequeridos) * 100)) : 0,
            'expediente_completo' => $expedienteCompleto,
        ];
        $conteoValidados = CandidatosDAO::contarValidados($id_candidato);
        $payload['metricas']['validados'] = (int) ($conteoValidados['validados'] ?? 0);
        $payload['metricas'] = $this->calcularMetricasDocumentosCandidato($documentos, $id_candidato);

        if (!empty($payload['metricas']['expediente_completo']) && ($verificacion === null || $this->docVerifExpedientePendienteTecnico($verificacion))) {
            $candidatoRes = CandidatosDAO::getById($id_candidato);
            $candidato = ($candidatoRes['success'] ?? false) && !empty($candidatoRes['datos']) ? $candidatoRes['datos'] : [];
            $nombreCandidatoRegistro = trim(($candidato['nombres'] ?? '') . ' ' . ($candidato['apellidop'] ?? '') . ' ' . ($candidato['apellidom'] ?? ''));
            $payloadCache = $this->expedientePayloadDesdeCacheDocumentos($documentos, $nombreCandidatoRegistro, $this->docVerificacionIniSoloIdentificacion());
            if (is_array($payloadCache) && (int) ($payloadCache['checks_totales'] ?? 0) > 0) {
                $payloadCache['api_pendiente'] = false;
                $payloadCache['error_api'] = null;
                $payloadCache['alertas'] = array_values(array_filter($payloadCache['alertas'] ?? [], function ($a) {
                    $txt = strtoupper((string) $a);
                    return strpos($txt, 'FALLO TECNICO') === false && strpos($txt, 'API') === false;
                }));
                $verificacion = $payloadCache;
                $payload['verificacion_expediente'] = $payloadCache;
                CandidatosDAO::updateVerificacionExpediente($id_candidato, json_encode($payloadCache));
            } else {
                $resCola = $this->encolarVerificacionDocumentalCandidato($id_candidato, [], true, $verificacion === null ? 'modal_auto_sin_dictamen' : 'modal_auto_reintento');
                $payloadEnProceso = [
                    'verificacion_en_proceso' => true,
                    'todo_coincide' => null,
                    'foto_rechazada' => false,
                    'checks_ok' => 0,
                    'checks_totales' => 0,
                    'alertas' => ['Validacion documental en proceso. El expediente ya esta completo y se esta ejecutando el cruce automatico.'],
                    'identificacion_frente_score' => null,
                    'identificacion_reverso_score' => null,
                    'comparaciones' => null,
                    'modo_verificacion' => 'cola_background',
                    'api_pendiente' => false,
                    'error_api' => null,
                    'job_id' => (int) ($resCola['datos']['id_job'] ?? 0),
                    'iniciado_en' => date('Y-m-d H:i:s'),
                ];
                $verificacion = $payloadEnProceso;
                $payload['verificacion_expediente'] = $payloadEnProceso;
            }
        }

        $json = json_encode(self::respuesta(true, 'OK', $payload));

        header('X-Doc-List-Cache: miss');

        if (function_exists('apcu_store')) {
            @\apcu_store($cacheKey, ['ts' => time(), 'json' => $json], $ttl);
        } else {
            if (!is_dir($cacheDir)) {
                @mkdir($cacheDir, 0755, true);
            }
            $cacheFile = $cacheDir . '/' . $cacheKey . '.json';
            @file_put_contents($cacheFile, $json, LOCK_EX);
        }

        echo $json;
    }

    /**
     * Ejecutar verificación API del expediente ahora (frente + reverso + PDFs).
     * POST/GET: id_candidato. Ãštil cuando la verificación no se disparó al subir documentos.
     */
    private function encolarVerificacionDocumentalCandidato($id_candidato, array $tiposSubidos = [], ?bool $expedienteCompleto = null, string $origen = 'upload'): array
    {
        $res = CandidatosDAO::encolarVerificacionDocumental((int) $id_candidato, $tiposSubidos, $expedienteCompleto, $origen);
        if (!empty($res['success']) && $expedienteCompleto === true) {
            $payloadEnProceso = [
                'verificacion_en_proceso' => true,
                'todo_coincide' => null,
                'foto_rechazada' => false,
                'checks_ok' => 0,
                'checks_totales' => 0,
                'alertas' => ['Verificacion automatica en cola local. Capital Humano puede continuar y la vista se actualizara al terminar.'],
                'identificacion_frente_score' => null,
                'identificacion_reverso_score' => null,
                'comparaciones' => null,
                'modo_verificacion' => 'cola_background',
                'api_pendiente' => false,
                'error_api' => null,
                'job_id' => (int) ($res['datos']['id_job'] ?? 0),
                'iniciado_en' => date('Y-m-d H:i:s'),
            ];
            CandidatosDAO::updateVerificacionExpediente((int) $id_candidato, json_encode($payloadEnProceso));
        }
        if (!empty($res['success'])) {
            $this->lanzarWorkerVerificacionDocumental();
        } else {
            error_log('CapHum::encolarVerificacionDocumental: ' . ($res['error'] ?? $res['mensaje'] ?? 'error desconocido'));
        }
        return $res;
    }

    private function phpCliBinarioVerificacionDocumental(): string
    {
        $candidatos = [];
        if (stripos(PHP_OS_FAMILY, 'Windows') !== false) {
            $candidatos[] = 'C:\\xampp\\php\\php.exe';
            if (defined('PHP_BINDIR') && PHP_BINDIR) {
                $candidatos[] = PHP_BINDIR . DIRECTORY_SEPARATOR . 'php.exe';
            }
        }
        if (defined('PHP_BINARY') && PHP_BINARY) {
            $base = strtolower(basename(PHP_BINARY));
            if (strpos($base, 'php') === 0) {
                $candidatos[] = PHP_BINARY;
                $candidatos[] = dirname(PHP_BINARY) . DIRECTORY_SEPARATOR . 'php.exe';
                $candidatos[] = dirname(PHP_BINARY) . DIRECTORY_SEPARATOR . 'php';
            }
        }
        if (stripos(PHP_OS_FAMILY, 'Windows') === false && defined('PHP_BINDIR') && PHP_BINDIR) {
            $candidatos[] = PHP_BINDIR . DIRECTORY_SEPARATOR . 'php';
        }
        $candidatos[] = 'php';

        foreach ($candidatos as $bin) {
            if ($bin === 'php' || is_file($bin)) {
                return $bin;
            }
        }
        return 'php';
    }

    private function lanzarWorkerVerificacionDocumental(): void
    {
        $projectRoot = defined('RAIZ') ? dirname(RAIZ) : dirname(__DIR__, 2);
        $script = $projectRoot . DIRECTORY_SEPARATOR . 'scripts' . DIRECTORY_SEPARATOR . 'procesar_verificacion_documental.php';
        if (!is_file($script)) {
            error_log('CapHum::lanzarWorkerVerificacionDocumental: no existe script ' . $script);
            return;
        }
        $php = $this->phpCliBinarioVerificacionDocumental();
        $logDir = defined('RAIZ') ? (RAIZ . DIRECTORY_SEPARATOR . 'logs') : (__DIR__ . DIRECTORY_SEPARATOR . '..' . DIRECTORY_SEPARATOR . 'logs');
        if (!is_dir($logDir)) {
            @mkdir($logDir, 0775, true);
        }
        $logSuffix = date('Ymd-His') . '-' . getmypid() . '-' . substr(str_replace('.', '', uniqid('', true)), -6);
        $outLog = $logDir . DIRECTORY_SEPARATOR . 'verificacion_documental_worker-' . $logSuffix . '.log';
        $errLog = $logDir . DIRECTORY_SEPARATOR . 'verificacion_documental_worker-' . $logSuffix . '.err.log';
        $cmdQuote = function ($value) {
            return '"' . str_replace('"', '""', (string) $value) . '"';
        };
        try {
            if (stripos(PHP_OS_FAMILY, 'Windows') !== false) {
                // En Windows "start" es un builtin de cmd; escapeshellarg produce comillas
                // incompatibles en algunos entornos PHP/IIS/Apache. Se arma cmd /C con
                // comillas dobles para que el worker realmente quede desacoplado.
                $cmd = 'cmd /C start "" /B '
                    . $cmdQuote($php) . ' '
                    . $cmdQuote($script) . ' --max 5'
                    . ' >> ' . $cmdQuote($outLog)
                    . ' 2>> ' . $cmdQuote($errLog);
                $h = @popen($cmd, 'r');
                if (is_resource($h)) {
                    @pclose($h);
                }
            } else {
                $cmd = escapeshellarg($php) . ' ' . escapeshellarg($script) . ' --max 5 >> ' . escapeshellarg($outLog) . ' 2>> ' . escapeshellarg($errLog) . ' &';
                @exec($cmd);
            }
        } catch (\Throwable $e) {
            error_log('CapHum::lanzarWorkerVerificacionDocumental: ' . $e->getMessage());
        }
    }

    public function procesarSiguienteVerificacionDocumentalJob(): array
    {
        $job = CandidatosDAO::tomarSiguienteJobVerificacionDocumental();
        if (!$job) {
            return ['procesado' => false, 'mensaje' => 'Sin trabajos pendientes.'];
        }

        $idJob = (int) ($job['id'] ?? 0);
        $idCandidato = (int) ($job['id_candidato'] ?? 0);
        $tipos = json_decode((string) ($job['tipos_subidos_json'] ?? '[]'), true);
        if (!is_array($tipos)) {
            $tipos = [];
        }
        $expedienteCompleto = null;
        if (array_key_exists('expediente_completo', $job) && $job['expediente_completo'] !== null) {
            $expedienteCompleto = ((int) $job['expediente_completo']) === 1;
        }

        try {
            $ok = $this->ejecutarVerificacionBackground($idCandidato, $tipos, $expedienteCompleto);
            CandidatosDAO::finalizarJobVerificacionDocumental($idJob, (bool) $ok, $ok ? null : 'La verificacion documental no pudo completarse.');
            return ['procesado' => true, 'ok' => (bool) $ok, 'id_job' => $idJob, 'id_candidato' => $idCandidato];
        } catch (\Throwable $e) {
            CandidatosDAO::finalizarJobVerificacionDocumental($idJob, false, $e->getMessage());
            return ['procesado' => true, 'ok' => false, 'id_job' => $idJob, 'id_candidato' => $idCandidato, 'error' => $e->getMessage()];
        }
    }

    public function subirDocumentoManualCandidato()
    {
        header('Content-Type: application/json; charset=utf-8');
        if (!self::puedeValidarDocumentalCandidatos() && !self::puedeValidarFinalCandidatos()) {
            echo json_encode(self::respuesta(false, 'No tienes permiso para subir documentos manualmente.'));
            return;
        }

        $idCandidato = (int) ($_POST['id_candidato'] ?? 0);
        $tipoNum = (int) ($_POST['tipo_documento'] ?? 0);
        $tiposDocumento = [
            1  => 'SOLICITUD INTERNA',
            2  => 'CV O SOLICITUD DE TRABAJO',
            3  => 'ACTA DE NACIMIENTO Certificada',
            4  => 'CURP',
            5  => 'IDENTIFICACION OFICIAL',
            6  => 'COMPROBANTE DE DOMICILIO',
            7  => 'CONSTANCIA DE SITUACION FISCAL',
            8  => 'NUMERO DE SEGURIDAD SOCIAL',
            9  => 'HOJA DE RETENCION FONACOT O INFONAVIT',
            10 => 'ESTADO DE CUENTA',
        ];
        $slugPorTipo = [
            1 => 'solicitud_interna', 2 => 'cv', 3 => 'acta_nacimiento', 4 => 'curp',
            5 => 'identificacion_oficial', 6 => 'comprobante_domicilio', 7 => 'constancia_fiscal',
            8 => 'nss', 9 => 'hoja_retencion', 10 => '__SPARTA_SECRET_REDACTED__',
        ];

        if ($idCandidato <= 0 || !isset($tiposDocumento[$tipoNum])) {
            echo json_encode(self::respuesta(false, 'Datos incompletos para subir el documento.'));
            return;
        }
        if (!isset($_FILES['archivo']) || ($_FILES['archivo']['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK) {
            echo json_encode(self::respuesta(false, 'Selecciona un PDF para subir.'));
            return;
        }

        $tmp = (string) ($_FILES['archivo']['tmp_name'] ?? '');
        $nombreOriginal = basename((string) ($_FILES['archivo']['name'] ?? 'documento.pdf'));
        $ext = strtolower(pathinfo($nombreOriginal, PATHINFO_EXTENSION));
        if ($tmp === '' || !is_uploaded_file($tmp) || $ext !== 'pdf' || !SecureUpload::validateMime($tmp, SecureUpload::MIME_PDF) || !$this->esPdfValidoBasico($tmp)) {
            echo json_encode(self::respuesta(false, 'Solo se acepta un archivo PDF valido.'));
            return;
        }

        $resCandidato = CandidatosDAO::getById($idCandidato);
        if (empty($resCandidato['success']) || empty($resCandidato['datos'])) {
            echo json_encode(self::respuesta(false, 'Candidato no encontrado.'));
            return;
        }

        $resDocs = CandidatosDAO::getDocumentosCandidato($idCandidato);
        if (!empty($resDocs['success']) && !empty($resDocs['datos'])) {
            foreach ($resDocs['datos'] as $docExistente) {
                if ($this->numeroTipoDocumentoCandidatoMetricas($docExistente['tipo_documento'] ?? '') === $tipoNum) {
                    echo json_encode(self::respuesta(false, 'Ese documento ya existe en el expediente. Si necesita reemplazarlo, primero elimine el documento actual.'));
                    return;
                }
            }
        }

        $dirBase = defined('RAIZ') ? (RAIZ . '/storage/candidatos') : (__DIR__ . '/../storage/candidatos');
        $dirExpediente = $dirBase . '/' . $idCandidato . '/expediente';
        if (!is_dir($dirExpediente)) {
            @mkdir($dirExpediente, 0755, true);
        }
        if (!is_dir($dirExpediente)) {
            echo json_encode(self::respuesta(false, 'No se pudo preparar la carpeta del expediente.'));
            return;
        }

        $slug = $slugPorTipo[$tipoNum] ?? ('doc_' . $tipoNum);
        $nombreSeguro = preg_replace('/[^A-Za-z0-9._-]+/', '_', pathinfo($nombreOriginal, PATHINFO_FILENAME));
        $nombreSeguro = trim($nombreSeguro, '._-');
        if ($nombreSeguro === '') {
            $nombreSeguro = $slug;
        }
        $nombreArchivo = $slug . '_manual_' . date('Ymd_His') . '_' . substr(md5($nombreSeguro . microtime(true)), 0, 8) . '.pdf';
        $rutaDestino = $dirExpediente . '/' . $nombreArchivo;
        if (!move_uploaded_file($tmp, $rutaDestino)) {
            echo json_encode(self::respuesta(false, 'No se pudo guardar el PDF en el expediente.'));
            return;
        }

        $rutaRelativa = 'candidatos/' . $idCandidato . '/expediente/' . $nombreArchivo;
        $tipoNombre = $tiposDocumento[$tipoNum];
        $marcaManual = [
            'subida_manual_rrhh' => true,
            'revision_manual' => true,
            'pendiente_revision_manual' => true,
            'id_usuario_rrhh' => (int) ($_SESSION['usuario_id'] ?? 0),
            'fecha_subida_manual' => date('Y-m-d H:i:s'),
            'notas' => ['Documento subido manualmente por Capital Humano.'],
        ];
        $verificacionFiscalJson = $tipoNum === 7 ? json_encode($marcaManual) : null;
        $verificacionCalidadJson = $tipoNum !== 7 ? json_encode($marcaManual) : null;

        $guardar = CandidatosDAO::guardarDocumento($idCandidato, $nombreOriginal, $rutaRelativa, $tipoNombre, null, null, $verificacionFiscalJson, $verificacionCalidadJson);
        if (empty($guardar['success'])) {
            @unlink($rutaDestino);
            echo json_encode(self::respuesta(false, $guardar['mensaje'] ?? 'No se pudo registrar el documento.', null, $guardar['error'] ?? null));
            return;
        }

        CandidatosDAO::registrarSubidaManualDocumentoCandidato(
            $idCandidato,
            $tipoNombre,
            $nombreOriginal,
            $rutaRelativa,
            (int) ($_SESSION['usuario_id'] ?? 0),
            'Subida manual desde modal de documentación'
        );
        CandidatosDAO::updateVerificacionExpediente($idCandidato, null);

        $resDocsActualizados = CandidatosDAO::getDocumentosCandidato($idCandidato);
        $docsActualizados = (!empty($resDocsActualizados['success']) && !empty($resDocsActualizados['datos'])) ? $resDocsActualizados['datos'] : [];
        $metricas = $this->calcularMetricasDocumentosCandidato($docsActualizados, $idCandidato);
        if (!empty($metricas['expediente_completo'])) {
            $this->encolarVerificacionDocumentalCandidato($idCandidato, [$tipoNum], true, 'subida_manual_rrhh');
        }

        echo json_encode(self::respuesta(true, 'Documento subido manualmente al expediente.', [
            'id_candidato' => $idCandidato,
            'tipo_documento' => $tipoNombre,
            'expediente_completo' => !empty($metricas['expediente_completo']),
        ]));
    }

    public function verificarExpedienteCandidato()
    {
        set_time_limit(1200);
        header('Content-Type: application/json; charset=utf-8');
        $id_candidato = (int) ($_GET['id_candidato'] ?? $_POST['id_candidato'] ?? 0);
        if ($id_candidato <= 0) {
            echo json_encode(self::respuesta(false, 'id_candidato inválido.'));
            return;
        }
        $storageRoot = defined('RAIZ') ? (RAIZ . '/storage') : (__DIR__ . '/../storage');
        $rutasParaValidar = ['identificacion_pdf' => null, 'curp' => null, 'nss' => null, 'constancia_fiscal' => null, 'acta_nacimiento' => null];
        $resDocs = CandidatosDAO::getDocumentosCandidato($id_candidato);
        if (!$resDocs['success'] || empty($resDocs['datos'])) {
            echo json_encode(self::respuesta(false, 'No hay documentos para verificar.'));
            return;
        }
        foreach ($resDocs['datos'] as $d) {
            $rutaRel = trim($d['ruta_archivo'] ?? '');
            if ($rutaRel === '' || !is_file($storageRoot . '/' . $rutaRel)) {
                continue;
            }
            $pathAbs = $storageRoot . '/' . $rutaRel;
            $tipo = trim($d['tipo_documento'] ?? '');
            if (in_array($tipo, ['IDENTIFICACIÓN OFICIAL', 'IDENTIFICACION OFICIAL', 'IDENTIFICACIÃ“N OFICIAL'], true)) {
                $rutasParaValidar['identificacion_pdf'] = $pathAbs;
            } elseif ($tipo === 'CURP') {
                $rutasParaValidar['curp'] = $pathAbs;
            } elseif (in_array($tipo, ['NÚMERO DE SEGURIDAD SOCIAL', 'NUMERO DE SEGURIDAD SOCIAL', 'NÃšMERO DE SEGURIDAD SOCIAL'], true)) {
                $rutasParaValidar['nss'] = $pathAbs;
            } elseif ($tipo === 'CONSTANCIA DE SITUACION FISCAL') {
                $rutasParaValidar['constancia_fiscal'] = $pathAbs;
            } elseif ($tipo === 'ACTA DE NACIMIENTO' || $tipo === 'ACTA DE NACIMIENTO Certificada') {
                $rutasParaValidar['acta_nacimiento'] = $pathAbs;
            }
        }
        if (!$rutasParaValidar['identificacion_pdf']) {
            echo json_encode(self::respuesta(false, 'Falta el documento de identificación oficial (PDF con frente y reverso) para poder verificar.'));
            return;
        }
        $soloIdentificacion = $this->docVerificacionPetitorioSoloIdentificacion() || $this->docVerificacionIniSoloIdentificacion();
        if ($soloIdentificacion) {
            $this->docVerificacionQuitarAdjuntosOpcionalesExpediente($rutasParaValidar);
        }
        $ejecutarAsync = !empty($_POST['async']) || !empty($_GET['async']);
        if ($ejecutarAsync && !$soloIdentificacion) {
            $this->encolarVerificacionDocumentalCandidato($id_candidato, [], true, 'reintento_modal');
            echo json_encode(self::respuesta(true, 'Verificacion encolada en segundo plano. La documentacion se actualizara automaticamente.', [
                'verificacion_en_proceso' => true,
            ]));
            return;

            $payloadEnProceso = [
                'verificacion_en_proceso' => true,
                'todo_coincide' => null,
                'foto_rechazada' => false,
                'checks_ok' => 0,
                'checks_totales' => 0,
                'alertas' => ['Verificación automática en proceso. Esta vista se actualizará sola.'],
                'identificacion_frente_score' => null,
                'identificacion_reverso_score' => null,
                'comparaciones' => null,
                'modo_verificacion' => 'completo',
                'error_api' => null,
                'iniciado_en' => date('Y-m-d H:i:s'),
            ];
            CandidatosDAO::updateVerificacionExpediente($id_candidato, json_encode($payloadEnProceso));
            $respuestaAsync = self::respuesta(true, 'Verificación iniciada en segundo plano. La documentación se actualizará automáticamente.', [
                'verificacion_en_proceso' => true,
            ]);
            $jsonRespuesta = json_encode($respuestaAsync);
            header('Content-Length: ' . strlen($jsonRespuesta));
            header('Connection: close');
            echo $jsonRespuesta;
            if (function_exists('fastcgi_finish_request')) {
                fastcgi_finish_request();
            } else {
                while (ob_get_level() > 0) {
                    @ob_end_flush();
                }
                flush();
                if (function_exists('session_write_close')) {
                    session_write_close();
                }
            }
            ignore_user_abort(true);
            if (function_exists('set_time_limit')) {
                @set_time_limit(1200);
            }
            register_shutdown_function(function () use ($id_candidato) {
                try {
                    $this->ejecutarVerificacionBackground((int) $id_candidato, [], true);
                } catch (\Throwable $e) {
                    error_log('CapHum::verificarExpedienteCandidato async error candidato ' . (int) $id_candidato . ': ' . $e->getMessage());
                }
            });
            return;
        }
        if (function_exists('session_write_close')) {
            @session_write_close();
        }
        $candidatoRes = CandidatosDAO::getById($id_candidato);
        $candidato = ($candidatoRes['success'] && !empty($candidatoRes['datos'])) ? $candidatoRes['datos'] : [];
        $nombreCandidatoRegistro = trim(($candidato['nombres'] ?? '') . ' ' . ($candidato['apellidop'] ?? '') . ' ' . ($candidato['apellidom'] ?? ''));
        $docsCache = CandidatosDAO::getDocumentosYVerificacion($id_candidato);
        $payloadCache = $this->expedientePayloadDesdeCacheDocumentos($docsCache['documentos'] ?? [], $nombreCandidatoRegistro, $soloIdentificacion);
        if (is_array($payloadCache)) {
            CandidatosDAO::updateVerificacionExpediente($id_candidato, json_encode($payloadCache));
            echo json_encode(self::respuesta(true, 'Verificación ejecutada con datos ya procesados. Ya puedes ver coincidencias.', ['verificacion_expediente' => $payloadCache]));
            return;
        }
        $resultadoApi = $this->validarExpedienteApi($rutasParaValidar, $nombreCandidatoRegistro);
        if ($resultadoApi === null) {
            echo json_encode(self::respuesta(false, 'No se pudo enviar el expediente a la API.'));
            return;
        }
        if (!empty($resultadoApi['error'])) {
            $alertasErr = ['La verificacion automatica no finalizo por un fallo tecnico de la API. No se considera revision manual; reintente cuando el servicio este disponible.'];
            if ($soloIdentificacion) {
                array_unshift($alertasErr, 'Modo "solo identificación" activo: el fallo puede no reproducirse al verificar con todos los PDFs.');
            }
            $payloadError = [
                'todo_coincide' => null,
                'foto_rechazada' => false,
                'curp_definitivo' => null,
                'checks_ok' => 0,
                'checks_totales' => 0,
                'alertas' => $alertasErr,
                'identificacion_frente_score' => null,
                'identificacion_reverso_score' => null,
                'comparaciones' => null,
                'nombre_ocr' => null,
                'anio_nacimiento' => null,
                'tipo_documento' => null,
                'modo_verificacion' => $soloIdentificacion ? 'solo_identificacion' : 'completo',
                'api_pendiente' => true,
                'error_api' => $resultadoApi['error'],
            ];
            CandidatosDAO::updateVerificacionExpediente($id_candidato, json_encode($payloadError));
            $mensajeUsuario = 'La verificación automática no pudo completarse. El estado quedó como API pendiente; reintente cuando el servicio esté disponible.';
            $mensajeUsuario = 'La verificacion automatica no pudo completarse por un fallo tecnico. Reintente la API cuando el servicio este disponible.';
            echo json_encode(self::respuesta(true, $mensajeUsuario, ['verificacion_expediente' => $payloadError]));
            return;
        }
        $payload = $this->expedientePayloadDesdeApi($resultadoApi, $soloIdentificacion);
        CandidatosDAO::updateVerificacionExpediente($id_candidato, json_encode($payload));
        $msgOk = $soloIdentificacion
            ? 'Verificación (modo prueba: solo identificación) ejecutada. Revise scores; para cruce completo desactive la casilla y vuelva a intentar.'
            : 'Verificación ejecutada. Ya puedes ver los porcentajes y coincidencias.';
        echo json_encode(self::respuesta(true, $msgOk, ['verificacion_expediente' => $payload]));
    }

    /**
     * Abrir/descargar un documento del expediente. Requiere módulo Candidatos.
     * GET: id (id del registro candidato_documento).
     * Sirve desde disco (rápido, con caché) si existe ruta_archivo; si no, desde BD (contenido LONGBLOB).
     */
    public function verDocumentoCandidato($id = null)
    {
        $id_doc = (int) ($id ?? $_GET['id'] ?? 0);
        if ($id_doc <= 0) {
            header('HTTP/1.0 400 Bad Request');
            echo 'ID inválido';
            return;
        }

        $storageRoot = defined('RAIZ') ? (RAIZ . '/storage') : (__DIR__ . '/../storage');

        // Ruta rápida: solo nombre y ruta (sin cargar LONGBLOB). Casi siempre el archivo está en disco.
        $resRuta = CandidatosDAO::getDocumentoRutaSolo($id_doc);
        if ($resRuta['success'] && !empty($resRuta['datos']['ruta_archivo'])) {
            $rutaRel = trim($resRuta['datos']['ruta_archivo']);
            $path = $storageRoot . '/' . $rutaRel;
            if (is_file($path)) {
                $nombre = $resRuta['datos']['nombre_archivo'] ?? 'documento';
                $ext = strtolower(pathinfo($nombre, PATHINFO_EXTENSION));
                $mimes = ['pdf' => 'application/pdf', 'jpg' => 'image/jpeg', 'jpeg' => 'image/jpeg', 'png' => 'image/png', 'doc' => 'application/msword', 'docx' => 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'];
                $mime = $mimes[$ext] ?? 'application/octet-stream';
                $size = filesize($path);
                $mtime = filemtime($path);
                if (ob_get_length()) {
                    ob_clean();
                }
                header('Content-Type: ' . $mime);
                header('Content-Disposition: inline; filename="' . str_replace('"', '\\"', $nombre) . '"');
                header('Content-Length: ' . $size);
                header('Cache-Control: private, max-age=86400'); // 1 día: segunda vez sale de caché del navegador
                header('Last-Modified: ' . gmdate('D, d M Y H:i:s', $mtime) . ' GMT');
                $etag = '"' . md5($path . $size . $mtime) . '"';
                header('ETag: ' . $etag);
                if (isset($_SERVER['HTTP_IF_NONE_MATCH']) && trim($_SERVER['HTTP_IF_NONE_MATCH']) === $etag) {
                    header('HTTP/1.1 304 Not Modified');
                    return;
                }
                readfile($path);
                return;
            }
        }

        // Fallback: documento guardado en BD (contenido LONGBLOB) o archivo no encontrado en disco
        $res = CandidatosDAO::getDocumentoContenidoParaVer($id_doc);
        if (!$res['success'] || empty($res['datos'])) {
            header('HTTP/1.0 404 Not Found');
            echo 'Documento no encontrado';
            return;
        }
        $doc = $res['datos'];
        $nombre = $doc['nombre_archivo'] ?? 'documento';

        if (!empty($doc['contenido'])) {
            $mime = !empty($doc['mime_type']) ? $doc['mime_type'] : 'application/octet-stream';
            if (ob_get_length()) {
                ob_clean();
            }
            header('Content-Type: ' . $mime);
            header('Content-Disposition: inline; filename="' . str_replace('"', '\\"', $nombre) . '"');
            header('Content-Length: ' . strlen($doc['contenido']));
            header('Cache-Control: private, max-age=3600');
            echo $doc['contenido'];
            return;
        }

        $rutaRel = trim($doc['ruta_archivo'] ?? '');
        $path = $storageRoot . '/' . $rutaRel;
        if (!is_file($path)) {
            header('HTTP/1.0 404 Not Found');
            echo 'Archivo no encontrado';
            return;
        }
        $ext = strtolower(pathinfo($nombre, PATHINFO_EXTENSION));
        $mimes = ['pdf' => 'application/pdf', 'jpg' => 'image/jpeg', 'jpeg' => 'image/jpeg', 'png' => 'image/png', 'doc' => 'application/msword', 'docx' => 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'];
        header('Content-Type: ' . ($mimes[$ext] ?? 'application/octet-stream'));
        header('Content-Disposition: inline; filename="' . str_replace('"', '\\"', $nombre) . '"');
        header('Content-Length: ' . filesize($path));
        header('Cache-Control: private, max-age=86400');
        readfile($path);
    }

    /**
     * Eliminar un documento del expediente. Requiere módulo Candidatos.
     * POST JSON o form: id (id del registro candidato_documento), comentario (obligatorio, motivo visible para el candidato por correo).
     */
    public function eliminarDocumentoCandidato()
    {
        header('Content-Type: application/json; charset=utf-8');
        $puedeDocumentalEliminar = self::puedeValidarDocumentalCandidatos();
        $puedeFinalEliminar = self::puedeValidarFinalCandidatos();
        if (!$puedeDocumentalEliminar && !$puedeFinalEliminar) {
            echo json_encode(self::respuesta(false, 'No tienes permiso para rechazar documentos de candidatos.'));
            return;
        }
        $id_doc = 0;
        $comentario = '';
        $ct = $_SERVER['CONTENT_TYPE'] ?? '';
        if (stripos($ct, 'application/json') !== false) {
            $raw = file_get_contents('php://input');
            $body = json_decode($raw, true);
            if (is_array($body)) {
                $id_doc = (int) ($body['id'] ?? 0);
                $comentario = trim((string) ($body['comentario'] ?? ''));
            }
        }
        if ($id_doc <= 0) {
            $id_doc = (int) ($_POST['id'] ?? $_GET['id'] ?? 0);
        }
        if ($comentario === '') {
            $comentario = trim((string) ($_POST['comentario'] ?? ''));
        }
        if ($id_doc <= 0) {
            echo json_encode(self::respuesta(false, 'ID inválido.'));
            return;
        }
        if ($comentario === '') {
            echo json_encode(self::respuesta(false, 'Debe escribir un comentario para el candidato (motivo de la eliminación).'));
            return;
        }
        $lenCom = function_exists('mb_strlen') ? mb_strlen($comentario, 'UTF-8') : strlen($comentario);
        if ($lenCom > 4000) {
            echo json_encode(self::respuesta(false, 'El comentario es demasiado largo.'));
            return;
        }
        $res = CandidatosDAO::getDocumentoById($id_doc);
        if (!$res['success'] || empty($res['datos'])) {
            echo json_encode(self::respuesta(false, 'Documento no encontrado.'));
            return;
        }
        $doc = $res['datos'];
        $idCand = (int) ($doc['id_candidato'] ?? 0);
        $tipoDoc = trim((string) ($doc['tipo_documento'] ?? ''));
        $nombreArch = trim((string) ($doc['nombre_archivo'] ?? ''));
        $idUsuarioRrhh = (int) ($_SESSION['usuario_id'] ?? 0);
        $estatusAntesRechazo = '';
        if ($idCand > 0) {
            $candAntesRes = CandidatosDAO::getById($idCand);
            if ($candAntesRes['success'] && !empty($candAntesRes['datos'])) {
                $estatusAntesRechazo = trim((string) ($candAntesRes['datos']['estatus'] ?? ''));
            }
        }
        $rechazoEnFlujoFinal = $puedeFinalEliminar && in_array($estatusAntesRechazo, ['Pendiente de validacion final', 'Ingreso programado'], true);

        $logRes = CandidatosDAO::registrarEliminacionDocumentoCandidato(
            $idCand,
            $id_doc,
            $tipoDoc !== '' ? $tipoDoc : null,
            $nombreArch !== '' ? $nombreArch : null,
            $comentario,
            $idUsuarioRrhh > 0 ? $idUsuarioRrhh : null
        );
        if (!$logRes['success']) {
            echo json_encode(self::respuesta(false, $logRes['mensaje'] ?? 'No se pudo registrar el motivo. Revise permisos de BD o ejecute la migración de la tabla candidato_documento_eliminacion.', null, $logRes['error'] ?? null));
            return;
        }

        $storageRoot = defined('RAIZ') ? (RAIZ . '/storage') : (__DIR__ . '/../storage');
        $path = $storageRoot . '/' . trim($doc['ruta_archivo'] ?? '');
        CandidatosDAO::eliminarDocumento($id_doc);
        if ($path !== '' && is_file($path)) {
            @unlink($path);
        }
        if ($idCand > 0) {
            CandidatosDAO::updateVerificacionExpediente($idCand, null);
            CandidatosDAO::updateEstatus($idCand, $rechazoEnFlujoFinal ? 'Pendiente de validacion final' : 'Por evaluar');
            CandidatosDAO::invalidateDocumentacionCache($idCand);
        }

        $correoOk = false;
        $correoIntentado = false;
        $candRes = CandidatosDAO::getById($idCand);
        if ($candRes['success'] && !empty($candRes['datos'])) {
            $c = $candRes['datos'];
            $nombreCompleto = trim(implode(' ', [
                $c['nombres'] ?? '',
                $c['segundo_nombre'] ?? '',
                $c['apellidop'] ?? '',
                $c['apellidom'] ?? '',
            ]));
            $destino = trim((string) ($c['email'] ?? ''));
            if ($destino !== '' && filter_var($destino, FILTER_VALIDATE_EMAIL)) {
                $correoIntentado = true;
                $labelTipo = $tipoDoc !== '' ? $tipoDoc : 'Documento';
                $asunto = 'Actualización de su expediente — documento retirado';
                $htmlCom = nl2br(htmlspecialchars($comentario, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'));

                $base = $this->obtenerBaseUrlApp();
                $urlDocumentos = '';
                $resTokDel = CandidatosDAO::getOrCreateTokenDocumentos($idCand);
                if ($resTokDel['success'] && !empty($resTokDel['datos'])) {
                    $urlDocumentos = rtrim($base, '/') . '/CapHum/subirDocumentosCandidato/' . $resTokDel['datos'];
                }

                $diasHabilesCfg = 2;
