    public function guardarAusencia()
    {
        // ðŸ¹ Recibimos JSON
        if (!self::puedeAccionGestion(self::MODULO_GESTION_AUSENCIAS)) {
            self::respuestaJSON([
                'success' => false,
                'mensaje' => 'No tienes permiso para registrar ausencias.'
            ]);
            return;
        }

        $data = json_decode(file_get_contents("php://input"), true);

        // ðŸ¹ Normalizamos idAusencia (puede venir o no)
        $data['idAusencia'] = $data['idAusencia'] ?? null;

        // ðŸ¹ Validaciones obligatorias (NO incluye idAusencia)
        if (
            empty($data['idPersona']) ||
            empty($data['idRazon']) ||
            empty($data['fechaInicio']) ||
            empty($data['fechaFin'])
        ) {
            self::respuestaJSON([
                'success' => false,
                'mensaje' => 'Datos incompletos'
            ]);
            return;
        }

        // ðŸ¹ DAO decide si INSERT o UPDATE
        $resultado = CapHumDAO::guardarAusencia($data);

        self::respuestaJSON($resultado);
    }


    public function getJefeDirecto()
    {
        $input = json_decode(file_get_contents("php://input"), true);
        $idDepartamento = $input['id_departamento'] ?? null;
        $idPuesto = $input['id_puesto'] ?? null;
        $idPersonaActual = (int)($input['id_persona'] ?? 0);
        $soloPersonas = !empty($input['solo_personas']);

        if (!$idDepartamento) {
            self::respuestaJSON([
                'success' => false,
                'mensaje' => 'ID de departamento no recibido'
            ]);
            return;
        }

        // Deduplicar por id de persona (quien tiene dos cargos no debe salir dos veces)
        $deduplicarPorPersona = function ($lista) use ($idPersonaActual) {
            if (!is_array($lista) || empty($lista)) return $lista;
            $vistos = [];
            $out = [];
            foreach ($lista as $row) {
                $id = isset($row['id']) ? (int) $row['id'] : 0;
                if ($idPersonaActual > 0 && $id === $idPersonaActual) {
                    continue;
                }
                if ($id && !isset($vistos[$id])) {
                    $vistos[$id] = true;
                    $out[] = $row;
                }
            }
            return array_values($out);
        };
        $normalizarVacantesJefe = function ($lista) {
            $out = [];
            foreach ((array)$lista as $vacante) {
                $id = (int)($vacante['id'] ?? 0);
                if ($id <= 0) continue;
                $puesto = trim((string)($vacante['nombre_puesto'] ?? 'Vacante'));
                $subs = (int)($vacante['subordinados'] ?? 0);
                $out[] = [
                    'id' => 'vacante:' . $id,
                    'tipo_jefe' => 'vacante',
                    'id_vacante' => $id,
                    'nombre_completo' => 'Vacante - ' . $puesto . ($subs > 0 ? ' (' . $subs . ' subordinado(s))' : ''),
                    'nombre_puesto' => $puesto,
                ];
            }
            return $out;
        };
        $agregarVacantesJefe = function ($personas) use ($idDepartamento, $idPuesto, $normalizarVacantesJefe, $soloPersonas) {
            if ($soloPersonas) {
                return (array)$personas;
            }
            $vacantes = CapHumDAO::getVacantesJefeDirecto($idDepartamento, $idPuesto);
            $datosVacantes = !empty($vacantes['success']) ? $normalizarVacantesJefe($vacantes['datos'] ?? []) : [];
            return array_merge((array)$personas, $datosVacantes);
        };
        $responderPersonasEmpresa = function ($mensaje) use ($deduplicarPorPersona) {
            $personasEmpresa = CapHumDAO::getPersonasActivasEmpresaParaJefe();
            if (!empty($personasEmpresa['success']) && !empty($personasEmpresa['datos'])) {
                self::respuestaJSON([
                    'success' => true,
                    'mensaje' => $mensaje,
                    'datos' => $deduplicarPorPersona($personasEmpresa['datos']),
                    'fallback_empresa' => true
                ]);
                return true;
            }
            return false;
        };

        // 1) Si hay puesto seleccionado: jefes por nivel (mismo departamento, nivel superior)
        if ($idPuesto) {
            $porPuesto = CapHumDAO::getConsultaGestoresPorPuesto($idPuesto);
            if ($porPuesto['success'] && !empty($porPuesto['datos'])) {
                $datos = array_map(function ($row) {
                    return [
                        'id' => $row['id'],
                        'nombre_completo' => $row['nombre_completo'] ?? '',
                        'nombre_puesto' => $row['puesto'] ?? $row['nombre_puesto'] ?? ''
                    ];
                }, $porPuesto['datos']);
                $datos = $deduplicarPorPersona($datos);
                $datos = $agregarVacantesJefe($datos);
                self::respuestaJSON(['success' => true, 'mensaje' => 'Jefes encontrados.', 'datos' => $datos]);
                return;
            }

            $soloVacantes = $agregarVacantesJefe([]);
            if (!empty($soloVacantes)) {
                self::respuestaJSON(['success' => true, 'mensaje' => 'Vacantes encontradas.', 'datos' => $soloVacantes]);
                return;
            }

            if ($responderPersonasEmpresa('El puesto no tiene jefe configurado. Seleccione una persona activa de la empresa.')) {
                return;
            }

            self::respuestaJSON(['success' => true, 'mensaje' => 'Sin jefes disponibles.', 'datos' => []]);
            return;
        }

        // 2) Jefes por es_jefe=1 en el departamento
        $detalles = CapHumDAO::getConsultaJefe($idDepartamento);
        if ($detalles['success'] && !empty($detalles['datos'])) {
            $datos = $deduplicarPorPersona($detalles['datos']);
            $datos = $agregarVacantesJefe($datos);
            self::respuestaJSON(['success' => true, 'mensaje' => $detalles['mensaje'] ?? 'Jefes encontrados.', 'datos' => $datos]);
            return;
        }

        $soloVacantes = $agregarVacantesJefe([]);
        if (!empty($soloVacantes)) {
            self::respuestaJSON(['success' => true, 'mensaje' => 'Vacantes encontradas.', 'datos' => $soloVacantes]);
            return;
        }

        if ($soloPersonas && $responderPersonasEmpresa('No hay jefes persona configurados en el departamento. Seleccione una persona activa de la empresa.')) {
            return;
        }

        // 4) Si no hay jefe real configurado, no inventar uno.
        self::respuestaJSON(['success' => true, 'mensaje' => 'Sin jefes disponibles.', 'datos' => []]);
    }
    public function updateGestorF()
    {
        session_start(); //  IMPORTANTE
        header('Content-Type: application/json; charset=utf-8');

        // Mismo permiso que Gestiones: solo quien tiene Organización - Departamentos (módulo 10) puede editar
        $puedeEditarCompleto = self::puedeAccionGestion(self::MODULO_GESTION_EDITAR_USUARIO);
        $permisosEdicionCobranza = self::permisosEdicionCobranzaSesion();
        $puedeEditarParcial = in_array(true, $permisosEdicionCobranza, true);

        if (!$puedeEditarCompleto && !$puedeEditarParcial) {
            echo json_encode([
                'success' => false,
                'mensaje' => 'No tienes permiso para editar usuarios.'
            ]);
            exit;
        }

        // Leer JSON
        $input = json_decode(file_get_contents("php://input"), true);

        if (!$input || empty($input['id'])) {
            echo json_encode([
                'success' => false,
                'mensaje' => 'Datos incompletos'
            ]);
            exit; //  CLAVE
        }
        $input['usuario_edita'] = $_SESSION['usuario_id'] ?? $_SESSION['id_usuario'] ?? null;

        if (!$puedeEditarCompleto) {
            $input = self::normalizarPayloadEdicionCobranzaParcial($input, $permisosEdicionCobranza);
        }

        $n3e = trim((string) ($input['id_div_nivel3'] ?? ''));
        $n4e = trim((string) ($input['id_div_nivel4'] ?? ''));
        $calleTe = trim((string) ($input['domicilio_calle_texto'] ?? ''));
        $cpe = trim((string) ($input['codigo_postal'] ?? ''));
        $numExte = trim((string) ($input['domicilio_num_exterior'] ?? ''));
        $capturaDome = ($n3e !== '' || $n4e !== '' || $calleTe !== '' || $cpe !== '');
        $validarDomicilioObligatorio = $puedeEditarCompleto || !empty($input['_domicilio_editado_parcial']);
        if ($validarDomicilioObligatorio && $capturaDome && $numExte === '') {
            echo json_encode([
                'success' => false,
                'mensaje' => 'El número exterior es obligatorio cuando captura domicilio (colonia, calle o código postal).',
            ]);
            exit;
        }

        $resultado = CapHumDAO::UpdatePersona($input);
        if (!empty($resultado['success'])) {
            $idPersonaSync = (int)($input['id'] ?? 0);
            $legacySync = $idPersonaSync > 0
                ? LegacyUserSync::sincronizarDesdeEditarUsuario($idPersonaSync, (int)($_SESSION['usuario_id'] ?? $_SESSION['id_usuario'] ?? 0))
                : [
                    'success' => false,
                    'resultado' => 'error',
                    'mensaje' => 'No se pudo confirmar el ID de la persona para sincronizar con Legacy.',
                    'detalle' => null,
                ];
            $datos = is_array($resultado['datos'] ?? null) ? $resultado['datos'] : [];
            $datos['legacy_sync'] = $legacySync;
            $resultado['datos'] = $datos;
            $resultado['legacy_sync'] = $legacySync;
        }

        echo json_encode($resultado);
        exit; //  CLAVE
    }

