    /// ESTA NO SE MUEVE
    public function nivelJerarquicoColaborador($persona_id)
    {
        $persona_id = (int) ($persona_id ?? 0);
        if ($persona_id <= 0) {
            header('Content-Type: application/json');
            echo json_encode(['success' => false, 'mensaje' => 'ID de persona inválido']);
            exit;
        }
        $id_departamento = isset($_GET['id_departamento']) ? (int) $_GET['id_departamento'] : 0;

        // 1ï¸âƒ£ Obtener organigrama desde la DAO (solo personas con puesto en el departamento si se envía)
        $personas = CapHumDAO::getConsultaPersonasJerarquia($persona_id, $id_departamento);

        // ðŸ Debug: verificar qué se está devolviendo
        if (!$personas['success'] || empty($personas["datos"])) {
            header('Content-Type: application/json');
            echo json_encode([
                "success" => false,
                "mensaje" => "No se encontraron datos del organigrama",
                "debug" => $personas
            ]);
            exit;
        }

        $primeraFila = $personas["datos"][0] ?? [];
        $organigramaJson = $primeraFila["organigrama_json"] ?? $primeraFila["ORGANIGRAMA_JSON"] ?? null;

        if ($organigramaJson === null || $organigramaJson === '') {
            header('Content-Type: application/json');
            echo json_encode([
                "success" => false,
                "mensaje" => "organigrama_json está vacío",
                "debug" => $personas["datos"]
            ]);
            exit;
        }

        $organigrama = json_decode($organigramaJson, true);
        if (!is_array($organigrama)) {
            header('Content-Type: application/json');
            echo json_encode(['success' => false, 'mensaje' => 'Datos del organigrama no válidos']);
            exit;
        }

        // 2ï¸âƒ£ Construir filas para el OrgChart (siempre al menos la raíz)
        $rows = [];
        $this->idsYaAgregados = [];
        $id_puesto = isset($_GET['id_puesto']) ? (int) $_GET['id_puesto'] : 0;
        $nombrePuestoRaiz = $organigrama["nombre_puesto"] ?? '';
        if ($id_puesto > 0) {
            $nombrePuestoRaiz = CapHumDAO::getNombrePuesto($id_puesto) ?: $nombrePuestoRaiz;
        }

        $idRaiz = (string)($organigrama["id_jefe"] ?? $persona_id);
        $this->idsYaAgregados[$idRaiz] = true;

        // Raíz del organigrama (evitar null para que el gráfico no falle)
        $rows[] = [
            "id"     => $idRaiz,
            "nombre" => $organigrama["nombre_jefe"] ?? '',
            "puesto" => $nombrePuestoRaiz,
            "jefe"   => null
        ];

        // Subordinados de la raíz (recorrerArbol evita duplicados por id)
        if (!empty($organigrama["subordinados"])) {
            foreach ($organigrama["subordinados"] as $sub) {
                $this->recorrerArbol($sub, $rows, $idRaiz);
            }
        }

        // 3ï¸âƒ£ Devolver JSON
        $idsRows = array_values(array_filter(array_map(function ($r) {
            return isset($r['id']) && is_numeric($r['id']) ? (int)$r['id'] : 0;
        }, $rows)));
        $metaOrg = CapHumDAO::getMetaOrganigrama($idsRows, $id_departamento);
        if (!empty($metaOrg['success']) && !empty($metaOrg['datos'])) {
            $ausencias = $metaOrg['datos']['ausencias'] ?? [];
            foreach ($rows as &$rowOrg) {
                $rid = isset($rowOrg['id']) && is_numeric($rowOrg['id']) ? (int)$rowOrg['id'] : 0;
                if ($rid > 0 && isset($ausencias[$rid])) {
                    $rowOrg['tipo_estado'] = 'ausencia';
                    $rowOrg['estado_label'] = $ausencias[$rid]['razon_nombre'] ?? 'Ausencia';
                }
            }
            unset($rowOrg);

            $idsExistentes = [];
            foreach ($rows as $rOrg) {
                $idsExistentes[(string)($rOrg['id'] ?? '')] = true;
            }
            $vacantesConSubordinadosVisibles = [];
            foreach (($metaOrg['datos']['subordinados_vacante'] ?? []) as $subVac) {
                $idVacanteJefe = (int)($subVac['id_vacante_jefe'] ?? 0);
                $idSubordinado = (string)($subVac['id'] ?? '');
                if ($idVacanteJefe > 0 && $idSubordinado !== '' && !isset($idsExistentes[$idSubordinado])) {
                    $vacantesConSubordinadosVisibles[$idVacanteJefe] = true;
                }
            }
            $vacantesAgregadas = [];
            foreach (($metaOrg['datos']['vacantes'] ?? []) as $vac) {
                $idVacanteReal = (int)$vac['id'];
                if (empty($vacantesConSubordinadosVisibles[$idVacanteReal])) continue;
                $jefeVac = !empty($vac['id_jefe']) ? (string)$vac['id_jefe'] : $idRaiz;
                if (!isset($idsExistentes[$jefeVac])) continue;
                $idVacante = 'vacante-' . $idVacanteReal;
                if (isset($idsExistentes[$idVacante])) continue;
                $idsExistentes[$idVacante] = true;
                $vacantesAgregadas[$idVacanteReal] = $idVacante;
                $rows[] = [
                    'id' => $idVacante,
                    'id_vacante' => $idVacanteReal,
                    'id_departamento' => isset($vac['id_departamento']) ? (int)$vac['id_departamento'] : null,
                    'id_puesto' => isset($vac['id_puesto']) ? (int)$vac['id_puesto'] : null,
                    'id_jefe' => !empty($vac['id_jefe']) ? (int)$vac['id_jefe'] : null,
                    'nombre' => 'Vacante',
                    'puesto' => $vac['nombre_puesto'] ?? 'Sin puesto',
                    'jefe' => $jefeVac,
                    'tipo_estado' => 'vacante',
                    'estado_label' => 'Vacante',
                ];
            }
            foreach (($metaOrg['datos']['subordinados_vacante'] ?? []) as $subVac) {
                $idVacanteJefe = (int)($subVac['id_vacante_jefe'] ?? 0);
                if ($idVacanteJefe <= 0 || !isset($vacantesAgregadas[$idVacanteJefe])) continue;

                $idSubordinado = (string)($subVac['id'] ?? '');
                if ($idSubordinado === '' || isset($idsExistentes[$idSubordinado])) continue;

                $idsExistentes[$idSubordinado] = true;
                $this->idsYaAgregados[$idSubordinado] = true;
                $rows[] = [
                    'id' => $idSubordinado,
                    'nombre' => $subVac['nombre'] ?? '',
                    'puesto' => $subVac['nombre_puesto'] ?? 'Sin puesto',
                    'jefe' => $vacantesAgregadas[$idVacanteJefe],
                ];

                $arbolSubordinado = CapHumDAO::getConsultaPersonasJerarquia((int)$idSubordinado, $id_departamento);
                if (!empty($arbolSubordinado['success']) && !empty($arbolSubordinado['datos'][0])) {
                    $jsonSubordinado = $arbolSubordinado['datos'][0]['organigrama_json'] ?? $arbolSubordinado['datos'][0]['ORGANIGRAMA_JSON'] ?? null;
                    $orgSubordinado = $jsonSubordinado ? json_decode($jsonSubordinado, true) : null;
                    if (is_array($orgSubordinado) && !empty($orgSubordinado['subordinados'])) {
                        foreach ($orgSubordinado['subordinados'] as $subHijo) {
                            $this->recorrerArbol($subHijo, $rows, $idSubordinado);
                        }
                    }
                }
            }
        }

        header('Content-Type: application/json');
        echo json_encode([
            "success" => true,
            "rows"    => $rows
        ]);
        exit;
    }
    private $idsYaAgregados = [];

    private function recorrerArbol($nodo, &$rows, $jefeId = null) {
        $id = (string)($nodo["id"] ?? '');
        if ($id === '') return;
        /* Evitar duplicados por id (misma persona no debe aparecer dos veces en el organigrama) */
        if (isset($this->idsYaAgregados[$id])) return;
        $this->idsYaAgregados[$id] = true;

        $rows[] = [
            "id"     => $id,
            "nombre" => $nodo["nombre"] ?? '',
            "puesto" => $nodo["nombre_puesto"] ?? '',
            "jefe"   => $jefeId
        ];

        if (!empty($nodo["subordinados"])) {
            foreach ($nodo["subordinados"] as $sub) {
                $this->recorrerArbol($sub, $rows, (string)$nodo["id"]);
            }
        }
    }
