    }
    public function getInsertarGestor()
    {
        if (!self::puedeAccionGestion(self::MODULO_GESTION_AGREGAR_USUARIO)) {
            header('Content-Type: application/json; charset=utf-8');
            echo json_encode([
                'success' => false,
                'mensaje' => 'No tienes permiso para agregar usuarios.'
            ]);
            return;
        }

        // Obtener el JSON enviado desde fetch
        $inputJSON = file_get_contents('php://input');
        $data = json_decode($inputJSON, true);

        if (!is_array($data)) {
            echo json_encode(['success' => false, 'mensaje' => 'Solicitud inválida. Envíe un JSON válido.']);
            return;
        }

        // Validaciones básicas (todos los campos de registro obligatorios; id_jefe puede estar vacío si es máximo rango)
        $tipoRegistro = strtolower(trim((string)($data['tipo_registro'] ?? 'persona')));
        if ($tipoRegistro === 'vacante') {
            foreach (['departamento_id' => 'Departamento', 'id_puesto' => 'Puesto'] as $field => $nombre) {
                if (empty($data[$field])) {
                    echo json_encode(['success' => false, 'mensaje' => "El campo \"$nombre\" es obligatorio"]);
                    return;
                }
            }

            $resVacante = CapHumDAO::crearVacantePersonal([
                'id_departamento' => (int)$data['departamento_id'],
                'id_puesto' => (int)$data['id_puesto'],
                'id_jefe' => !empty($data['id_jefe']) ? (int)$data['id_jefe'] : null,
                'origen' => 'manual',
                'creado_por' => $_SESSION['usuario_id'] ?? null,
            ]);

            echo json_encode([
                'success' => !empty($resVacante['success']),
                'mensaje' => $resVacante['mensaje'] ?? (!empty($resVacante['success']) ? 'Vacante registrada correctamente' : 'No se pudo registrar la vacante'),
                'datos' => $resVacante['datos'] ?? null,
                'error' => $resVacante['error'] ?? null,
            ]);
            return;
        }

        $requiredFields = ['nombres', 'apellidop', 'apellidom', 'curp', 'telefono', 'fecha_ingreso', 'id_puesto', 'departamento_id', 'usuario', 'contrasena'];
        $nombresCampos = [
            'nombres' => 'Nombres',
            'apellidop' => 'Apellido paterno',
            'apellidom' => 'Apellido materno',
            'curp' => 'CURP',
            'telefono' => 'Teléfono',
            'fecha_ingreso' => 'Fecha de ingreso',
            'id_puesto' => 'Puesto',
            'departamento_id' => 'Departamento',
            'usuario' => 'Usuario',
            'contrasena' => 'Contraseña'
        ];
        foreach ($requiredFields as $field) {
            if (!array_key_exists($field, $data) || $data[$field] === '' || $data[$field] === null || (is_string($data[$field]) && trim($data[$field]) === '')) {
                $nombre = $nombresCampos[$field] ?? $field;
                echo json_encode([
                    'success' => false,
                    'mensaje' => "El campo \"$nombre\" es obligatorio"
                ]);
                return;
            }
        }

        $curpNorm = strtoupper(preg_replace('/\s+/', '', (string) ($data['curp'] ?? '')));
        if (!OcrIdentidad::validarFormatoCURP($curpNorm)) {
            echo json_encode([
                'success' => false,
                'mensaje' => 'El CURP no tiene un formato válido (18 caracteres estándar).',
            ]);
            return;
        }
        $data['curp'] = $curpNorm;

        // Preparar datos
        $data['contrasena'] = $data['contrasena'];
        $data['id_jefe'] = isset($data['id_jefe']) ? $data['id_jefe'] : null;
        $data['fecha_ingreso'] = $data['fecha_ingreso'];
        $data['asignar_legion'] = isset($data['asignar_legion']) ? (bool)$data['asignar_legion'] : false;
        $data['id_legion'] = isset($data['id_legion']) && !empty($data['id_legion']) ? (int)$data['id_legion'] : null;

        // Validar que si asignar_legion es true, id_legion debe estar presente
        if ($data['asignar_legion'] && !$data['id_legion']) {
            echo json_encode([
                'success' => false,
                'mensaje' => 'Debe seleccionar una legión si marca la opción de asignar legión'
            ]);
            return;
        }

        $n3 = trim((string) ($data['id_div_nivel3'] ?? ''));
        $n4 = trim((string) ($data['id_div_nivel4'] ?? ''));
        $calleT = trim((string) ($data['domicilio_calle_texto'] ?? ''));
        $cp = trim((string) ($data['codigo_postal'] ?? ''));
        $numExt = trim((string) ($data['domicilio_num_exterior'] ?? ''));
        $capturaDom = ($n3 !== '' || $n4 !== '' || $calleT !== '' || $cp !== '');
        if ($capturaDom && $numExt === '') {
            echo json_encode([
                'success' => false,
                'mensaje' => 'El número exterior es obligatorio cuando captura domicilio (colonia, calle o código postal).',
            ]);
            return;
        }

        // Llamar al DAO
        $inserted = CapHumDAO::insertPersona($data);

        if ($inserted['success']) {
            $datos = is_array($inserted['datos'] ?? null) ? $inserted['datos'] : [];
            $idPersona = (int)($datos['id'] ?? 0);
            $legacySync = $idPersona > 0
                ? LegacyUserSync::sincronizarDesdeEditarUsuario($idPersona, (int)($_SESSION['usuario_id'] ?? 0))
                : [
                    'success' => false,
                    'resultado' => 'error',
                    'mensaje' => 'No se pudo confirmar el ID de la persona para sincronizar con Legacy.',
                    'detalle' => null,
                ];
            $datos['legacy_sync'] = $legacySync;

            echo json_encode([
                'success' => true,
                'mensaje' => 'Usuario registrado correctamente',
                'datos' => $datos,
                'legacy_sync' => $legacySync,
            ]);
        } else {
            $mensajeAmigable = $this->interpretarErrorDBPersona((string)($inserted['error'] ?? ''));
            echo json_encode(['success' => false, 'mensaje' => $mensajeAmigable]);
        }
    }

    /**
     * Convierte un mensaje de error de base de datos en un texto amigable para el usuario.
     */
    private function interpretarErrorDBPersona(string $error): string
    {
        // Usuario duplicado
        if (stripos($error, 'uq_persona_user_name') !== false
            || (stripos($error, 'Duplicate entry') !== false && stripos($error, 'user_name') !== false)) {
            return 'El nombre de usuario ya se encuentra registrado. Favor de capturar uno diferente.';
        }
        // Correo duplicado
        if (stripos($error, 'uq_persona_correo') !== false
            || (stripos($error, 'Duplicate entry') !== false && stripos($error, 'correo') !== false)) {
            return 'El correo electrónico ya está registrado en el sistema.';
        }
        // CURP duplicada
        if (stripos($error, 'uq_persona_curp') !== false
            || (stripos($error, 'Duplicate entry') !== false && stripos($error, 'curp') !== false)) {
            return 'La CURP ingresada ya está registrada en el sistema.';
        }
        // Número de empleado duplicado
        if (stripos($error, 'uq_persona_numero_empleado') !== false
            || (stripos($error, 'Duplicate entry') !== false && stripos($error, 'numero_empleado') !== false)) {
            return 'El número de empleado ya está registrado en el sistema.';
        }
        // Entrada duplicada genérica
        if (stripos($error, 'Duplicate entry') !== false || stripos($error, '1062') !== false) {
            return 'Uno de los datos ingresados ya se encuentra registrado. Favor de verificar la información.';
        }
        // Campo obligatorio nulo
        if (stripos($error, 'cannot be null') !== false || stripos($error, '1048') !== false) {
            return 'Favor de completar todos los campos requeridos.';
        }
        // Llave foránea inválida
        if (stripos($error, 'foreign key') !== false || stripos($error, '1452') !== false) {
            return 'Uno de los valores seleccionados no es válido. Verifique la información ingresada.';
        }
        // Error genérico
        return 'Ocurrió un error al registrar el usuario. Favor de verificar la información e intentar nuevamente.';
    }

    public function registrarBaja()
    {
        header('Content-Type: application/json; charset=utf-8');

        // âš ï¸ Al usar FormData NO se usa php://input
        if (!self::puedeAccionGestion(self::MODULO_GESTION_DAR_BAJA)) {
            echo json_encode([
                'success' => false,
                'message' => 'No tienes permiso para dar de baja usuarios. Requiere el permiso especial Capital Humano > Dar de baja; Control de Bajas solo permite consultar el panel.'
            ]);
            return;
        }

        $idGestor    = $_POST['idGestor'] ?? null;
        $motivo      = $_POST['motivo'] ?? null;
        $descripcion = $_POST['descripcion'] ?? null;
        $modoReasignacion = $_POST['modo_reasignacion'] ?? 'sin_subordinados';
        $sustitutoId = $_POST['sustituto_id'] ?? null;
        $subordinadosSeleccionadosRaw = $_POST['subordinados_seleccionados'] ?? '[]';
        $subordinadosSeleccionados = json_decode($subordinadosSeleccionadosRaw, true);
        if (!is_array($subordinadosSeleccionados)) $subordinadosSeleccionados = [];
        $asignacionesJefeRaw = $_POST['asignaciones_jefe'] ?? '{}';
        $asignacionesJefe = json_decode($asignacionesJefeRaw, true);
        if (!is_array($asignacionesJefe)) $asignacionesJefe = [];
        $vacanteExistenteId = $_POST['vacante_existente_id'] ?? null;

        //  Validaciones obligatorias
        if (empty($idGestor)) {
            echo json_encode([
                'success' => false,
                'message' => 'ID del gestor es obligatorio'
            ]);
            return;
        }

        if (empty($motivo)) {
            echo json_encode([
                'success' => false,
                'message' => 'El motivo de baja es obligatorio'
            ]);
            return;
        }

        if (empty(trim($descripcion))) {
            echo json_encode([
                'success' => false,
                'message' => 'La descripción de la baja es obligatoria'
            ]);
            return;
        }

        // ðŸ“Ž MANEJO DE MÃšLTIPLES PDFs (MIME real, nombre seguro, 0755)
        $rutasPDF = [];

        if (!empty($_FILES['archivosPDF']['name'][0])) {

            $directorio = sparta_uploads_join('bajas') . DIRECTORY_SEPARATOR;
            SecureUpload::ensureDir($directorio);

            foreach ($_FILES['archivosPDF']['tmp_name'] as $i => $tmp) {

                if ($_FILES['archivosPDF']['error'][$i] !== UPLOAD_ERR_OK) {
                    continue;
                }

                if (!SecureUpload::validateMime($tmp, SecureUpload::MIME_PDF)) {
                    continue;
                }

                $nombreFinal = SecureUpload::generateSafeFilename('pdf');
                $rutaFinal   = $directorio . $nombreFinal;

                if (move_uploaded_file($tmp, $rutaFinal)) {
                    $rutasPDF[] = $nombreFinal;
                }
            }
        }

        // ðŸ“¦ Preparar datos para el DAO
        $data = [
            'id_gestor'   => $idGestor,
            'motivo'      => $motivo,
            'descripcion' => $descripcion,
            'archivos'    => $rutasPDF, // ï¿½Ë† ahora es un arreglo
            'fecha_baja'  => date('Y-m-d H:i:s'),
            'usuario_baja' => $_SESSION['usuario_id'],
            'modo_reasignacion' => $modoReasignacion,
            'sustituto_id' => $sustitutoId,
            'subordinados_seleccionados' => $subordinadosSeleccionados,
            'asignaciones_jefe' => $asignacionesJefe,
            'vacante_existente_id' => $vacanteExistenteId
        ];

        //  Llamar al modelo / DAO
        $resultado = CapHumDAO::registrarBajaGestor($data);

        if ($resultado['success']) {
            echo json_encode([
                'success' => true,
                'datos' => $resultado['datos'] ?? null,
                'message' => 'La baja se registró correctamente'
            ]);
        } else {
            echo json_encode([
                'success' => false,
                'message' => $resultado['mensaje'] ?? 'Error al registrar la baja',
                'error'   => $resultado['error'] ?? null
            ]);
        }
        exit;
    }

    /**
     * Registrar reingreso: persona que estaba de baja vuelve a la plantilla (estatus Activo).
     * POST: id_gestor, motivo_reingreso, descripcion_reingreso, archivosPDF[]
     * La fecha de reingreso se asigna en el backend (momento del registro).
     */
    public function registrarReingreso()
    {
        header('Content-Type: application/json; charset=utf-8');

        $idGestor = $_POST['id_gestor'] ?? null;
        $motivo = trim($_POST['motivo_reingreso'] ?? '');
        $descripcion = trim($_POST['descripcion_reingreso'] ?? '');

        if (empty($idGestor)) {
            echo json_encode(['success' => false, 'message' => 'Falta el ID del gestor']);
            return;
        }
        if (empty($motivo)) {
            echo json_encode(['success' => false, 'message' => 'Debes seleccionar un motivo de reingreso']);
            return;
        }
        if (empty($descripcion)) {
            echo json_encode(['success' => false, 'message' => 'Debes escribir la descripción del reingreso']);
            return;
        }

        $rutasPDF = [];
        // Aceptar tanto 'archivosPDF' como 'archivosPDF[]' (según cómo PHP reciba el FormData)
        $files = $_FILES['archivosPDF'] ?? $_FILES['archivosPDF[]'] ?? null;
        if ($files && !empty($files['name'])) {
            $directorio = sparta_uploads_join('reingresos') . DIRECTORY_SEPARATOR;
            SecureUpload::ensureDir($directorio);
            $names = is_array($files['name']) ? $files['name'] : [$files['name']];
            $tmpNames = is_array($files['tmp_name']) ? $files['tmp_name'] : [$files['tmp_name']];
            $errors = is_array($files['error']) ? $files['error'] : [$files['error']];
            foreach ($names as $i => $name) {
                if (empty($name) || ($errors[$i] ?? UPLOAD_ERR_OK) !== UPLOAD_ERR_OK) continue;
                $tmp = $tmpNames[$i] ?? '';
                if (!is_uploaded_file($tmp) || !SecureUpload::validateMime($tmp, SecureUpload::MIME_PDF)) continue;
                $nombreFinal = SecureUpload::generateSafeFilename('pdf');
                $rutaFinal = $directorio . $nombreFinal;
                if (move_uploaded_file($tmp, $rutaFinal)) {
                    $rutasPDF[] = $nombreFinal;
                }
            }
        }

        // Fecha de reingreso en hora CDMX (America/Mexico_City)
        $tz = new \DateTimeZone('America/Mexico_City');
        $now = new \DateTime('now', $tz);
        $fechaReingresoSql = $now->format('Y-m-d H:i:s');

        $data = [
            'id_gestor' => $idGestor,
            'motivo_reingreso' => $motivo,
            'descripcion_reingreso' => $descripcion,
            'fecha_reingreso' => $fechaReingresoSql,
            'usuario_reingreso' => (string)($_SESSION['usuario_id'] ?? $_SESSION['usuario'] ?? 'sistema'),
            'archivos' => $rutasPDF
        ];

        $resultado = CapHumDAO::registrarReingresoGestor($data);

        if ($resultado['success']) {
            echo json_encode(['success' => true, 'message' => $resultado['mensaje'] ?? 'Reingreso registrado correctamente']);
        } else {
            $msg = $resultado['mensaje'] ?? 'Error al registrar el reingreso';
            if (!empty($resultado['error'])) {
                $msg .= ' Detalle: ' . $resultado['error'];
            }
            echo json_encode([
                'success' => false,
                'message' => $msg,
                'error' => $resultado['error'] ?? null
            ]);
        }
    }

    /**
     * Elimina por completo un usuario/persona del sistema (y sus datos relacionados).
     */
    /**
     * Consultar dependencias de una persona antes de eliminarla
     * Ãštil para saber qué tablas tienen referencias a esta persona
     */
    public function consultarDependenciasPersona()
    {
        $input = json_decode(file_get_contents('php://input'), true);
        $id = isset($input['idPersona']) ? (int) $input['idPersona'] : 0;
        if ($id < 1) {
            self::respuestaJSON(['success' => false, 'mensaje' => 'ID de persona inválido.']);
            return;
        }
        // Usar el método de consulta (confirmar = false)
        $resultado = CapHumDAO::eliminarPersonaSeguro($id, false);
        self::respuestaJSON($resultado);
    }

    /**
     * Eliminar persona de forma segura (elimina todas las dependencias primero)
     */
    public function eliminarPersonaCompleto()
    {
        $input = json_decode(file_get_contents('php://input'), true);
        $id = isset($input['idPersona']) ? (int) $input['idPersona'] : 0;
        if ($id < 1) {
            self::respuestaJSON(['success' => false, 'mensaje' => 'ID de persona inválido.']);
            return;
        }
        $resultado = CapHumDAO::eliminarPersonaCompleto($id);
        if ($resultado['success']) {
            self::respuestaJSON(['success' => true, 'mensaje' => $resultado['mensaje'] ?? 'Usuario eliminado del sistema.']);
        } else {
            self::respuestaJSON(['success' => false, 'mensaje' => $resultado['mensaje'] ?? 'Error al eliminar.', 'error' => $resultado['error'] ?? null]);
        }
    }

